window.__D("text/likkutei-sichot/c139",{"p":[[1300211133,"ובקדש הקדשים\" (און דערנאך זאגט די מכילתא דעם ק\"ו „ומה אם אבנים כו'\"):\nאבער רש\"י, בהתחלת פירושו, וואו ער איז מסביר דעם פסוק, איז מפרש: „שע\"י המעלות אתה צריך להרחיב פסי־עותיך, ואע\"פ שאינו גילוי ערוה ממש שהרי כתיב10 ועשה להם מכנסי בד מ\"מ הרחבת הפסיעות קרוב לגילוי ערוה הוא ואתה נוהג בהם מנהג בזיון\".\nדאס וואס דער ק\"ו הנ\"ל קומט אין מכילתא גלייך נאך דעם מיעוט „עליו אי אתה פוסע פסיעה גסה אבל אתה פוסע כו' בהיכל ובקדש הקדשים\" — איז י\"ל אז דערמיט ווערט באווארנט וואס מ'קען פרעגן:\nדער איסור פון „לא תגלה ערותך עליו\" („לא תנהג בהם מנהג בזיון\") איז לכאורה ניט מצד די אבני מזבח מצ\"ע, נאר צוליב דעם וואס זייענדיק א טייל פון מזבח (ומקדש) איז דאס (אן ענין פון קדושת ויראת המזבח וואס איז) פאר־בונדן מיט כבוד השם, וואס איז שורה אויפן מזבח (ומקדש)11\n[ע\"ד ווי די מצוה פון מורא מקדש בכלל, וואס „לא מן המקדש אתה ירא אלא ממי ששכן שכינתו במקום הזה\"12, ובלשון החינוך13 אז דאס איז „לקבוע בנפשותינו יראת המקום ב\"ה וחשיבותו וע\"כ הוזהרנו שלא לנהוג שם קלות ראש בשום ענין\"],\nהיינט ווי קען מען פון די „אבנים\"14 אפלערנען א ק\"ו בנוגע „חבירך\", ווי־באלד אז ביי די „אבנים\" איז דא א קדושה וואס איז ניטא ביי „חברך\"?\nוויבאלד אבער אז מ'האט פריער אפגעלערנט „עליו אי אתה פוסע פסיעה גסה אבל אתה פוסע פסיעה גסה בהיכל ובקדש הקדשים\"\n[וואס לפי קס\"ד הנ\"ל, אז דאס איז פארבונדן מיט כבוד המקדש וכו', וואלט דער איסור פון „פסיעה גסה\" גע־דארפט חל זיין אויך15 בהיכל ובקדש הקדשים, ואדרבה נאך שטארקער — מיט א כל־שכן וק\"ו, היות זיי זיינען דאך חמורין מן המזבח]16\nאיז דערפון מובן אז דער איסור „ולא תעלה גו'\" איז ניט (בלויז) צוליב דעם וואס דאס איז א חלק פון דעם מקדש נאר (בעיקר) מצד די אבני המזבח עצמן; ובמילא קען מען פון דעם אפלערנען א ק\"ו „ומה אם אבנים שאין בהם דעת לא לרעה ולא לטובה אמר הקב\"ה לא תנהג",[["10","10","תצוה כח, מב."],["11","11","בלשון הרמב\"ן סוף פרשתנו: וטעם המעלות יראת המזבח והדורו לכבוד השם. ובאברבנאל: וכ\"ז צוה ליראת המקדש כי הוא כבודו יתברך."],["12","12","ספהמ\"צ להרמב\"ם מ\"ע כא. וראה יבמות ו, רע\"ב. רמב\"ם רפ\"ז מהלכות ביהב\"ח."],["13","13","מצוה מא."],["14","14","להעיר מפי' מושב זקנים עה\"ת כאן: קצת קשה למה הקפיד על כבוד המזבח יותר מכל כלי המקדש."],["15","15","להעיר שכ\"ה במכילתא דרשב\"י: כשתעלה למזבח לא תהא פוסע פסיעה גסה כו' אין לי אלא למזבח לעזרות מנין ת\"ל כו'. ושם: יכול לא יעשה מעלות [להיכל ולעזרות תל' לו' ולא] תעלה במעלות כו' למזבח אי אתה עושה כו'."],["16","16","במרכבת המשנה למכילתא כאן מפרש שהק\"ו במכילתא חוזר לשיטת ת\"ק לפנ\"ז שהאיסור הוא מצד גילוי ערוה. והמיעוט „עליו אי אתה פוסע פסיעה גסה אבל אתה פוסע פסיעה גסה בהיכל כו'\" הוא דעת ר\"י שם שלדעתו אינו גילוי ערוה אלא ש„בעודו הולך למזבח טוען אברים ופדרים ודם אצל המזבח יהי' נראה עליו המצוה כמשאוי\". ולכן בהיכל וקדה\"ק „שקדושתן רבה . . יפסע פסיעה גסה כאדם בהול בל יזון עינו מזיו השכינה\". אבל מזה שגם לר\"י הלימוד הוא מסיום הכתוב „אשר לא תגלה ערותך עליו\" וכן מלשון המכילתא „פסיעה גסה\" (לא „יתירה\" כבילק\"ש), משמע, שגם לדעתו שייך זה לגילוי ערוה."]]],[1300211134,"בהם (אין די אבנים גופא) מנהג בזיון, חבירך כו' דין הוא שלא תנוג בו מנהג בזיון\".\nג. עפ\"ז וועט מען אויך פארשטיין פארוואס רש\"י איז מוסיף17 בפירושו די ווערטער „אמרה תורה הואיל ויש בהם צורך לא תנהג בהם מנהג בזיון\":\nוויבאלד אז אין פרש\"י ווערט ניט דערמאנט דער מיעוט „עליו אי אתה פוסע כו' אבל אתה פוסע בהיכל וקדש קדשים\"18, פון וועלכן מען ווייס אז דער\nאיסור פון „ולא תעלה במעלות\" איז פארבונדן מיט אבני מזבח מצ\"ע, כנ\"ל — מוז רש\"י מדגיש זיין דעם ענין אין דעם ק\"ו גופא:\n„הואיל ויש בהם צורך\": וויבאלד אז אין „אבנים הללו\" (פון מזבח) איז דא אן ענין מיוחד — „יש בהם צורך\" — וואס דאס ברענגט דעם איסור פון „לא תעלה במעלות אשר לא תגלה ערותך עליו\"19 —\nאויף די אבני המזבח כשלעצמם (ניט דערפאר וואס זיי זיינען א טייל פון כללות המקדש, נאר) „הואיל ויש בהם צורך\":\nועפ\"ז מובן בפשטות וואס מען געפינט ניט קיין איסור צו מאכן „מעלות\" אין (אנדערע טיילן פון) מקדש (אע\"פ וואס דורך דעם „תגלה ערותך\") — ואדרבה: עס זיינען געווען „מעלות\" אַרויפצוגיין צום (אולם) היכל20 — ווייל בא די אבנים פון די „מעלות\" איז ניטא דער „יש בהם צורך\".\nד. דער ביאור בזה:\nדאס וואס מען לערנט אפ פון „אבני",[["17","17","הכרחו של רש\"י בכלל להביא הלימוד דהק\"ו (שלכאורה הוא רק לימוד מהכתוב ואינו נוגע בפשש\"מ), י\"ל שהוא מזה שהכתוב מוסיף הטעם „אשר לא תגלה ערותך עליו\", שהוא לא רק מיותר בפשש\"מ (כמ\"ש בדבק טוב כאן ובבאר מים חיים בפסוק כב), כ\"א שעפ\"ז יוקשה מה שדוקא במזבח נאמר „ולא תעלה במעלות\", ולטעם זה צ\"ל האיסור ד„לא תעלה במעלות\" בכל המקדש (והרי מצינו מעלות במקדש גופא גם לפנים ממקום המזבח, לפני האולם (וההיכל) — ראה מדות פ\"ג מ\"י. רמב\"ם הל' בית הבחירה פ\"ו ה\"ד־ה). משא\"כ באם הי' נאמר האיסור בלא טעם לא הי' בזה שום קושיא, כי ריבוי ציוורים לא נאמר בהם טעם. ומזה מוכח בפשש\"מ שהטעם שבכתוב — ללמד דבר חדש בא: ק\"ו לבזיון האדם (ועד\"ז י\"ל במה שכתב רש\"י „הרי דברים ק\"ו\" בפסוק לפנ\"ז כ, כב)."],["18","18","ולהעיר שבפרש\"י בכלל לא נזכר ע\"ד האיסור דפסיעה גסה (הרחבת הפסיעות) על המזבח כבמכילתא (רק מפרש שזהו הטעם ד„אשר לא תגלה ערותך עליו — שע\"י המעלות אתה צריך להרחיב פסיעותיך\")*. ויתרה מזה — יש מפרשים שמפרשי בד\"ה ולא תעלה במעלות „כשאתה בונה כבש למזבח לא תעשה מעלות כו'\", משמע שאין האיסור בעלי' רק בעשי' (באר מים חיים). וראה ראם ושפ\"ח ועוד (ולא כמ\"ש בספר הזכרון)). *) ולהעיר שהרמב\"ם בספר היד (הל' בית הבחירה פ\"א הי\"ז) לא כתב האיסור דפסיעה גסה, רק „והעולה במעלות על המזבח לוקה\". אבל כתבו בספר המצות מל\"ת פ, חינוך מצוה מא. ראה מל\"מ ויעב\"ץ לרמב\"ם שם. מנ\"ח שם. ולהעיר גם מהשינויים בלשון הרמב\"ם: במנין המצות בריש ספר היד כותב „שלא לפסוע על המזבח\", משא\"כ בהכותרת להל' ביהב\"ח: שלא לעלות עליו במעלות. ובסהמ\"צ שם: שהוזהרנו מעלות על המזבח במעלות כדי שלא יפסיע פסיעה גסה . . וכל מי שמפסיע פסיעה גסה על המזבח . . לוקה. ואכ\"מ"],["19","19","ועפ\"ז יל\"פ גם שינוי הלשון במכילתא „ומה אם אבנים\", וברש\"י — „אבנים הללו\": להמכילתא הלימוד הוא מזה שאין לנהוג מנהג בזיון באבנים כי באבנים שבכבש המזבח אין ענין מיוחד, ואדרבה צריך לימוד מיוחד למעט אבני ההיכל וקדה\"ק; משא\"כ לרש\"י ישנו ענין מיוחד באבנים אלו שלכן למדים „מאבנים הללו\"."],["20","20","אבל מהמעלות בשאר המקומות (מן החיל לעזרת נשים; מעזרת נשים לעזרת ישראל; מעזרת ישראל לעזרת כהנים — רמב\"ם הל' ביהב\"ח רפ\"ו) אין קושיא כ\"כ, כי הם מחוץ למקום המזבח והם מקומות שגם זר מותר ליכנס לשם (ראה כלים פ\"א מ\"ח ואילך. רמב\"ם שם הט\"ז ואילך)."]]],[1300211135,"מזבח\" אז מען טאר ניט מבזה זיין א צווייטן אידן\n— דלכאורה תמוה: צי דען דארף מען דערביי אנקומען צו א ק\"ו פון אבני מזבח?! —\nאיז ווייל דא, ביי אבני מזבח, רעדט זיך ניט וועגן א בזיון כפשוטו, נאר בלויז (בלשון המכילתא ורש\"י) — „מנהג בזיון\"21. סיי מצד די אבנים — וואס זיי פילן ניט קיין בזיון (וואָרום דער הרגש הבזיון איז אן ענין עקרי אין בזיון, ביז אז לויט איין סברא אין גמרא22, איז דער גאנצער חיוב פון בושת דוקא ווען עס איז פאראן „כיסופא\": אויב אבער „ביישו ישן ומת\", וואס דער צווייטער האט קיינמאל ניט געפילט די בושה, איז מען פטור);\nאון סיי מצד דעם מעשה הבזיון: דא רעדט זיך ניט וועגן א הנהגה פון קלות ראש23, וואָרום קלות ראש ובזיון ממש איז אסור בכל שטח המשכן והמקדש24: נאר דא רעדט זיך בלויז „מנהג בזיון\" — א מעשה וואס קען אויסגע־טייטשט ווערן ווי אן ענין של בזיון. און ווי רש\"י זאגט, אז ביי „עולה במעלות\" דא איז ניטא קיין „גלוי ערוה ממש\", נאר „קרוב לגלוי ערוה\"25.\nאון דערפון לערנט מען אפ לגבי חבירו, אז עס טאר ניט זיין א מעשה וואס איז בלויז א „מנהג בזיון\", און אפילו ווען דער צווייטער פילט דערביי ניט קיין בושה ובזיון.\nה. און אין דעם איז דער חילוק צווישן דער מכילתא און רש\"י: אין וואס באשטייט דער איסור:\nלדעת המכילתא באשטייט דער איסור אין פעולת האדם — מען טאר אפילו ניט טאן א מעשה וואס איז (ניט קיין מעשה בזיון, נאר) בלויז א „מנהג בזיון\".\nרש\"י — פשט — קען אזוי ניט לערנען, וואָרום לפי זה איז ניטא קיין טעם צו מחלק זיין צווישן אבני מזבח און אבני ההיכל. דערפון וואס דער איסור איז דוקא ביי אבני מזבח איז פאר־שטאנדיק, אז מצד פעולת האדם אליין וואלט קיין איסור ניט געווען (וואָרום דא איז ניט געווען קיין אמת'ער מעשה בזיון)26;\nנאר ביי די אבני מזבח איז דא אן ענין מיוחד — „הואיל ויש בהם צורך\" — וואס מצד דעם איז דער „מנהג בזיון\" גורם א מעין „כיסופא\"27 ביי די וואס דארפן אנקומען צו די אבנים (כדלקמן), ובמילא איז עס אסור.\nו. די הסברה בזה:\nמיט „הואיל ויש בהם צורך\" מיינט רש\"י צו זאגן, אז די כהנים קענען ניט טאן זייער עבודה אויפן מזבח נאר סיידן דורך זייער עולה זיין ארויפשטייגן אויף די אבנים; און דאס איז דער טעם פון „לא תנהג בהם מנהג בזיון\", ווייל דורך נוהג זיין א מנהג בזיון בשייכות צו די",[["21","21","להעיר מנזיר (מה, א): הרי אמרה תורה לא תעלה במעלות על מזבחי ק\"ו לדרך בזיון. וראה רש\"י שם."],["22","22","ב\"ק פו, ב."],["23","23","כדפי' בספורנו כאן."],["24","24","ראה ברכות נד, א. רמב\"ם הל' ביהב\"ח פ\"ז ה\"ב."],["25","25","וגם מצדו לא נתכוין לענין של בזיון. ולהעיר שאין המבייש חייב על הבושת עד שיתכוון (משנה ב\"ק שם)."],["26","26","ולכן גם להסברא בגמ' (ב\"ק שם) „משום זילותא הוא\", „שמזלזל בו בפני רבים ואף על פי שאינו שם על לבו\" (רש\"י שם) — אין כאן „זילותא\", כיון שאין כאן מעשה בזיון (ממש), רק „קרוב לגלוי ערוה\", כנ\"ל."],["27","27","ראה ב\"ק שם."]]],[1300211136,"אבני המזבח, איז מען בדרך ממילא אויך מבזה די כהנים וואס דארפן אנקומען צו די אבנים28.\nבדוגמת (ולא ממש) ווי עס שטייט אין ראשונים29 (לגבי חיוב תשלומין פון בושת), אז דער דין רקק בבגדו פטור30 איז דוקא ווען דער מתבייש האט בשעת מעשה דעם בגד ניט געטראגן: אויב אבער ער איז דאן (בעת הרקיקה) געווען אנגעטאן אין דעם בגד, איז דער רוקק חייב — ווייל דורכן שפייען אויפן בגד האט ער מבזה געווען דעם מענטשן וואס איז געווען אנגעטאן אין בגד31.\n[משא\"כ די מעלות פארן היכל — איז „אין בהם צורך\", ווייל: א) מען קען אנקומען אין היכל ניט דורך די מעלות32. ב) די מעלות זיינען געווען ניט לפני ההיכל וואו די עבודה איז געטאן געווארן, נאר לפני האולם33, קומט במילא אויס, אז די הליכת הכהנים צום היכל דורך די מעלות שלפני האולם איז ניט קיין חלק און „צורך\" פון זייער עבודה בהיכל (משא\"כ ביים מזבח איז דאך דער כבש מזבח א טייל פון מזבח גופא34, ביז אז דער פסוק זאגט „ולא תעלה במעלות על מזבחי35 אשר לא\nתגלה ערותך עליו\" — אז ארויפגאנג אויף די מעלות (אדער כבש) צום מזבח ווערט גערעכנט ווי ער איז אויפן מזבח גופא36].\nאון דערפון לערנט מען ארויס אויך לגבי בזיון חבירו: אפילו ווען דאס איז נאר אן ענין פון „מנהג בזיון\", וואס האט ביי „חבירך\" ניט געשאפן קיין בזיון ובושה בפועל — אעפ\"כ, וויבאלד אז „הוא בדמות יוצרך\", קומט אויס, אז מיטן מנהג בזיון לגבי חבירו איז עס אן ענין פון בזיון כלפי יוצרך (ע\"ד ווי ביים איסור „לא תעלה במעלות על מזבחי\", וואס דער „מנהג בזיון\" בשייכות צו די אבנים ברענגט א בזיון פאר די כהנים).\nז. עפ\"ז וועט מען אויך פארשטיין לשון רש\"י ביים זאגן דעם ק\"ו — „ומה אבנים הללו שאין בהם דעת להקפיד על בזיונן אמרה תורה הואיל ויש בהם צורך לא תנהג בהם מנהג בזיון, חברך שהוא בדמות יוצרך ומקפיד על בזיונו על אחת כמה וכמה\" (ניט ווי אין מכילתא, וואו עס שטייט ניט דער לשון „להקפיד על בזיונן\" און „מקפיד על בזיונו\") — דער־מיט איז רש\"י מסביר:\nמה־דאך ביי „אבנים הללו שאין בהם דעת להקפיד על בזיונן\" — ובמילא איז ביי זיי איבערהויפט ניטא דער (עיקר) גדר פון בזיון37 (וואָרום אויב ס'איז ניט קיין הקפדה אויפן בזיון, איז מען דאך ניט נתבזה געווארן), אעפ\"כ, מצד דערויף וואס „יש בהם צורך\" צו די כהנים, ווערט עס פאררעכנט ווי א מנהג בזיון,",[["28","28","או י\"ל ד„יש בהם צורך\" היינו לכל ישראל, ועפ\"מ שפירש רש\"י בפסוק שלפנ\"ז (כ, כב) שהמזבח נברא להאריך ימיו של אדם . . שהמזבח מטיל שלום בין ישראל לאביהם שבשמים."],["29","29","מאירי כתובות (סו, א) בשם קצת מפרשים."],["30","30","ב\"ק צא, א. כתובות שם."],["31","31","„וכן בהמתו אם הי' רכוב עלי' אף הוא מתבייש בכך\" (מאירי שם)."],["32","32","אף שאי\"ז דרך ביאה."],["33","33","ואין קדושתם כקדושת היכל — ראה יומא מד, ב. ובפרש\"י שם."],["34","34","רלב\"ג כאן ד\"ה השרש הג'. וראה רמב\"ם הל' ביהב\"ח פ\"א הט\"ו־טז. המפרש לתמיד כח, א. ותוי\"ט שם. ובכ\"מ."],["35","35","ולא „אל מזבחי\"."],["36","36","וי\"ל דהוי כמו בשעת עבודה — ראה תוס' ישנים יומא כב, א (ד\"ה בזמן)."],["37","37","כי בנדו\"ד לולי העניין ד(מעין) כיסופא, אין כאן גדר בזיון כלל, גם לא „זילותא\" (כנ\"ל הערה 26)."]]],[1300211137,"איז על אחת כמה וכמה אז מען טאר ניט נוהג זיין מנהג בזיון לגבי „חברך\" — (א) „שהוא בדמות יוצרך\", די שייכות צווישן אים מיט „יוצרך\" איז ישיר וניכר (ניט ווי אבני מזבח און כהנים וואס האבן צווישן זיך ניט קיין שייכות בדמותם וכו'): און (ב) „ומקפיד על בזיונו\" — ובמילא איז אויך מצד אים גופא קען זיין א מציאות פון בזיון (משא\"כ ביי אבני מזבח ביי וועלכע ס'איז איבערהויפט ניטא קיין בזיון מצד האבנים עצמן)38.\nח. פירוש רש\"י על התורה איז דאך יינה של תורה. איז יש לומר, אז אין דעם פירוש רש\"י בסיום הפרשה — וואס „הכל הולך אחר החיתום\"39 — איז מרומז דער עיקר ותוכן פון כללות הסדרה — דער ענין פון מתן תורה — עשרת הדברות:\nכשם ווי די עשרת הדברות זיינען כולל ניט נאר די דברות פון אנכי ה\"א און לא יהי' לך (די העכסטע ענינים אין אחדות השם), נאר אויך די דברות האחרונים וואס זיינען דברים פשוטים, ביז צו ענינים הכי פשוטים בין אדם לחבירו („לא40 תרצח לא תנאף גו' כל אשר לרעך\"),\nאיז אזוי אויך אין פירוש רש\"י — תורה שבע\"פ — אין דער סוף פון פ' יתרו, ווי עס דארף זיין די זהירות בתכלית אין ענינים פשוטים פון הנהגות בין אדם לחבירו, ביז צו זיין אויסגעהיט אפילו פון „מנהג בזיון\".\nאון כשם ווי די דברים פשוטים אין די עשרת הדברות זיינען ניט קיין באזונ־דער זאך פון די ערשטע דברות, נאר ווי ערקלערט בכמה מקומות41, אז דאס וואס מען האט די זאכן אריינגעשטעלט אין די עשרת הדברות איז אויך צו לערנען אז זיי זיינען אין ענין מיט „אנכי ה' אלקיך\": אויך די דברים שבין אדם לחבירו זיינען באמת „בין אדם למקום\", מען דארף זיין נזהר אין זיי ווייל דאס איז דער רצון ה',\nאיז אויך רש\"י מוסיף, אז די זהירות כלפי חבירך איז דערפאר וואס ער איז „בדמות יוצרך\": די שייכות האיסור צו „בין אדם למקום\" איז ניט נאר מצד דעם ציווי (אז מען דארף זיין נזהר אין די ענינים מצד ציווי ה'), נאר אויך ווייל „חבירך\" און „מקום\" זיינען איין דמות, כביכול; און דעריבער, איז דער ניט זיין נזהר בכבוד חבירך, הייסט א ניט־זהירות אין כבוד הקב\"ה.\nומרובה מדה טובה כו' — אז אהבת ישראל, ביז צו אן אהבה בלתי מוגבלת וואס ברענגט צו א הנהגה פון מכבד זיין חבירך בתכלית הזהירות, איז דאס (בפנימיות) אן ענין פון אהבת הקב\"ה און כבוד שמים,\nוכמים הפנים לפנים: דאס איז מגלה אהבת הקב\"ה צו אידן, וואס ברענגט סוף סוף צו הרמת כבוד ישראל אפילו בעיני כל עמי הארץ,\nביז צו דעם כבוד אמיתי וואס וועט זיין בגלוי בגאולה האמיתית והשלימה ע\"י משיח צדקינו, במהרה בימינו ממש.\n(משיחת ש\"פ יתרו תשכ\"ה)",[["38","38","וזה שהקדים רש\"י „שהוא בדמות יוצרך\" ל„ומקפיד על בזיונו\" — כי עיקר החידוש בק\"ו כאן הוא בזה „שהוא בדמות יוצרך\", שמצד פרט זה הוא בשוה ל„אבנים הללו\", הואיל „יש בהם צורך\", שלכן למדין מהם, אלא שיש בזה גם „חומר\", ש„הוא בדמות יוצרך\", ולא כהאבנים שרק „יש בהם צורך\", כנ\"ל בפנים."],["39","39","ברכות יב, א."],["40","40","ל' הלקו\"ת במדבר טו, סע\"ג."],["41","41","ראה לקו\"ש ח\"ג ע' 889 ואילך. ובכ\"מ."]]],[1300211138,"<h3>משפטים</h3>\nא. אויפן פסוק¹ „כי תראה חמור שונאך רובץ תחת משאו וחדלת מעזוב לו עזוב תעזוב עמו\" שטייט אין מכילתא: „פעמים שאתה חדל פעמים שאתה עוזב\", און מ'ברענגט דארט צוויי דוגמאות ביי וועלכע „אתה חדל\": א) „(חמור של ישראל ומשאו של גוי עזוב תעזוב עמו) חמור של גוי ומשאו של ישראל וחדלת מעזוב לו\". ב) „הי' בין הקברות אל יטמא\" — אויב די בהמה איז געווען „בין הקברות\" טאר א כהן זיך ניט מטמא זיין צוליב דעם.\nאויך רש״י בפירושו על התורה ברענגט די דרשה\n— נאך דעם ווי ער איז מפרש דעם פסוק לפי פשוטו, אז דער „פתרון\" פון פסוק איז: „שמא תראה חמורו רובץ תחת משאו, וחדלת מעזוב לו בתמי' עזוב תעזוב עמו\"² (און ברענגט דערויף א דוגמא³ פון פסוק⁴: „כי תאמר בלבבך רבים הגוים האלה ממני גו' לא תירא מהם\") — איז רש״י ממשיך\n„ומדרשו כך דרשו רבותינו כי תראה וחדלת פעמים שאתה חודל ופעמים שאתה עוזר⁵, הא כיצד זקן ואינו לפי כבודו וחדלת או בהמת נכרי ומשאו של ישראל וחדלת\".\nמען דארף אבער פארשטיין דעם שינוי אין פירוש רש״י — וואס אנשטאט דער דוגמא פון „(כהן ו)הי' בין הקברות\" וואס שטייט אין מכילתא, זאגט ער „זקן ואינו לפי כבודו\".\n„זקן ואינו לפי כבודו\" ווערט טאקע געבראכט אין ספרי (און גמרא⁶) אבער אויפן פסוק⁷ „לא תראה את שור אחיך גו' נדחים והתעלמת מהם גו'\" — „פעמים שאתה מתעלם . . הי' כהן והוא בבית הקברות או שהי' זקן ואינו לפי כבודו כו' פטור\" — איז תמוה:\nהלמאי איז רש״י משמיט בפירושו די דוגמא (כהן והי' בין הקברות) וואס ווערט געבראכט אין מכילתא על אתר, און ברענגט דעם פאל (זקן ואינו לפי כבודו) וואס חז״ל זאגן גאר⁸ אויף א צווייטן פסוק?!\nאויך דארף מען פארשטיין:\nא) אין מכילתא קומט „חמור של גוי ומשאו של ישראל\" אלס דער ערשטער פאל — אבער רש״י איז משנה און ברענגט עס אלס די צווייטע דוגמא?",[["1","1","פרשתנו כג, ה."],["2","2","נ״ל שכן צ״ל — כל זה בדיבור אחד (ולא כפי שנדפס בחומשים — התיבות „וחדלת מעזוב לו\" ו„עזוב תעזוב עמו\" באותיות גדולות), וכדמוכח ג״כ מהמשך לשון רש״י „כיוצא בו כו'\". וראה גם ס' זכרון כאן."],["3","3","אחרי שמפרש ש„עזיבה זו לשון עזרה\" — כי זהו ההכרח ד„וחדלת מעזוב לו\" הוא ל' בתמי' (משא״כ אם נפרש עזיבה זו כברוב המקומות)."],["4","4","עקב ז, יז-יח."],["5","5","במכילתא „עוזב\" (ע״ד לשון הפסוק). ושינה רש״י בהתאם לפירושו לפנ״ז ש„עזיבה זו לשון עזרה\"."],["6","6","ב״מ ל, סע״א."],["7","7","תצא כב, א (הובא בפרש״י שם. וראה לקמן סעיף ג). ועד״ז עה״פ (שם, ד) — גבי טעינה — „לא תראה את חמור אחיך גו' נופלים בדרך והתעלמת גו'\" (ושתיקת רש״י שם יל״פ כי סומך על פירושו לפנ״ז)."],["8","8","בגמ' (שם ע״ב) הובא הדין דכל בשלו פורק כו', משא״כ בזקן ואינו לפי כבודו כעובדא דר' ישמעאל ברבי יוסי. אבל לא הובא זה בפירוש הכתוב „וחדלת גו'\" — פעמים שאתה חודל. וראה לקמן הערה 14, 17."]]],[1300211139,"ב) פארוואס זאגט רש״י (ע״ד ווי אין מכילתא⁵) אויך דעם „ופעמים שאתה עוזר\"?\nבשלמא אין מכילתא איז דער לשון מתאים היטב מיטן המשך הענין — ווייבאלד אז דארט רעדט זיך וועגן ביידע אופנים הפכיים פון „חמור כו' משאו\" („חמור של ישראל ומשאו של גוי\" און „חמור של גוי ומשאו של ישראל\"), דערפאר איז „פעמים כו' פעמים שאתה עוזב\"; אבער רש״י ברענגט דאך בלויז דעם אופן פון „בהמת נכרי כו' וחדלת\" — איז וואס פאר אן ארט האט דא צו זאגן „ופעמים שאתה עוזר\", ווייבאלד אז ער רעדט ניט וועגן דעם בפירושו⁹?\n(און אויב ער מיינט אז ס'איז דא א חיוב פון „עוזר\" בכלל — איז דאך דאס מפורש אין פסוק „עזוב תעזוב\". ועוד — ווי פאסט אויף דעם זאגן „פעמים שאתה עוזר\"!).\nב. דער טעם וואס רש״י ברענגט ניט דעם פאל פון (מכילתא) „הי' בין הקברות\", וואלט מען לכאורה געקענט מבאר זיין:\nדאס וואס א כהן טאר זיך ניט מטמא זיין כדי צו מקיים זיין די מצות עשה פון „עזוב תעזוב עמו\", איז ווייל¹⁰ ביי טומאת כהן איז דא א ל״ת און אויך אן עשה, און דערפאר איז מובן מעצמו בפשטות אז עס ווערט ניט נדחה דורך איין עשה (פון „עזוב תעזוב עמו\")¹¹; ברענגט עס ניט רש״י¹², ווייל מען דארף ניט אנקומען צום לימוד פון (דעם יתור הלשון) „וחדלת גו'\".\n[ע״ד ווי די גמרא⁶ זאגט לגבי דעם לימוד פון פסוק „והתעלמת\" — „פעמים שאתה מתעלם\" — אז דעם לימוד דארף מען האבן נאר אויף צו ממעט זיין „זקן ואינו לפי כבודו\", אבער ניט לאפוקי „כהן והוא בבית הקברות\" (ועד״ז — ניט בנוגע דעם פאל פון „היתה מלאכה שלו מרובה משל חבירו\"¹³)].\nאבער מען קען בלאו הכי ניט אננעמען אז רש״י האלט אז דער פטור (פון ביידע פאלן) ווערט אפגעלערנט פון פסוק „וחדלת\" (און דערפאר ברענגט ער ניט דעם פאל פון „הי' בין הקברות\")\n— ווייל לפי זה איז שווער [ניט נאר פארוואס ברענגט רש״י די דוגמא פון „זקן ואינו לפי כבודו\", וואס ווערט ניט דערמאנט אין מכילתא, נאר נאכמער]: ווי אזוי קען מען פון איין יתור לשון („וחדלת גו'\") אפלערנען צוויי באר־",[["9","9","וכפרש״י תצא הנ״ל שכותב רק „פעמים שאתה מתעלם וכו'\" (אף שבספרי ובב״מ שם מוסיף „ופעמים שאי אתה מתעלם\")."],["10","10","ראה ב״מ שם (סע״א) לענין השבת אבידה (ויתירה מזה בנדו״ד (פריקה) שיש רק עשה — ראה בארוכה במפרשים לב״מ שם). אבל להעיר שמלשון המכילתא „יכול יטמא מפני שמ״ע קודמת לל״ת לכך נאמר וחדלת מעזוב\" משמע, שאין הטעם משום דבטומאת כהן יש עשה ול״ת (וראה גם רע״ב עה״ת כאן), כ״א שזהו לימוד מ„וחדלת\". ובמלבי״ם כאן מפרש שזהו מה שמוסיף במכילתא „א״ל אביו הטמא\" שאז יש גם העשה דכיבוד או״א והר״א דדחי עשה ול״ת דטומאה (וראה עד״ז זית רענן לילקוט כאן), אלא שבגמרא מסיק שגם על זה אין צריך קרא, כי העשה דכיבוד מלכתחילה אינה בשאמר לו' לעבור על המצוה. ע״ש. ואכ״מ."],["11","11","או כטעם הב' בגמ' שם (וברמב״ן שם הביא גירסא שרק טעם זה הובא בגמ') „ותו לא דחינן איסורא מקמי ממונא\". וטעם זה הובא ברע״ב עה״ת כאן."],["12","12","ואולי מטעם זה הביא במדרש לקח טוב כאן רק הדוגמא דחמור נכרי כו', והשמיט „הי' בין הקברות\". וגם בפ' תצא (שם, א) השמיט דוגמא זו, אבל הביאה להלן שם (פסוק ד). ואכ״מ."],["13","13","שנלמד ממש״נ (ראה טו, ד) אפס כי לא יהי' בך אביון (ב״מ שם)."]]],[1300211140,"זונדערע דינים (היתרים)¹⁴: א) „זקן ואינו לפי כבודו\" — אז דער חיוב פון פריקה („לפרק המשא\"¹⁵) איז ניט דוחה כבוד האדם; ב) „בהמת נכרי כו' וחדלת\" — אז חיוב פריקה איז ניט פארבונדן מיט צער בעלי חיים (ווארום מצד צער בע״ח איז קיין נפק״מ ניט צו וועמען געהערט די בהמה)¹⁶?\nמוז מען זאגן, אז כאטש דער לימוד פון „וחדלת\" איז ניט דער מקור הפטור אויף ביידע פאלן¹⁷, פונדעסטוועגן ברענגט זיי רש״י צוזאמען, ווייל סו״ס זיינען זיי ביידע אינעם כלל פון „פעמים שאתה חודל\"¹⁸ —\nאיז הדרא קושיא לדוכתה: פארוואס ברענגט ניט רש״י דעם פאל פון מכילתא על אתר „הי' בין הקברות\"¹⁹?\nג. וועט מען דאס פארשטיין בהקדים לבאר דעם טעם וואס רש״י איז דא בכלל מפרט דוגמאות\nובפרט אז בפסוק „והתעלמת\" זאגט רש״י „ורבותינו אמרו פעמים שאתה מתעלם וכו'\" — און טייטשט ניט אויס וואס זיינען די „פעמים שאתה מתעלם\", נאר באגנוגנט זיך מיט „וכו'\".\n[און ס'איז א דוחק גדול צו זאגן אז בדברים פ' תצא — איז ער ניט מפרט דערפאר וואס ער פארלאזט זיך אויף דעם וואס ער ברענגט זיי אויף „וחדלת\" בפרשתנו אין חומש שמות!\nובפרט אז: (א) דא רעדט זיך וועגן חיוב פריקה, און דארט — וועגן השבת אבידה; (ב) דער צווייטער פאל אין רש״י דא — „בהמת נכרי ומשאו של ישראל\" — פאסט ניט ביי השבת אבידה (ווארום פון „משאו של ישראל\" טאר מען זיך ניט מתעלם זיין)].\nמוז מען זאגן, אז וויבאלד ענינו של פירוש רש״י על התורה איז נאר בלויז צו מפרש זיין די כתובים, אבער ניט צו לערנען (פרטי) דינים, דערפאר ברענגט ער דארט נאר דעם טייל פון דרשת חז״ל וואס איז נוגע צום פירוש הכתוב („לא תראה והתעלמת — פעמים שאתה מתעלם\"):\nעפ״ז — היות אז בפרשתנו איז רש״י יא מפרט די דוגמאות פון „פעמים שאתה חודל\" — איז דערפון גופא געדרונגען, אז דא איז זייער פירוט נוגע ומוסיף אין הבנת פשט הכתוב פון „וחדלת גו'\".",[["14","14","וראה ריטב״א לב״מ (לב, ב), שו״ת רדב״ז ח״ז סי' אלף תקמב (הועתק בשטמ״ק שם לג, א) — דלרבנן שס״ל צער בע״ח דאורייתא ובהמת נכרי כו' חייב בפריקה, למדין הפטור דזקן ואינו לפי כבודו גבי פריקה מ„וחדלת\" (ולר' יוסי הגלילי דס״ל צער בע״ח לאו דאורייתא ואצטריך קרא ללמד דבהמת נכרי כו' פטור, יליף זקן כו' גבי פריקה במכש״כ מאבידה)."],["15","15","לשון רש״י כאן."],["16","16","כדאיתא בב״מ (לב, ב) דברייתא זו שבהמת נכרי כו' וחדלת אתיא כר' יוסי הגלילי שס״ל צער בע״ח לאו דאורייתא. וראה רש״י ד״ה צער בע״ח שבת קכח, ב."],["17","17","וי״ל שע״פ הפשט אצטריך קרא רק להפטור דבהמת נכרי כו', אבל זקן ואינו לפי כבודו ידעינן מסברא, דכיון דבשלו לא הי' פורק אינו מחויב בדחבירו (וראה רלב״ג כאן השרש הט'). ולהעיר שגם למ״ד צער בע״ח דאורייתא כתב הר״ן (ב״מ ל, ב) דזקן ואינו לפי כבודו פטור מסברא, דכיון דצער בע״ח הותר לתשמישן של בנ״א כש״כ לכבודם (וראה רע״ב עה״ת כאן: דעשה דממון . . לא דחי . . כבודו של זקן זה). וביראים סי' רסח, דנלמד מהשבת אבידה שבה מפורש דזקן ואינו לפי כבודו פטור (וראה שו״ע אדה״ז חו״מ הל' עוברי דרכים וצער בע״ח סעיף ה). וראה רדב״ז שבהערה 14. ואכ״מ."],["18","18","ע״ד שבספרי וב״מ שם הובאו ג' דוגמאות אף שהקרא לא איצטריך רק לזקן ואינו לפי כבודו, כנ״ל בפנים."],["19","19","אף שצ״ל שרש״י מצא מדרש כזה, מ״מ אינו מובן למה שבק רש״י מכילתא על אתר ומביא מדרש בלתי מצוי."]]],[1300211141,"ד. דער ביאור בזה:\nדער עיקר שוועריקייט אין דעם פירוש הפשוט פון „כי תראה גו' וחדלת גו'\" איז\n(ניט נאר מצד דעם לשון הכתוב, וואס לויטן פירוש „וחדלת מעזוב לו — בתמי'\" קומט אויס, אז דער וואָרט „כי\" (וואס איז „משמש בלשון דילמא\"¹⁵) באַציט זיך ניט צו די ווערטער „תראה חמור שונאך רובץ תחת משאו\" וואס קומען גלייך נאכן וואָרט „כי\", נאר ערשט צו די ווייטערדיקע ווערטער „וחדלת גו'\" —\nנאר דער עיקר שוועריקייט איז אין תוכן):\nדער טעם, בפשטות, פארוואס דער פסוק דארף שולל זיין דעם קס״ד פון „וחדלת מעזוב לו\", איז ווייל דא רעדט זיך וועגן „חמור שונאך\"²⁰; שטעלט זיך די שאלה: בדומה לזה שטייט אין דעם פסוק גלייך פאר דעם: „כי תפגע שור אויבך גו' תועה\" — און דארט איז דער פסוק ניט מזהיר מיטן לשון „וחדלת מלהשיב לו\" (וכיו״ב) — איז תמוה, ממה־נפשך:\nאויב ס'איז נויטיק צו באוואַרענען בשייכות צו אן אויב ושונא, האט עס דער פסוק געדארפט זאגן ביים ערשטן מאל וואו עס רעדט זיך וועגן אזא פאל; און אויב מען דארף עס דארט ניט באוואַרענען\n— ווייל מאי קמ״ל? און ווי ביי אלע אנדערע ציווים פון תורה, שטייט ניט אז אויב איינער וויל ניט פאלגן דעם ציווי — זאגט מען אז ער דארף יא פאלגן —\nאיז פארוואס זאגט עס דער פסוק בנדו״ד, ביים צווייטן מאל?\nדערפון נעמט רש״י ארויס, אז דער „וחדלת גו'\" קומט לערנען א דין וואס איז שייך בלויז צו אונזער פסוק; און דעריבער קען זיך רש״י ניט באגנוגענען מיט זאגן „ומדרשו . . פעמים שאתה חודל\", נאר מוז ברענגען אויך די פאלן²¹ ווען „אתה חודל\" — וואס דער (צווייטער) פאל „בהמת נכרי ומשאו של ישראל\" איז שייך נאר אין אונזער פסוק, און ניט (אין פריערדיקן פסוק) ביי השבת אבידה כנ״ל — און דערפאר שטייט „וחדלת גו'\" („פעמים שאתה חודל\") אין דעם פסוק דוקא.\nעס בלייבט אבער שווער (כנ״ל סעיף א): פארוואס ברענגט רש״י (אויך) „זקן ואינו לפי כבודו\"?\nה. דער ביאור אין דעם:\nמיט ברענגען דעם „מדרשו\" איז רש״י ניט אויסן צו זאגן א צווייטן פירוש אין פסוק, נאר אז דאס איז בהמשך צום ערשטן פירוש, דער דרש איז משלים (פארענטפערט א זייטיקע שוועריקייט אין) דעם פשט.\n[און עפ״ז איז אויך פארשטאנדיק וואס רש״י איז מאריך בלשונו: „ומדרשו כך דרשו רבותינו\" — און זאגט ניט בקיצור (ווי אין רוב ערטער) „ומדרשו\":\nדערמיט איז רש״י מדגיש, אז דער פירוש פון „מדרש\" פאר זיך איז רחוק פון פשוטו של מקרא (איז ניט קיין דרש הקרוב לפשט); ס'איז א באזונדער ענין פון דרש „ומדרשו כך דרשו\", עס בלייבט א דרש.",[["20","20","כפי' הת״א (ועד״ז בתיב״ע) ב„וחדלת מעזוב לו\" — „תשבוק מה דבלבך עלוהי\"."],["21","21","משא״כ בפ' תצא ש„והתעלמת\" אינו מחשבת האדם, כ״א הלאו — „לא תראה אותו שתתעלם\" (לשון רש״י שם)."]]],[1300211142,"מען איז נאר מצרף דעם „מדרשו\" צום פשט הכתוב, ד.ה. אז מיט „וחדלת\" מיינט דער פסוק אויך צו מרמז זיין „פעמים שאתה חודל\"].\nבסגנון אחר: דורך ברענגען דעם מדרש אז „פעמים שאתה חודל\" — ווערט רעכט די שאלה הנ״ל (ניט אין פשט הפסוק, נאר) פארוואס דוקא דא מוז די תורה שולל זיין דעם קס״ד „שמא תראה . . וחדלת מעזוב לו\" —\nוויבאלד אז „פעמים שאתה חודל\", קען א מענטש א טעות האבן (אדער זיך מורה היתר זיין), אז אויך אין זיין פאל איז ניט אזוי הארב אויב ער וועט חודל זיין מעזוב לו²² (כדלקמן).\nדעריבער איז דא דער פסוק שולל דאס מיט זאגן „וחדלת גו' (בתמי') — נאר עזוב תעזוב עמו\".\nו. כדי צו פארשטיין פארוואס זאל מען חושש זיין אז די „פעמים\" פון „אתה חודל\" זיינען עלול צו גורם זיין דעם קס״ד הנ״ל — טייטשט רש״י אויס וואס די פאלן זיינען:\nא) „זקן ואינו לפי כבודו\" — דער חיוב פון פריקה ווערט נדחה אפילו צוליב כבוד האדם (ועאכו״כ צוליב חלישות אין כח האדם):\nב) „בהמת נכרי ומשאו של ישראל\" — דערפון זעט מען, אז מ'איז דא ניט אויסן צו פארמיידן דעם צער פון דער בהמה.\nאון דאס איז וואס רש״י איז מקדים „פעמים שאתה חודל ופעמים שאתה עוזר\": ס'איז ניט דער פשט אז בכלל, אין רוב פאלן, איז דא דער ציווי „עזוב תעזוב\" און דער היתר פון „וחדלת\" („פעמים שאתה חודל\") איז בלויז אין אויסנאם־פאלן — נאר דער חיוב פריקה איז מלכתחילה מצומצם ומוגבל, „פעמים שאתה חודל ופעמים שאתה עוזר\" — דער „חודל\" און דער „עוזר\" זיינען געטיילט כאילו אויף גלייכע „פעמים\".\nובמילא איז פארשטאנדיק אז א מענטש קען זיך דערביי לייכט מורה היתר זיין ניט צו מקיים זיין דעם ציווי.\nדעריבער איז תורה בפירוש שולל אזא הנחה — „וחדלת מעזוב לו (בתמי') עזוב תעזוב עמו\".\nעפ״ז איז פארשטאנדיק פארוואס רש״י איז מקדים דעם פאל פון „זקן ואינו לפי כבודו\" צום פאל פון „בהמת נכרי כו'\" — ווייל דער עיקר גורם צו איינריידן זיך אז דער היתר איז גילטיק אויך אין זיין פאל קומט פון דעם פטור ביי זקן ואינו לפי כבודו; משא״כ דער פטור פון „בהמת נכרי כו'\" איז א טפל טעם וסיוע אז דער חיוב (בכלל) זאל ניט זיין חמור בעיניו.\nאון ס'איז אויך פארענטפערט בפשטות פארוואס רש״י ברענגט ניט דעם פאל פון „הי' בין הקברות\": פון דעם פאל קען מען ניט ארויסדרינגען קיין קולא אין דעם כללות החיוב פריקה, ווייל: (א) דאס איז א זעלטענע מציאות (אז א בהמה מיט א משא זאל זיך געפינען אין א בית הקברות; און דער געפינער איז א כהן). (ב) ועיקר: דער טעם הפטור איז פארבונדן מיטן חומר פון טומאת כהן און ניט צוליב דער קולא אין פריקה.\nז. דערמיט קומט אויך צו א תוספת ביאור פארוואס עס שטייט „וחדלת גו'\" אין אונזער פסוק דוקא, און ניט אין פריערדיקן פסוק ביי השבת אבידה (אע״פ וואס אויך ביי השבת אבידה איז",[["22","22","ראה עד״ז מלבי״ם ותו״ת כאן."]]],[1300211143,"דער זעלבער דין — „פעמים שאתה מתעלם\", כנ״ל):\nביי השבת אבידה פאסט ניט צו זאגן אז מצד די פאלן ווען „אתה מתעלם\" וועט מען אפלערנען א הוראת היתר אויף מקיל זיין אין כללות מצוה זו — ווייל ביי השבת אבידה, ע״ד הרוב, איז ניט פארבונדן מיט קיין גרויסער טירחא כו'.\n— דער פסוק דא רעדט וועגן „כי תפגע שור . . חמורו תועה\", וואס חי נושא את עצמו, ואפילו בספר דברים²³ רעדט זיך וועגן „שמלתו . . (ל)כל אבידת אחיך\", וואס ביי זיי אלע איז די השבה מערסטנס ניט קיין גרויסע טירחא²⁴.\nמשא״כ בנדו״ד, ביי פריקה, איז דאס אן ארבעט וואס איז תמיד פארבונדן מיט טירחא כו'; און וויבאלד אז א „זקן ואינו לפי כבודו\" איז פטור, קען מען דערפון ארויסנעמען א קולא אין כללות המצוה, כנ״ל.\nח. אין פירוש רש״י זיינען דאך מרומז „נפלאות\"²⁵ שבתורה:\nע״פ דעם פירוש הבעש״ט²⁶ אויף דעם פסוק, אז „חמור\" איז מרמז אויפן גוף („חומר שלך\"), און „עזוב תעזוב עמו\" מיינט, אז מען טאר ניט (פארלאזן און) ברעכן דעם גוף דורך תעניות וסיגופים, נאר מען דארף אים מברר ומזכך זיין,\nקען מען זאגן, אז דערפאר ברענגט רש״י די צוויי אופנים דוקא „שאתה חודל\" [(א) זקן ואינו לפי כבודו, (ב) בהמת נכרי ומשאו של ישראל] — ווייל זיי זיינען מרמז אויף די צוויי אופנים (וואס ווערן געבראכט אין אלטן רבי״נס שו״ע²⁷) ווען מען מעג יע פאסטן — (א) תעניות של תשובה, (ב) תעניות כדי למרק נפשו לה':\nוי״ל אז זיי זיינען מתאים צו די צוויי אופנים אין אגרת התשובה:<sup data-n=\"1\">1</sup> ספ״א,<sup data-n=\"2\">2</sup> ר״פ שני.\nתעניות של תשובה זיינען ווען עס רעדט זיך וועגן תשובה (אדער — שלימותה) על חטאים. דעם אופן איז רש״י מרמז אין דעם פאל פון „בהמת נכרי ומשאו של ישראל\": ווען א איד זינדיקט, ח״ו — ווערט זיין גוף ונפש הבהמית אפגעריסן פון קדושה און לפי שעה גייען זיי אריבער תחת ממשלת הקליפה (ס'ווערט „בהמתו של נכרי\") —\nס'איז דאך אבער אפילו פושעי²⁸ ישראל מלאים מצוות²⁹ כרמון — א משא",[["23","23","תצא כב, ג."],["24","24","אבל י״ל שמשום זה לחוד אין טעם מספיק שלא לכתוב „וחדלת\", מאחר שסו״ס נקט הכתוב דוגמא ד„שור . . או חמורו\" שהשבתם קשורה עם טירחא כו'. ועפ״ז מובן הכרחו של רש״י לפרש ד„וחדלת\" מלמד גם הפטור דבהמת נכרי כו' — אף שלפ״ז צ״ל שצער בע״ח לאו דאורייתא (כנ״ל ס״ב), וא״כ למה לא פי' דוחדלת בא ללמד רק הפטור דזקן כו' — כי מאחר שלא נאמר וחדלת בפסוק שלפנ״ז (גבי השבת אבידה), עכצ״ל שבא ללמד פטור השייך רק גבי פריקה, כנ״ל סו״ס ד."],["25","25","לשון השל״ה במס' שבועות שלו (קפא, א)."],["26","26","היום יום כח שבט. כתר שם טוב (קה״ת) הוספות סי' טז."],["27","27","חלק חו״מ הל' נזקי גוף ונפש סעיף ד."],["28","28","עירובין יט, א. חגיגה בסופה."],["29","29","ואף שהן אז בבחי' גלות בתוך הקליפות (תניא ספל״ט. וראה שם ספי״ז) ומוסיפין כח בהן כו' אין לו למנוע מלעסוק בהן (הל' ת״ת לאדה״ז פ״ד סוס״ג). ופשיטא שבמצות שחייב בהן — החיוב בתקפו גם אז, ובברכת „אשר קדשנו במצותיו וציוונו כו'\". והרי בודאי סופו לעשות תשובה ומוציא מהקליפות כל התומ״צ. עיי״ש. ולהעיר אשר המצות פועלות גם קודם שעשה תשובה (מדסתים בש״ס שם) שלא ישלוט בהם אור"]]],[1300211144,"פון (מצות —) ישראל. ובפרט אז די נשמה פון א אידן, איז „גם בשעת החטא היתה באמנה אתו ית'\"³⁰, זי בלייבט גאנץ ביים אידן.\nדאקעגן די תעניות „למרק נפשו לה'\" זיינען נאכדעם, כשעשה תשובה שלימה (כלשונו רפ״ב שם), [אדער ער האט מלכתחילה ניט געדארפט אנקומען דערצו, ווייל לא חטא ולא פגם כו'], נאר ער ווייל דערגרייכן „מירוק הנפש לה'\"³¹ ער זאל זיין לרצון לפני ה' וכו', און עס קען זיין דורך דעם צווייטן קצה: ווען איינער איז אריינגעטאן אין איידעלע ורוחניות'דיקע ענינים, און דערפאר פארנעמט ער זיך ניט (אזויפיל) מיט דער עבודה פון בירור וזיכוך הגוף, קען זיין גוף פארבלייבן אין א געווייסן מצב פון חומריות וגסות וואס פועלט אויך א גסות עכ״פ א ניט שלימות במירוק הנפש³² — דערפאר דארף ער האבן תעניות וואס זיי טוען אויף א מירוק וזיכוך הגוף והנפש.\nאון דאס איז רש״י מרמז מיטן פאל פון „זקן ואינו לפי כבודו\": דאס זיינען די תעניות פון דעם וואס איז א „זקן\" — זה שקנה חכמה³³ — דערפאר איז ביי אים די התעסקות אין בירור וזיכוך גופו („חמור\") און „אינו לפי כבודו\", ס'איז א ירידה לגבי זיין כבוד (ומעלתו³⁴ הרוחנית)); און די תעניות למרק נפשו זיינען פאר אים משלים דעם זיכוך הגוף וואס ער האט פארפעלט.\nועפ״ז איז מובן (בפנימיות הענינים) פארוואס רש״י ברענגט ניט אראָף דעם פאל פון „(כהן ו)הי' בין הקברות\" — ווייל דער ענין פון דער דוגמא אין עבודה רוחנית איז (ע״ד ווי דער ענין פון „בהמת נכרי ומשאו של ישראל\"): די בהמה איז „בין הקברות\" — דורך חטאים איז דער גוף ונפש הבהמית יורד אין „מקום המיתה והטומאה\"³⁵, אבער די נשמה פון א אידן איז אין דער בחינה פון „(בת) כהן\"³⁶ — מחוץ ולמעלה פון מקום המיתה והטומאה, ווייל „גם בשעת החטא היתה באמנה אתו ית'\", כנ״ל.\nאון רש״י קלייבט אויס דעם פאל פון זקן ואינו לפי כבודו דוקא — ווייל אין רוחניות איז ניטאָ די מציאות פון אמת'ן „הי' בין הקברות\": אויך א אידישער גוף איז א מציאות נצחית ביי וועלכער ס'איז ניט שייך קיין מיתה והפסד לגמרי; עס איז „מעשה ידי להתפאר\"³⁷ און אין אים איז דא בחירת הקב״ה³⁸ וואס קען ניט „פארפאלן\" ווערן ח״ו.\nער קען זיך בלויז געפינען ברשותו של נכרי, אבער דאס איז נאר א שינוי (אין) רשות, אז לפי שעה איז ער תחת רשותו, אבער ניט קיין שינוי אין מהות הגוף — וואַרום אויך דעמאלט איז דאס",[["","","של גהינם והן „חומר\" לגבי מזבח הזהב. — ולהעיר אשר שינוי החוזר לברייתו (כשיעשה תשובה) מלכתחילה אינו קונה (ראה סוכה ל, ב. ב״ק צו, ב)."],["30","30","תניא ספכ״ד."],["31","31","אגה״ת רפ״ד."],["32","32","ע״ד הפי' בגסה״ר — שהרוחניות היא בבחי' גסות ועביות (לקו״ת לר״ה סב, א)."],["33","33","קידושין לב, ב. תו״כ ורש״י קדושים יט, לב."],["34","34","להעיר משו״ע אדה״ז הל' מציאה ופקדון סעיף לו ובקו״א סק״ז שם."],["35","35","לשון אדה״ז תניא פכ״ב (כז, ב)."],["36","36","ראה זהר פרשתנו צה, א ואילך. אגה״ק סי״ב (קיח, א)."],["37","37","ראה משנה סנה' ר״פ חלק: כל ישראל כו' לעוה״ב כו' מעשה ידי להתפאר (והכוונה לתחה״מ שהיא להגוף). וראה בארוכה תשובות וביאורים סי' ח*. וש״נ."],["38","38","תניא פמ״ט. וראה בארוכה לקו״ש ח״ו ע' 84. ע״ש. *) אגרות קודש כ״ק אדמו״ר שליט״א ח״א ע' קמב ואילך. המו״ל."]]],[1300211145,"א אידישער גוף. אז דער עצם הגוף פון א אידן זאל זיך ברוחניות געפינען ממש אין א „בית הקברות\" (מיתה רוחנית) — דאס קען מען ניט זאגן!\nוע״ד ההלכה³⁹ — אז א איד וואס (אויך) תורה זאגט אז „נמכר לנכרי\" איז דעמאלט גופא איז ער איינער פון „לי בנ״י עבדים הם, עבדי הם, שטרי קודם\".\nט. און דאס איז אויך דער ביאור ע״פ פנימיות הענינים אין די צוויי פירושים וואס רש״י זאגט דא אין פסוק:\nלויט פשוטו איז „וחדלת מעזוב לו\" א תמי': א איד וואס איז ישר הולך, ווי האלקים עשה את האדם ישר⁴⁰, און דינט דעם אויבערשטן ע״פ סדר התורה — זאגט דער פסוק „וחדלת מעזוב לו — בתמי'\": עס טאר ניט זיין קיין ענין פון סיגופים ותעניות וואס ברעכט דעם גוף, נאר מען דארף זיך פארנעמען מיטן גוף אויף אים מברר זיין און מזכך זיין, כתורת הבעש״ט הנ״ל.\nדערנאך קומט „ומדרשו\" — וואס באווארנט אויך אזעלכע וואס חטאו ופגמו, אדער עכ״פ ניט געגאנגען אין דעם דרך הישר — ובמילא ווערט די מציאות פון „פעמים שאתה חודל\", כנ״ל.\nאעפ״כ, ניט געקוקט אויף הנ״ל אז צוליב ענין התשובה מעג מען פאסטן, און „אפילו מי שאינו יכול להתענות\"⁴¹ — זאגט דער אלטער רבי אין אגרת התשובה⁴² א הוראה ברורה, אז „בדורותינו אלה\" טאר מען ניט מרבה זיין בתעניות אפילו תעניות של תשובה, נאר מען זאל פודה זיין די תעניות מיט צדקה;\nאון וויבאלד אז די חלישות הדור איז ניט מצד דער אייגענער בחירה, נאר ווייל אזוי האט דער אויבערשטער באשאפן דעם דור, איז זיכער, אז אויך דורך דעם אופן העבודה ווי אנגעוויזן דורכ״ן בעש״ט און אלטן רבי״ן פעלט ח״ו גאר ניט אין דעם תיקון החסרון וואס מ'וואלט געהאט דורך תעניות וסיגופים⁴³,\nבדורנו זה איז געגעבן געווארן דער כח צו קענען מתקן זיין ענינים בלתי רצויים אין אזא אופן וואס איז ניט פארבונדן מיט צער ודאגה, נאר דוקא מתוך שמחה וטוב לבב.\n(משיחת ש״פ משפטים תשכ״ו)",[["39","39","ס״פ בהר ובתו״כ שם."],["40","40","קהלת ז, כט."],["41","41","לשון אדה״ז הל' נזקי גוף כו' שם."],["42","42","פ״ג. וראה בארוכה לקו״ש ח״ב ע' 531 ואילך שי״ל שהחידוש בתורת הבעש״ט הנ״ל — שלכאורה ה״ז פסק הלכה שאסור לצער הגוף (שו״ע אדה״ז שם) — שגם באופנים הנ״ל שבשו״ע שמותר להתענות, הנה בדורות הללו ניתן הכח לפעול ענין התשובה ומירוק הנפש באופן של שמירת בריאות הגוף כו'. ע״ש. ואולי י״ל שזהו טעמו של אדה״ז באגה״ת שם, שאסר להרבות בתעניות של תשובה (אף שבשו״ע שם התיר גם במי שאינו יכול להתענות), כי מכיון שבדורות הללו אפשר בלאו הכי שוב אסור לצער גופו."],["43","43","ראה בכ״ז לקוטי ביאורים לתניא (להר״ק קארף) ח״ב ע' צב ואילך (אגה״ת עם ליקוט פירושים כו' (קה״ת) ע' קלז ואילך). וראה שם (ע' צו ואילך. אגה״ת הנ״ל ע' קמא ואילך) טעם החילוק בין דורות הראשונים ודורות האחרונים. ע״ש. וראה הערה הקודמת. סה״ש תשמ״ט ח״א ע' 184 ואילך."]]],[1300211146,"<h3>משפטים ב</h3>\nא. אין פסוק¹ „הנה אנכי שולח מלאך לפניך גו׳ ולהביאך אל המקום אשר הכינותי״, איז רש״י מפרש: „אשר הכינותי — אשר זמנתי לתת לכם״ (און דערנאך ברענגט רש״י א צווייטן פירוש (כדלקמן סעיף ב)).\nמפרשים לערנען², אז רש״י בא־וארנט דא: אין פסוק שטייט „אשר הכינותי״ סתם, און זאגט ניט פאר וועמען דער אויבערשטער האט צוגע־גרייט דעם מקום. איז רש״י מפרש, אז דער „הכינותי״ איז — „לתת לכם״.\n[וויבאלד אבער אז לויט דעם פירוש איז שווער, פארוואס דער פסוק זאגט ניט בפירוש „אשר הכינותי לך״ — ברענגט דעריבער רש״י א צווייטן פירוש, אז „אשר הכינותי״ מיינט „כבר מקומי ניכר כנגדו . . שבהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה״ (כדלקמן ס״ב), וואס לויט דעם פירוש איז דער „הכינותי״ געווען „לעצמו״, כאילו עס וואלט געשטאנען „אשר הכינותי לי״ (און עס דארף ניט שטיין בפירוש, ווייל „סתם הכינותי הוא לעצמו״³)].\nדער פירוש איז אבער ניט פאר־שטאנדיק, ווייל:\nא) אין דרך הפשט איז מלכתחילה ניט קיין קשיא וואס דער פסוק זאגט דא „הכינותי״ סתם⁴, ווייל ס׳איז מובן מאליו אז דער „הכינותי״ איז פאר אידן (וועגן וועמען עס רעדט זיך אין פסוק).\nב) לפ״ז האט רש״י געדארפט זאגן בקיצור (ע״ד ווי דער לשון פון אבן עזרא דא) „אשר הכינותי — לכם״ — פארוואס איז רש״י (א) מאריך בלשונו — „אשר זמנתי לתת (לכם)״; און נאכ־מער: (ב) ער איז משנה פון לשון הפסוק („הכינותי״) און נוצט דעם ווארט „זמנתי״.\nב. דערנאך איז רש״י ממשיך: „זהו פשוטו, ומדרשו אל המקום אשר הכינותי כבר מקומי ניכר כנגדו, וזה א׳ מן המקראות שאומרים שבהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה״.\nדער טעם פארוואס רש״י איז נאכ־אמאל מעתיק די ווערטער „אל המקום אשר הכינותי״ אין דעם (צווייטן) פירוש, איז מובן — לרמז, אז לויט „מדרשו״ איז גלאטיקער פשט הלשון (וואס דער פסוק זאגט) „אל המקום״ — ניט „אל הארץ״⁵ — ווייל דער „הכינותי״ באציט זיך (ניט צו ארץ ישראל, נאר) צום מקום המקדש.\n[ס׳איז אבער ניט קיין קשיא מכריחה אויף „פשוטו״ (פירוש הא׳) — ווייל אין פסוק געפינט מען אז אויך א גאנצע לאנד ווערט אנגערופן „מקום״⁶; ואדרבה — פון המשך הענין דא איז, לכאורה, מוכרח⁷, אז „ולהביאך אל",[["1","1","פרשתנו כג, כ."],["2","2","ראה רא״ם, דבק טוב ושפ״ח כאן."],["3","3","ל׳ הרא״ם כאן."],["4","4","ולהעיר ממקץ מג, טז."],["5","5","ראה גם נחלת יעקב לפרש״י כאן."],["6","6","ראה לדוגמא — מטות לב, א: ארץ גו׳ המקום מקום מקנה (ולאח״ז — שם, ד — ארץ מקנה). וראה בהעלותך י, כט. שלח יד, מ. ועוד."],["7","7","ולפ״ז מ״ש רש״י „ומדרשו״ קאי גם על תיבת „המקום״ — אף שעיקר כוונת רש״י ב„פשוטו ומדרשו״ היא בתוכן ה„הכנה״ כאן (אם הכנה למטה כפשוטה, או הכנה למעלה ברוחניות — בבהמ״ק של מעלה). ולהעיר ממשנ״ת (לקו״ש חט״ז ע׳ 81־82)."]]],[1300211147,"המקום גו׳״ רעדט זיך (ניט וועגן א מקום מסויים אין א״י⁸, נאר) וועגן א״י בכלל;\nוויבאלד אז לויט „מדרשו״ (א) בייט זיך דער טייטש פון „אל המקום״, און (ב) לפ״ז איז גלאטיקער דער לשון „אשר הכינותי״ (כדלקמן), דעריבער איז רש״י מעתיק די ווערטער אראפברענגענדיק „מדרשו״].\nמען דארף אבער פארשטיין וואס רש״י איז דא מוסיף נאך אן ענין: „וזה א׳ מן המקראות שאומרים שבהמ״ק של מעלה כו׳״ — דלכאורה: וואס איז דא נוגע צו וויסן (מדגיש זיין) אז עס זיינען פאראן נאך „מקראות שאומרים שבהמ״ק של מעלה כו׳״?\nמ׳קען ניט זאגן, אז דאס איז אן ענין וואס לייגט זיך ניט אויפן שכל פון א „בן חמש למקרא״, און דערפאר מוז רש״י מוסיף זיין ע״ד ווי ער זאגט בכ״מ „מצאתי לו חבר״ — מ׳געפינט דעם ענין אין נאך ערטער,\nווייל רש״י האט שוין פריער⁹ — צוויי מאל — געבראכט דעם ענין, אז „בהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה״, און אין יענע ערטער איז רש״י ניט מוסיף די ווערטער (די ראי׳ —) „וזה א׳ מן המקראות שאומרים כו׳״.\nג. אויך דארף מען פארשטיין נאך דיוקים בלשון רש״י, ומהם:\nא) דער מקור פון „מדרשו״ איז אין תנחומא¹⁰, אבער דארט איז דער לשון „זה אחד מן המקראות המחוורת שבה״מ שלמטן מכוון כנגד בהמ״ק שלמעלן״ — פארוואס איז רש״י מהפך דעם סדר¹¹: שבהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה¹²?\nב) עס איז דא א גירסא¹³ אין רש״י „שבהמ״ק של מעלה מכוון כנגד של מטה״ (ניט — „בהמ״ק של מטה״) — פארוואס איז רש״י משמיט (לגירסא זו) די ווערטער „בית המקדש״? ובפרט אז אין די פריערדיקע צוויי ערטער זאגט רש״י יע דעם לשון „בית המקדש (מקדש) של מטה״?\nד. דער ביאור אין דעם:\nרש״י קומט דא באווארענען א שאלה פשוטה אין די ווערטער „אשר הכינותי״: „הכנה״ באדייט — א באשטימטע ענדער־רונג אין דער זאך, וואס דערמיט ווערט זי „מוכן״, ראוי ומוכשר צום ענין צו וועלכן מ׳איז עס מכין¹⁴: שטעלט זיך די שאלה בנדו״ד: אין וואס איז באשטאנען דער „הכינותי״ פון ארץ ישראל צו אויפנעמען דארט די אידן — מ׳געפינט ניט אז אין איר איז עפעס נשתנה גע־ווארן איצט לגבי מצבה פריער?\nואדרבה: דער תוכן פון המשך",[["","","החילוק בין הלשונות „פשוטו״ ו„פשוטו של מקרא״ שבפירוש רש״י."],["8","8","ובזה גופא — בית המקדש, שאפילו באם לא הייתה גזירת המרגלים — ע״פ פשש״מ — הי׳ נבנה כמה זמן לאחרי ביאת בנ״י לארץ."],["9","9","ויצא כח, יז. בשלח טו, יז (ושם: כסא של מעלה). ולהעיר שבבשלח לא כתב רש״י ע״ז „ומדרשו״ (או כיו״ב)."],["10","10","פרשתנו יח."],["11","11","ולהעיר גם מהשינוי בין פרש״י ויצא לפירושו בבשלח: בויצא הסדר ברש״י הוא כבפרשתנו, ובפ׳ בשלח — מקדש של מטה מכוון כנגד כסא של מעלה. ואכ״מ."],["12","12","ראה גם של״ה פ׳ תצוה (שכח, סע״א ואילך). וראה לקמן הערה 26."],["13","13","דפוס שני של רש״י (שחתום עליו ר״ש אלקב״ץ (זקנו של בעל ה„לכה דודי״), שהוגה על ידו). וכ״ה בא׳ מכת״י רש״י שתח״י."],["14","14","עייג״כ ל׳ אדה״ז בשו״ע חאו״ח סתצ״ה סוסט״ז."]]],[1300211148,"הפרשה¹⁵ איז מדגיש, אז די לאנד איז נאך ניט מוכן פאר אידן: אין א״י זיינען דא די שבע אומות, מ׳דארף זיי ערשט פארטרייבן פון לאנד, עס דארף קומען (ל׳ עתיד) „והכחדתיו״ „אגרשנו״: און נאכמער — עס איז ניט בעתיד הקרוב, עס קען ניט זיין בקרוב („פן תהי׳ הארץ שממה״), נאר דוקא אין אן אופן פון „מעט מעט אגרשנו״ —\nאיז וואס מיינט דער פסוק מיטן „(ולהביאך אל המקום) אשר הכינותי״¹⁶?\nפארענטפערט רש״י, אז „(אשר) הכינותי״ דא מיינט (ניט א צוגרייטונג דורך א פעולה, טאן — ווי דער טייטש פון „הכנה״ בכמה מקומות¹⁷, נאר) „אשר זמנתי לתת לכם״, אז ס׳איז בלויז געווען א הזמנה — „זמנתי״ (אויך) פון לשון זימון (איינלאדונג): ווי ביים איינלאדן א גאסט, איז דאך אין דעם איינלאדן פאר זיך ניטא קיין פעולת הכנה, ס׳איז נאר א הזמנה (בדיבור)¹⁸ — עד״ז בעניננו¹⁹: דער אויבערשטער האט מזמין געווען ארץ ישראל²⁰ פאר דער שפעטער־דיקער נתינה²¹ צו אידן („זמנתי לתת לכם״).\nוויבאלד אבער אז דער פירוש פון הכנה ע״פ רוב איז — הכשרה ושינוי אין דער זאך, ברענגט רש״י א׳ צווייטן פירוש — „ומדרשו״ — „כבר מקומי ניכר²² כנגדו״, וואס לויט דעם פירוש האט זיך אויפגעטאן א הכנה והכשרה¹⁹ אין דעם מקום, נאר ניט אין דעם מקום המקדש למטה, נאר אין מקום המקדש של מעלה — „מקומי ניכר כנגדו״.\nומהאי טעמא איז רש״י מדייק „שבית המקדש של מעלה מכוון כנגד בהמ״ק של מטה״ — ניט אין דעם (פארקערטן) סדר (כלשון) התנחומא — ווייל די פעולת ההכנה איז געווען אינעם ארט פון „מקדש של מעלה״, אז „מקומי״ (פון מקדש של מעלה) איז געווארן „ניכר²² כנגדו״ (פון דעם מקום מקדש של מטה).\nה. דאס אליין איז אבער ניט מספיק —\nווייל עס איז ניט מסתבר צו זאגן, אז דאס וואס דער אויבערשטער האט מכין געווען דעם מקום המקדש של מעלה, זאל כלל ניט האבן קיין ווירקונג אויף דעם מקום המקדש של מטה, וואס איז „מכוון כנגדו״;\nאון ווי מיר זעען טאקע אין פסוק²³ (ביי יעקב׳ן) „וזה שער השמים״ — וואו",[["15","15","כג, כג. שם, כח ואילך."],["16","16","במדרש לקח טוב כאן: „אע״פ שעתיד כאילו זכינו לפי שגזירת מלכו של עולם משאמרה כבר נעשית״ (וראה רש״י לך טו, יח) — אבל ע״ד הפשט, אין המדובר כאן בנתינת הארץ לבנ״י, כ״א „אשר הכינותי״, הכנתה („להביאך״) בתוכה, היינו פעולה (ניכרת) בהארץ [משא״כ „נתתי״ שבלך שם, שאינו ניכר בהארץ. ולהעיר שברש״י שם הלשון „כאלו היא עשוי״, וראה בארוכה בלקו״ש חט״ו (ע׳ 204 ואילך) שהנתינה בפועל הייתה (ע״ד הפשט) ב(עת) כיבוש הארץ)."],["17","17","ראה מקץ מג, טז. בשלח טז, ה (ובת״א). ועוד."],["18","18","ראה פרש״י לעיל בפרשתנו כא, יג. יתרו יט, יו״ד. ת״א רמב״ן וכו׳ שם. מקץ מג, כה (ות״א). ועוד. ולהעיר מביצה כו, ב (ובר״ח ורש״י שם): עד שיזמין. שו״ע (ודאדה״ז) או״ח סי׳ שי ס״ה (ס״ט). ועייג״כ ל׳ אדה״ז שם סתצ״ה סי״ד."],["19","19","ראה גם באר יצחק לפרש״י כאן."],["20","20","ראה פרש״י בראשית א, א. נת׳ בלקו״ש ח״ה ע׳ 10 ואילך."],["21","21","ראה לעיל הערה 16."],["22","22","כ״ה בדפוסי רש״י שלפנינו. ובדפוס ראשון ושני וכת״י רש״י (שתח״י), וכן ברא״ם כאן — „כבר מקומי כנגדו״ (בלי תיבת „ניכר״). וראה לקמן הערה 25."],["23","23","ויצא שם."]]],[1300211149,"רש״י ברענגט צום ערשטן מאל אז „בהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה״ — אז יעקב האט מרגיש געווען קדושת המקום דלמטה, ווי ער האט געזאגט „מה נורא המקום הזה אין זה כי אם בית אלקים וזה שער השמים״.\nאון וויבאלד דער פסוק זאגט אז דא איז געווען „אשר הכינותי״ — א הכנה אין דעם מקום המקדש של מעלה באופן אז „כבר מקומי ניכר כנגדו״ — האט דאס געדארפט זיין „ניכר״ דאמאלס אויך אין דעם מקום המקדש של מטה —\nווי שטימט דאס מיטן תוכן פון המשך הפרשה, וואו ס׳איז מודגש אז ארץ ישראל (כולל מקום המקדש) איז נאך דאן כלל ניט געווען גרייט (אפילו) פאר ביאת בני ישראל לארץ²⁴?\nדערפאר איז רש״י מוסיף ומבאר „וזה א׳ מן המקראות שאומרים שבהמ״ק של מעלה כו׳״: דער פסוק מיינט דא ניט צו זאגן אז איצט איז געווען א הכנה דורך דעם וואס בהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה: דער „הכינותי״ איז געווען מאז ומקדם, און דאס איז נאך א פסוק (צווישן אנדערע, אויך פריערדיקע „מקראות״) וואס דער־ציילט וועגן זעלבן ענין, אז (שוין פון פריער איז) „בהמ״ק של מעלה מכוון כנגד בהמ״ק של מטה״ (און דער „כבר מקומי ניכר כנגדו״ איז אויך געווען פון פריער (אלעמאל²⁵));\nובמילא איז שוין קיין קשיא ניט וואס מיר געפינען ניט אז עס זאל איצט ווערן א שינוי אין דעם מקום המקדש של מטה.\nעפ״ז איז אויך מובן דער טעם פון דער גירסא „שבהמ״ק של מעלה מכוון כנגד של מטה״ (אן די ווערטער „בהמ״ק של מטה״) — להדגיש, אז די הכנה אין מקום המקדש של מעלה איז ניט פאר־בונדן מיטן מצב פון מקום מקדש של מטה: דער בית המקדש של מעלה איז דא אפילו ווען למטה איז ניטא קיין בית המקדש, עס איז „מכוון כנגד של מטה״ (עס פעלט דער בית המקדש)²⁶: און דערפאר איז קיין סתירה ניט, וואס אע״פ אז „כבר מקומי ניכר כנגדו״, פונדעסטוועגן זעט זיך דא ניט למטה קיין שינוי והכנה²⁷, ואדרבה — אין מקום המקדש של מטה געפינען זיך אומות העולם, דער היפך פון בית המקדש.\nו. פון די עניני הלכה וואס מען קען ארויסנעמען פון דעם פירוש רש״י:\nעס איז דא א מחלוקת הראשונים אין דעת אביי²⁸ אז „הזמנה מילתא היא״ — צי אויך א הזמנה בדיבור מילתא היא, אדער ניט²⁹\n— און דאס איז אויך א נפק״מ למעשה, ווייל (אויך) לדעת רבא²⁸ (וואס הלכה כמותו) אז „הזמנה לאו מילתא",[["24","24","והיינו, דאף את״ל שנעשה איזו הכשרה (רוחנית) גם במקום המקדש של מטה — הו״ל להפסוק להדגיש זה בהמשך הפרשה, ולא להדגיש רק הפכו, איך שהארץ אינה מוכנה."],["25","25","ועפ״ז תומתק הגירסא הנ״ל (הערה 22) „כבר מקומי כנגדו״ — שלגירסא זו מובן שאין הכוונה שהי׳ כאן שינוי לגבי המצב שהי׳ לפנ״ז (שהרי „מקומי כנגדו״ הי׳ גם בימי יעקב)."],["26","26","ועפ״ז (ולגירסא זו) מתורצת קושיית השל״ה (הנ״ל הערה 12), שמלשון רש״י „. . של מעלה מכוון כנגד . . של מטה״ — משמע כאלו הי׳ שלמטה קודם ח״ו."],["27","27","ומה שראה זה יעקב (כנ״ל בפנים) — ה״ז בחלום, או ע״י החלום."],["28","28","סנהדרין מז, ב."],["29","29","ראה חי׳ הר״ן שם. תוד״ה נתנו שם מח, א. שלטי גבורים לברכות כג, ב."]]],[1300211150,"היא״, זיינען אבער דא געוויסע פאלן וואו מען רעכנט זיך יע מיט „הזמנה״³⁰ —\nקען מען זאגן אז דאס איז די נפק״מ להלכה צווישן די צוויי פירושים פון רש״י:\nלויט „פשוטו״ קומט אויס, אז דאס וואס „זמנתי לתת לכם״ (און א פעולת הכנה והכשרה אין דעם מקום), ווערט אנגערופן (אין פסוק „אשר) הכינותי״, ולפ״ז איז אויך הזמנה בדיבור אן ענין של הכנה — מילתא היא³¹.\nמשא״כ לויט „מדרשו״ איז דער „הכינותי״ פארבונדן מיט אן אויפטו וואס איז ניכר אין דער זאך (באופן כנגדו) — „כבר מקומי ניכר כנגדו״; ולפ״ז איז מסתבר לומר, אז הזמנה בדיבור לאו מילתא היא.\n(משיחת מוצש״ק פ׳ משפטים תשל״ט)",[["30","30","ראה לדוגמא: שו״ע או״ח סמ״ב ס״ג ונ״כ שם; רמ״א שם (ובשו״ע אדה״ז שם ס״ו: ולענין הלכה יש להחמיר כסברא זו). וראה שקו״ט להלכה — אם בהנ״ל מהני הזמנה בדיבור — ערוך השולחן ומשנה ברורה לשו״ע או״ח שם. אנציקלופדי׳ תלמודית ע׳ הזמנה (א) ע׳ תרלד (וראה שם ע׳ תרכה ואילך, תרלז), וש״נ."],["31","31","אף שיש לחלק כי כאן המדובר בדיבורו של הקב״ה ש„כאילו היא עשוי״ (רש״י לך טו, יח)."]]],[1300211151,"<h3>משפטים ג</h3>\nא. אויפן פסוק (קרוב לסוף פרשתנו)<sup data-n=\"1\">1</sup> „ויכתוב משה את כל דברי ה'\" שטעלט זיך רש\"י אויף די ווערטער „ויכתוב משה\" און איז מפרש: „מבראשית ועד מתן תורה וכתב מצות שנצטוו במרה\".\nווי גערעדט כמה פעמים, איז רש\"י בפירושו על התורה מפרש פשוטו של מקרא — דארף מען פארשטיין: וואס איז דער הכרח אין פשש\"מ אז משה האט געשריבן אלע ענינים „מבראשית ועד מתן תורה\" (אע\"פ וואס רובם איז בסגנון פון א סיפור און ניט בסגנון פון „דברי ה'\") און אויך „מצות שנצטוו במרה\", און ניט א טייל פון דעם אלעס, אדער אנדערע „דברי ה'\" וכיו\"ב?\nנאך מער: אין פסוק דא שטייט „ויכתוב משה את כל דברי ה'\" — דער זעלבער לשון וואס שטייט אין א פריערדיקן פסוק<sup data-n=\"2\">2</sup> „ויבא משה ויספר לעם את כל דברי ה'\" — וואס רש\"י טייטשט דארט „את כל דברי ה' — מצות פרישה והגבלה\". טאָ וואס איז דער טעם לשנות דעם פירוש פון „ויכתוב משה את כל דברי ה'\" אין דעם פסוק, פון דעם פירוש אין פריערדיקן פסוק?\nאפילו מ'זאל לערנען אז וויבאלד אז מצות פרישה והגבלה איז געווען אן איין מאליגער ענין (אלס הכנה צו מ\"ת), איז דערפאר ניט מסתבר אז (נאר) אויף דעם באציט זיך דער „ויכתוב משה\", וואס כתיבת משה ווייזט אויף אן ענין וואס איז נוגע אויף שפעטער, אדער נאכמער א קביעות לדורות — קען מען דאך לערנען, אז דער „ויכתוב משה\" איז כולל, צוזאמען מיט מצות פרישה והגבלה, אויך די אלע דיבורים וואס זיינען געקומען אלס הקדמה צו מ\"ת אבער אויך נוגע אויף שפעטער [ווי (דער בחיי<sup data-n=\"3\">3</sup> לערנט אז „ויכתוב משה את כל דברי ה'\" מיינט) „התנאים והי'<sup data-n=\"4\">4</sup> אם שמוע תשמעו בקולי ושמרתם את בריתי וגו'\"<sup data-n=\"5\">5</sup>].\nב. די תמיהה בזה איז נאך גרעסער:\nבדוגמא צו פירוש רש\"י געפינט מען אין מכילתא<sup data-n=\"6\">6</sup> — אבער רש\"י איז משנה פון מכילתא, באופן אז דער פירוש פון רש\"י איז דלא כמאן!\nדי מכילתא ברענגט דריי דיעות: „ר' יוסי ברבי אסי אומר מתחלת בראשית ועד כאן, רבי אומר מצוות שנצטווה אדם הראשון ומצוות שנצטוו בני נח ומצוות שנצטוו במצרים ובמרה ושאר כל המצוות כולם, רבי ישמעאל אומר בתחלת הענין מה הוא אומר ושבתה הארץ שבת לה' שש שנים תזרע שדך וגו'<sup data-n=\"7\">7</sup> שמטים ויובלות ברכות וקללות בסוף הענין מה הוא אומר אלה החוקים והמשפטים והתורות<sup data-n=\"8\">8</sup>, אמרו מקבלים אנו עלינו כו'\" —",[["1","1","כד, ד."],["2","2","כד, ג."],["3","3","פרשתנו עה\"פ."],["4","4","יתרו יט, ה (ושם: ועתה אם גו')."],["5","5","במדה\"ג עה\"פ „אלו דברים שקדמו למתן תורה\". אבל משם אין הוכחה כפי' הבחיי כי אפשר לפרש (בדוחק עכ\"פ) שהכוונה היא (ע\"ד המכילתא) גם לדברים שקדמו הרבה למ\"ת (ולא רק לאלו הסמוכים למ\"ת), וכמו שמפרש גם על „ספר הברית\"."],["6","6","יתרו יט, יוד."],["7","7","בהר כה, ב־ג."],["8","8","בחוקתי כו, מו."]]],[1300211152,"רש\"י איז אבער מצרף די ערשטע צווי דיעות צוזאמען.\nאפילו אויב רש\"י לערנט דעם פשט אין מכילתא, אז רבי איז ניט שולל די ערשטע דיעה, נאר ער קומט מוסיף זיין אויף איר, אז אין צוגאב צו „מתחלת בראשית ועד כאן\" זיינען אין דער כתיבה נכלל געווארן די „מצוות שנצטווה אדם הראשון כו'\"<sup data-n=\"9\">9</sup> — קען מען אבער ניט זאגן אז דאס איז דער מקור פון פירוש רש\"י, ווייל רבי רעכנט ניט נאר די מצות שנצטוו במרה (ווי רש\"י זאגט), נאר אלע איבעריקע מצוות (אויך די וואס רש\"י ברענגט ניט)<sup data-n=\"10\">10</sup>.\nנוסף לזה: ס'איז בכלל שווער צו זאגן, אז פירוש רש\"י דא איז גענומען פון (אדער מיוסד אויף) דער מכילתא — וואָרום די מכילתא איז מפרש ניט דעם פסוק „ויכתוב משה\", נאר דעם פסוק<sup data-n=\"11\">11</sup> „ויקח ספר הברית ויקרא באזני העם\", און זאגט „אבל לא שמענו מהיכן קרא באזניהם\" — ד.ה. אין מכילתא רעדט זיך ניט וועגן דער כתיבה (וואס האט משה געשריבן אין דעם ספר), נאר וועגן דעם וואס משה האט געלייענט (פון אט דעם ספר) „באזני העם\". במילא איז דערפון קיין ראי' ניט אויף „ויכתוב משה\" — עס קען זיין אז אין דער כתיבה האט משה כולל געווען מערער ווי אין דער קריאה (וכדיוק לשון המכילתא: „לא שמענו מהיכן (אין דעם ספר) קרא\").\nובכל אופן איז ניט מובן: פון וואנען נעמט רש\"י בפשוטו של מקרא אז דער „ויכתוב משה\" איז געווען „מבראשית ועד מתן תורה . . מצות שנצטוו במרה\"?\nג. ווייטער, אויפן פסוק11 „ויקח ספר הברית ויקרא באזני העם\" איז רש\"י מפרש די ווערטער „ספר הברית\" — „מבראשית ועד מ\"ת ומצות שנצטוו במרה\".\nדער טעם וואס רש\"י דארף דא בכלל זאגן א פירוש אויף „ספר הברית\", איז מובן, ווייל פריער ווערט ניט דערמאנט אז דאס וואס משה האט געשריבן איז געווען דער ספר הברית, דארף רש\"י אפטייטשן אז היינו הך.\nמען דארף אבער פארשטיין: צוליב וואס דארף רש\"י איבערחזר'ן דא די אלע פרטים (וואס ער האט שוין געזאגט ביי „ויכתוב משה\") „מבראשית ועד מתן תורה ומצות שנצטוו במרה\"? — ער האט נאר געדארפט זאגן אז דאס איז דער ספר שכתב משה. וע\"ד לשון הרשב\"ם דא: „ספר הברית — דכתיב למעלה ויכתוב משה וגו'\".\nלכאורה וואלט מען געקענט זאגן, אז רש\"י דארף אויסרעכענען בפרטיות, ווייל אין פסוק שטייט סתם „ויקח ספר הברית ויקרא באזני העם\", עס שטייט אבער ניט וואס און וויפל משה האט פאר זיי געלייענט (ובלשון המכילתא הנ\"ל: „אבל לא שמענו מהיכן קרא\"); דעריבער גיט רש\"י צו וויסן, אז דאס וואס ער האט געלייענט איז געווען „מבראשית ועד מתן תורה ומצות שנצטוו במרה\" — דעם גאנצן ספר הברית.\nאבער מען קען אזוי ניט איינלערנען, ווייל לפ\"ז וואלט רש\"י זיך געדארפט",[["9","9","וראה נח\"י לפרש\"י כאן. שבות יהודה למכילתא יתרו שם."],["10","10","אבל במדרש תנאים דברים (הובא במכילתא הוצאת הארוויטץ בהערות) איתא בשם ר' יהודה רק „מצות שנצטוו במרה\" ותו לא. אבל גם לפי גירסא זו יוקשה כדלהלן, שהרי גם שם קאי על הכתוב „ויקח ספר הברית ויקרא באזני העם\" — קרא באזניהם כו', ולא בנוגע לכתיבת ספר הברית."],["11","11","פרשתנו שם, ז."]]],[1300211153,"שטעלן אויף די ווערטער „ויקרא באזני העם\" און דערויף זאגן (אז „ויקרא\" מיינט) „מבראשית כו'\": רש\"י שטעלט זיך אבער אויף די ווערטער „ספר הברית\", און נאך מער — ער איז אפילו ניט מוסיף „וגו'\" (לרמז על המשך הכתוב); וואס דערפון איז מובן, אז ער איז אויסן צו מפרש זיין (ניט וואס „ויקרא\" נאר) וועלכן ספר דער פסוק מיינט מיט „ספר הברית\".\nאיז הדרא קושיא לדוכתא: צוליב וואס חזר'ט רש\"י איבער זיין פירוש — בפרטיות?\nד. וועט מען דאס פארשטיין בהקדם נאך א דיוק אין לשון רש\"י אין דעם פריערדיקן פירוש (הנ\"ל) „ויכתוב משה — מבראשית ועד מתן תורה וכתב מצות שנצטוו במרה\". דלכאורה איז דער וואַרט „וכתב\" איבעריק: ער שטעלט זיך דאך אויף „ויכתוב משה\", וואלט געווען גענוג בלויז דער ו' החיבור — „(מבראשית ועד מ\"ת) ומצות שנצטוו במרה\", און מ'וואלט אליין פארשטאנען אז דאס אלץ איז נכלל אין דעם „ויכתוב\"?\nאיז דער ביאור בזה:\nוועגן כללות הפרשה (פון „ואל משה אמר עלה אל ה' גו'\") איז פאראן א מחלוקת צווישן מפרשי התורה — ווען די פרשה איז געזאגט געווארן און ווען עס זיינען פארגעקומען די אלע מאורעות וועגן וועלכע די פרשה רעדט:\nרש\"י לערנט<sup data-n=\"12\">12</sup> אז „פרשה זו נאמרה קודם עשרת הדברות ובד' בסיון נאמרה לו עלה\". ד.ה. אז אויך דער ויכתוב משה איז געווען ביום ד', און אנדערע זאכן, ווי „ויבן מזבח וכו'\", זיינען פארגעקומען ביום ה' בסיון<sup data-n=\"13\">13</sup>.\nלדעת הרמב\"ן<sup data-n=\"14\">14</sup> ועוד איז דאס אלץ פארגעקומען נאך די עשרת הדברות, נאך מ\"ת.\nמצד דער מחלוקת אין דעם זמן, ווען די פרשה איז געזאגט געווארן, קומט אויך אַרויס א שינוי אינעם פירוש פון דעם פסוק „ויבוא משה ויספר להם את כל דברי ה' ואת כל המשפטים\":\nלויט רש\"י מיינט „כל דברי ה'\", כנ\"ל, די „מצות פרישה והגבלה\", און „ואת כל המשפטים\" — די ז' מצות שנצטוו בני נח ושבת וכבוד אב ואם ופרה אדומה ודינין שניתנו להם במרה\"<sup data-n=\"15\">15</sup>.\nולדעת הרמב\"ן<sup data-n=\"16\">16</sup> ועוד ווערט דערמיט („כל דברי ה'\") געמיינט דאס וואס דער אויבערשטער האט געזאגט נאך מ\"ת — „אתם ראיתם כי מן השמים גו'\", און (מיט „כל המשפטים\" —) גאנץ פרשת משפטים ביז צו דער פרשה „ואל משה אמר גו'\".",[["12","12","פרשתנו כד, א. וראה בחיי שם: על דרך הפשט זו קודם מתן תורה. וראה בארוכה לקו\"ש חכ\"ו ע' 153 ואילך."],["13","13","כפרש\"י כד, ד ד\"ה וישכם בבקר."],["14","14","ראה בארוכה רמב\"ן כאן, א. וראה בראב\"ע כאן — בהמשך כל הפסוקים (הובא ברמב\"ן): יתרו כ, כא. וראה אברבנאל כאן: ואמרו חכמי צרפת כי זה נאמר קודם מ\"ת . . אבל חכמי ספרד קיימו וקבלו שהי' זה אחר מ\"ת כסדר הפרשיות. וראה גם אוה\"ח כאן."],["15","15","ויל\"ע אם לפרש\"י זה גם ז' מצות ב\"נ נאמרו להם במרה, וכהדיעה בסנהדרין (נו, ב). ואף שבפ' בשלח (טו, כה) לא הובא בפרש\"י ע\"ד ז' מצות ב\"נ — הרי זהו לפי ששם בא לפרש הלשון „שם שם לו חוק ומשפט גו'\". והרי גם כבוד או\"א לא הביא רש\"י שם אף שהובאה כאן, כי אף שמוכח בואתחנן (ה, טז) ש„אף על כבוד אב ואם נצטוו במרה\" (רש\"י שם), מ\"מ, מכיון שאין הכרח בלשון הכתוב ובפשש\"מ שם ע\"ז, אין רש\"י מביאו בפ' בשלח. וראה שיחת ש\"פ בשלח וש\"פ ואתחנן תשכ\"ח. וראה לקמן בפנים ובהערה 24."],["16","16","רמב\"ן שם. ועד\"ז הוא בראב\"ע פרשתנו שם, ג."]]],[1300211154,"און אט דער חילוק צווישן די צווי דיעות ברענגט אויך א חילוק אין דעם תוכן פון דעם „ברית\":\nענינו פון א ברית איז צו פארשטארקן דעם קישור וחיבור צווישן די וועלכע זיינען זיך משתתף אין דעם ברית<sup data-n=\"17\">17</sup>, ובנדו\"ד — אידן מיט תורה (וואס דורך דער תורה וואס דער אויבערשטער האט זיי געגעבן ווערן זיי פארבונדן אויך מיטן אויבערשטן)<sup data-n=\"18\">18</sup>.\nלפ\"ז איז מובן, אז לויט רש\"י אז דער ברית איז געווען פאר מ\"ת, איז דער ברית אויף און דורך די ענינים וואס דער אויבערשטער האט געגעבן די אידן פאר מ\"ת, ובפרט די וועלכע קענען שטארקן ביותר דעם (פארבונד) ברית, ווי „כח מעשיו הגיד לעמו\" — מבראשית ועד החודש הזה<sup data-n=\"19\">19</sup> און דער ברית איז געווען אלס הכנה והקדמה צו מ\"ת<sup data-n=\"20\">20</sup> (עשהו\"ד וכו'); אבער לדעת הרמב\"ן ועוד — איז דער ברית געווען בעיקר פארבונדן מיט די דברות וציוויים וואס דער אויבערשטער האט אנגעזאגט נאך מתן תורה.\nלפ\"ז איז מובן אז ווען דער פסוק זאגט „ויכתוב משה\" — די כתיבה פון דעם „ספר הברית\" (דעם ספר וואס איז פארבונדן מיטן ברית, ווי געזאגט ווייטער אין דער פרשה) — ווערט געמיינט לויט פרש\"י, אז ער האט געשריבן די „כל דברי ה'\" וואס זיינען שוין ביז דעמאלט געזאגט געווארן צו אידן, דהיינו: „מבראשית ועד מ\"ת\" און די „מצוות שנצטוו במרה\".\nוואס די כתיבה איז געווען ניט (בלויז) צוליב דער שפעטערדיקער קריאה „באזני העם\", נאר דאס גופא איז (אויך) געווען א טייל פון דעם ברית: מיט דעם וואס ער האט עס פארשריבן האט עס באקומען א תוספת תוקף, דאס האט די אידן מער מחייב געווען און פארבונדן אין דעם<sup data-n=\"21\">21</sup>.\nה. עפ\"ז יש לומר, אז דער טעם וואס רש\"י צעטיילט (מיטן „וכתב\") די ביידע ענינים „מבראשית ועד מ\"ת\" און „מצוות שנצטוו במרה\", איז ווייל דאס זיינען צווי אופני כתיבה:\nא) „מבראשית ועד מ\"ת\", דער סיפור המאורעות כו' פון בריאת העולם ביזן זמן פון מ\"ת, האט זיי (רוב רובם) משה דא פארשריבן בסגנון ובצורה ווי זיי זיינען כתובים בתורה לפנינו<sup data-n=\"22\">22</sup> (דמהיכא תיתי און פארוואס זאל ער משנה זיין, וכדמשמע קצת פון ל' רש\"י גופא: „מבראשית ועד מ\"ת\"), ובמילא איז דאס אין גדר פון כתיבת פרשיות של תורה:\nב) „וכתב מצות שנצטוו במרה\", וואס",[["17","17","ראה פרש\"י לך טו, י. נצבים כט, יא. וראה רמב\"ן כאן „כי זאת אות הברית לבא השנים בחלקים שוים\"."],["18","18","ובנדו\"ד התבטא בזריקת חצי הדם על המזבח וחצי הדם על העם (כרמב\"ן הנ\"ל). וראה חזקוני כאן פסוק ח. אברבנאל שם. וראה לקו\"ש משפטים תש\"נ (ס\"ד ואילך)."],["19","19","כפרש\"י בראשית א, א."],["20","20","וראה אוה\"ח שם, א."],["21","21","וע\"ד דבר שבע\"פ שבא אח\"כ גם בשטר."],["22","22","היינו עד ס\"פ בשלח [מלבד הפסוק טז, לג (פרש\"י שם). וכצ\"ל לרש\"י שם בנוגע פסוקים לד־ה — אף שהלשון ברש\"י הוא „ולא נאמר מקרא זה\", כי בפסוקים שלאח\"ז ה\"ז מובן בפשטות], ובפ' יתרו מ„בחדש השלישי\" עד פסוק טז. אבל התחלת פ' יתרו או עכ\"פ מפסוק יח, יג עד „בחדש השלישי\" „שלא נאמר ויהי ממחרת עד שנה שני'\" (פרש\"י יח, יג שם) — לא נכתבו. ולהעיר מחידושי הריטב\"א מכ\"י (ירושלים תשמ\"א) לגיטין ס, א ד\"ה ואידך „וי\"מ שכיון משה רבינו כמה פרשיות עתידות ליכתב בינתיים בין אחת לחברתה וכמה גויל צריך להניח ביניהן כו'\". וראה בארוכה בנוגע ל„ספר הברית\" — השקו\"ט והדיעות בזה — תו\"ש חי\"ט מילואים סל\"א פ\"ג־ד."]]],[1300211155,"דאס זיינען די מצות פון „שבת כבוד או\"א פרה אדומה ודינין\", האט ער דאך ניט געקענט שרייבן (לדוגמא) בא פרה אדומה „זאת חוקת התורה\" „ונתתם אותה אל אלעזר הכהן\" ועוד. איז מסתבר אז משה האט זיי פארשריבן ניט (באופן ובנוסח ווי זיי זיינען שפעטער פארשריבן געווארן) אלס פרשיות של תורה, נאר באופן וואס גיט אַרויס דעם תוכן וענין המצוות (וכלשון רש\"י: וכתב מצות<sup data-n=\"23\">23</sup>), דא איז ניט געווען גדר כתיבת פרשיות של תורה, נאר א גדר פון כתיבת מצות<sup data-n=\"24\">24</sup>.\nאון עד\"ז איז דער אונטערשייד צי דער „ויכתוב משה\" איז געווען פאר מ\"ת אדער (ווי די דיעות אז ס'איז געווען) לאחר מ\"ת.\nלפני מתן תורה זיינען געווען צווי ענינים: פרשיות התורה<sup data-n=\"25\">25</sup> און מצוות שנצטוו במרה, ובמילא זיינען אויך אין „ויכתוב משה\" געווען צווי סוגי כתיבה, כנ\"ל — כתיבת פרשיות התורה און כתיבת מצות (שנצטוו במרה) ניט ווי זיי זיינען א חלק פון פרשיות התורה:\nנאך מתן תורה אבער איז ניטא קיין טעם צו מאכן א חילוק<sup data-n=\"26\">26</sup>, נאר „ויכתוב\" אלעס אין זעלבן אופן — אויך די מצות (משפטים) זיינען געשריבן געווארן דורך משה אלס פרשיות התורה (וועלכע אנטהאלטן די מצות).\nו. דערמיט ווערט פארשטאנדיק דער טעם, וואס קומענדיק צום פסוק „ויקח ספר הברית\", דארף רש\"י מבאר און מפרש זיין וואס דער „ספר הברית\" איז:\nהיות מ'האט געלערנט פריער אז משה האט געשריבן צווי באזונדערע ענינים, אין צווי פארשידענע גדרי כתיבה — און דא שטייט „ספר הברית\" לשון יחיד — דארף רש\"י מפרש זיין אז דער ספר הברית באשטייט פון די זעלבע צווי פארשידענע ענינים: „מבראשית ועד מ\"ת ומצות שנצטוו במרה\"; מיט דעם ווערט אויך אַרויסגעבראכט אז דער ברית מיט אידן איז געווען אויף ביידע ענינים:\nא) אויף תורה ולימודה, וואס דאס איז געווען דורכן שרייבן „מבראשית ועד מ\"ת\", פרשיות התורה.\nב) אויף קיום המצוות<sup data-n=\"27\">27</sup> — דורך כתיבת ה„מצות שנצטוו במרה\".\nאון עפ\"ז יומתק, וואס נאכדעם ווי משה רבינו האט געלייענט דעם ספר הברית „באזני העם\", האבן די אידן געזאגט: „כל אשר דבר ה' נעשה ונשמע\"<sup data-n=\"28\">28</sup>:",[["23","23","ולא כתב „וכתב פרשיות התורה שנצטוו במרה\" וכיו\"ב."],["24","24","ואף שבפ' בשלח שם פרש\"י „במרה נתן להם מקצת פרשיות של תורה\", הרי\"ז כהמשך לשון רש\"י „שיתעסקו בהם\", דשם לא נצטוו בקיום מצות אלו אלא רק „שיתעסקו בהם\", שילמדם (ראה רמב\"ן שם. שיחת ש\"פ בשלח, וש\"פ ואתחנן הנ\"ל. לקו\"ש בשלח תשמ\"ז ס\"ג), וזה שייך רק בפרשיות של תורה — שהוא לא רק דיבור בכלל אלא בפרטים. אבל אי\"ז שייך לסגנון הכתיבה, שבמרה בכלל לא נכתבו עדיין פרשיות אלו. ועפ\"ז אולי יש לומר מה שלא פרש\"י שם ז' מצות שנצטוו ב\"נ (ראה לעיל הערה 15) כי זה לא שייך לענין פרשיות של תורה שיתעסקו בהם שהרי היו ידועות להם מכבר."],["25","25","ובזה כלול — המצות שנאמרות בפרשיות אלו בתורה."],["26","26","ולדחוק ד„ויכתוב\" לצדדין איתמר."],["27","27","ולכאורה זהו תוכן הפלוגתא במכילתא (הנ\"ל ס\"ב): לדעת ר\"י ברבי אסי „מתחלת בראשית עד כאן\" הוי עיקר ותוכן קריאת ספר הברית — תורה, וע\"ז הי' עיקר הברית; ולדעת רבי „מצות שנצטווה אדה\"ר ומצות שנצטוו בני נח כו' ושאר כל המצות כולם\" — עיקרו הוא ברית על מצות."],["28","28","משא\"כ לעיל פסוק ג' אמרו „כל הדברים אשר דבר ה' נעשה\", כי שם היו רק ציוויים ולא „תורה\"."]]],[1300211156,"„נעשה\" — בקשר צו די „מצות שנצטוו במרה\", וואס ער האט געלייענט: און „נשמע\" בהמשך צו קריאת הפרשיות „מבראשית ועד מ\"ת\"<sup data-n=\"29\">29</sup> — און דאס איז געווען די הכנה והקדמה צום לימוד התורה וקיום המצות וואס אידן האבן אויף זיך מקבל געווען*<sup data-n=\"29\">29</sup> מכאן ולהבא; דורך דער קבלה כפולה ובאופן של „ברית\", זיינען זיי געווארן ראוי צו מקבל זיין די תורה.\nז. פון די ענינים מופלאים שבפירוש רש\"י זה:\nאין גמרא<sup data-n=\"30\">30</sup> איז דא א מחלוקת צווישן ר\"י און ר\"ל, צי „תורה מגילה מגילה ניתנה\" („כשנאמרה פרשה למשה הי' כותבה, ולבסוף מ' שנה כשנגמרו כל הפרשיות חיברן בגידין ותפרן\" — רש\"י<sup data-n=\"31\">31</sup>), אדער „תורה חתומה ניתנה\" („לא נכתבה עד סוף מ' לאחר שנאמרו כל הפרשיות כולן והנאמרות לו בשנה ראשונה ושני' היו סדורות לו על פה עד שכתבן\" — רש\"י<sup data-n=\"32\">32</sup>).\nשטעלט זיך תוס'<sup data-n=\"33\">33</sup> אויף דעם מ\"ד וואס האלט „תורה חתומה ניתנה\" און פרעגט: „תימה דכתיב ויקח ספר הברית ויקרא באזני העם ופרש\"י בפי' חומש דהיינו מבראשית ועד כאן\"<sup data-n=\"34\">34</sup>, און פארענטפערט: „ונראה לפרש דלא קאמר חתומה ניתנה שלא נכתבה עד לבסוף אלא שעל הסדר נכתבה דיש פרשיות שנאמרו תחילה לפני אותם הכתובים לפניהם ולא נכתבה עד שנאמר לו אותה שכתובה לפני' וכותב זאת אחרי'\".\nדער מהר\"ל<sup data-n=\"35\">35</sup> איז מסביר, אז פרש\"י בפרשתנו איז ניט בסתירה צום מ\"ד תורה חתומה ניתנה (אויך לדעת רש\"י בפי' לש\"ס, אז דאס מיינט „לא נכתבה עד סוף מ'\") — ווייל דאס איז געווען „צורך מצוה\", און דעריבער איז „אין זה נתינת תורה נחשב רק לכרות ברית\"<sup data-n=\"36\">36</sup>.\nע\"פ הנ\"ל יומתק: וואָרום עם היות אז די כתיבה „מבראשית ועד מ\"ת\" איז געווען",[["29","29","ומה שע\"ד הפשט הקדימו נעשה לנשמע אף שסדרם בספר הברית והסדר ששמעו קריאתו של משה היא תחילה פרשיות התורה מבראשית ועד מ\"ת ואח\"כ מצות שנצטוו במרה — כי גם ע\"ד הפשט עיקר ענין התורה (ל' הוראה) הוא קיום המצות, מעשה. *29) כי „נשמע\" כאן אין פירושו „שמיעת האוזן\" כ\"א „קבלת דברים\" (רש\"י וישב לז, כז), ומכפל לשון הכתוב „נעשה ונשמע\", מובן שהן ב' קבלות: „נעשה\" היא הקבלה על מצות (עשי'), ו„נשמע\" — ה„קבלה\" על התורה."],["30","30","גיטין ס, א."],["31","31","גיטין שם ד\"ה מגילה."],["32","32","גיטין שם ד\"ה חתומה."],["33","33","גיטין שם ד\"ה תורה."],["34","34","וצע\"ק מה שהתוס' הביאו הפסוק ויקח ספר הברית ויקרא באזני העם (ופרש\"י עה\"פ), ולא הכתוב (ופרש\"י) שקדמו — „ויכתוב משה\". והרי המדובר כאן הוא בנוגע לכתיבת משה. ואולי לא הי' לפני התוס' פרש\"י ד\"ה ויכתוב משה, וכבכמה כת\"י רש\"י (שתח\"י) שד\"ה זה ליתא*. וראה לקמן הערה 40."],["35","35","גו\"א פרשתנו עה\"פ ויכתוב משה."],["36","36","ראה עד\"ז חידושי הרשב\"א גיטין שם: „ואולו נאמר דאפילו ר\"ל לא אמר אלא שלא הי' כותב כל פרשה ופרשה כמו שנאמרה לו אלא סודרה על פה עד גמר התורה אלא פרשיות שהיו צריכות לשעה הי' כותבן כדי שיראו וילמדו מתוך הכתב\". אלא שצע\"ק אם שייך „שיראו וילמדו מתוך הכתב\" בנוגע ל„ספר הברית\". ואולי נקט לשון זה כי קאי (בעיקר) על שמונה פרשיות שנכתבו (כר' לוי), ע\"ש — אבל ההיתר לכתוב הוא משום שהי' צורך השעה (עדמ\"ש בגו\"א). וכן מוכח בצידה לדרך פרשתנו כאן (מספר אמרי שפר). ע\"ש. וראה בארוכה (ובהבא לקמן) תורה שלימה שם פ\"ד. ואכ\"מ. *) אבל מסתבר שטעות המעתיק הוא, שדילג מתיבת „במרה\" שבפרש\"י סוף פסוק ג ל„במרה\" שבסוף ד\"ה ויכתוב משה (בפסוק ד). ובא' מכת\"י הנ\"ל הועתק על הגליון פרש\"י ד\"ה ויכתוב משה. ולהעיר שבכתבי יד רש\"י הנ\"ל, הגירסא בפרש\"י ד\"ה „ספר הברית\" היא: מבראשית עד מ\"ת שנצטווה במרה (וט\"ס דמוכח הוא)."]]],[1300211157,"ווען באופן הכתיבה פון פרשיות התורה, איז דאס אבער פארט ניט אין גדר פון (כתיבת) פרשיות התורה, נאר א טייל פון „ספר הברית\", וואס האט אויך אנטהאלטן די „מצות שנצטוו במרה\" — און זייער שרייבן איז דאך געווען אינגאנצן אנדערש פון דער כתיבה בפרשיות התורה און די ביידע סוגי כתיבה האבן דאך צוזאמענגעשטעלט איין „ספר הברית\".\nאון דאס וואס תוס' פרעגט פון דעם פירוש רש\"י — איז י\"ל לדעת התוס': וויבאלד אז די פרשיות וואס משה האט געשריבן מבראשית ועד מ\"ת זיינען ניט אנדערש (בצורתן ולשונן) ווי די פרשיות הכתובות לאח\"ז בתורה<sup data-n=\"37\">37</sup>, איז אע\"פ אז משה האט אין „ספר הברית\" צו זיי מצרף געווען אויך די מצות שנצטוו במרה (וואס זיינען געשריבן געווארן ניט ווי פרשיות התורה), איז דאס אבער ניט מבטל אדער גורע פון דעם וואס די פרשיות מבראשית ועד מ\"ת זיינען אן ענין פון כתיבת פרשיות התורה.\n[ועפ\"ז יומתק וואס תוס' איז מעתיק פון לשון רש\"י „מבראשית ועד כאן\"<sup data-n=\"38\">38</sup> און דערמאנט ניט דעם סיום לשון רש\"י „מצות שנצטוו במרה\"<sup data-n=\"39\">39</sup> — ווייל די כתיבת מצות שנצטוו במרה האט קיין שייכות ניט להשקו\"ט אין תוס'. די קשיא איז נאר פון „כתיבת בראשית ועד מ\"ת\", וואס איז א גדר פון כתיבת פרשיות של תורה<sup data-n=\"40\">40</sup>].\nדעת רש\"י איז אבער, אז וויבאלד ביידע עניני כתיבה זיינען געווארן איין „ספר הברית\" — איז אפילו די פרשיות מבראשית ועד מ\"ת זיינען ניט אן ענין פון כתיבת פרשיות של תורה, נאר — אן ענין פון „ספר הברית\".\nח. מיינה של תורה שבפירוש רש\"י זה — י\"ל:\nאע\"פ אז כללות ענין הברית איז דער קישור והתחברות צווישן די וואס זיינען כורת דעם ברית, ובנדו\"ד — די התחברות והתאחדות פון אויבערשטן מיט אידן, איז אבער דא א חילוק אין דעם תוכן הברית צי דער ברית איז געמאכט געווארן לפני מ\"ת, אדער לאחרי מ\"ת:\nביז מ\"ת איז געווען די גזירה אז העליונים לא ירדו לתחתונים והתחתונים לא יעלו לעליונים<sup data-n=\"41\">41</sup>. קומט אויס, אז דער ברית פון פאר מ\"ת איז נאך אלץ געווען פארבונדן מיט דעם גברא ניט מיט דער חפצא. ויתרה מזו: עס האט זיך טאקע אויפגעטאן דורך תורה ומצות (דלפני מ\"ת) אן עלי' און א חיבור מיט דעם אויבערשטן, דאס איז אבער געווען אינעם אופן פון פאר מ\"ת — ניט",[["37","37","אבל ראה לעיל הערה 22."],["38","38","שינוי לשון התוס' „מבראשית ועד כאן\", לא כלשון רש\"י לפנינו (וכ\"ה בדפוס ראשון ושני דרש\"י) „מבראשית ועד מ\"ת\" — י\"ל כי כן היתה גירסתם בפרש\"י, וכגירסת המכילתא יתרו שם. ואולי י\"ל, כי ס\"ל שפרשה זו נאמרה אחרי מ\"ת ו„ועד כאן\" כולל גם פ' משפטים. וכמפורש בחידושי הריטב\"א מכת\"י הנ\"ל (גיטין שם ד\"ה ור\"ל) „כי מתחלה כתב מבראשית עד סוף ואלה המשפטים\". וצ\"ע בכוונת המכילתא (יתרו שם) ב„ועד כאן\" — אם כולל רק עד מ\"ת או גם פ' משפטים. ולהעיר מהפלוגתא במכילתא ריש פרשתנו אם ואלה המשפטים „מסיני\" או „במרה\". ואכ\"מ."],["39","39","בפשטות י\"ל שלא הי' לפני התוס' סיום לשון רש\"י „מצות שנצטוו במרה\" (וכלשון המכילתא. וראה הערה הקודמת)."],["40","40","ואולי יש לומר, שלכן הביא התוס' פרש\"י עה\"פ ויקח ספר הברית ויקרא באזני העם, ולא פרש\"י עה\"פ ויכתוב משה — כי מזה מובן שזהו בגדר כתיבת התורה. שהרי כתיבת ספר תורה ענינה (ומצותה) הוא (כהמשך הכתוב — וילך לא, יט) „ולמדה את בני ישראל, לקרות וללמד בה (ראה בארוכה לקו\"ש חכ\"ג ע' 18 ואילך. וש\"נ). משא\"כ מצד עצם הכתיבה אין מוכרח דהוי גדר כתיבת התורה."],["41","41","ראה שמו\"ר פי\"ב, ג. תנחומא וארא טו."]]],[1300211158,"ארויס פון גדר (תחתון) נברא<sup data-n=\"42\">42</sup>.\nמשא\"כ לויט די דיעות אז דער ברית איז געווען לאחרי מ\"ת, נאכן א) ביטול הגזירה, ב) ואני המתחיל, ויתרה מזו ג) דער חידוש פון „אנא נפשי כתבית יהבית\"<sup data-n=\"43\">43</sup> — דער אויבערשטער האט זיך אליין כביכול אריינגעגעבן לנצח ותמיד אין תורה<sup data-n=\"44\">44</sup>,\nאיז אויך מובן, אז די התאחדות מיט תורה ובאופן של ברית האט געפועל'ט תכלית ושלימות העלי' בבחי' יציאה לגמרי פון גדר נברא.\nס'איז אבער דא אן עילוי אין דער דיעה (דעת רש\"י) אז דער ברית איז געווען פאר מ\"ת — היות אז זייענדיק אויך דעמאלט (פאר מ\"ת) „קשורים ענובים תפוסים\"<sup data-n=\"45\">45</sup> מיט בחי' התורה ווי זי איז אראפגעקומען צו נבראים (פאר מ\"ת) און מיט בחי' האלקות שנמשך על ידה, איז מובן, אז נאך אזא הכנה איז דער זיכוך ועליית הנבראים ביי מ\"ת געווען נאכמער בשלימות, ובמילא זיינען זיי געווען מצד מדריגתם ראוי מקבל זיין די תורה שלמעלה מגדר הנבראים.\nמשא\"כ לויט די דיעות, אז דער ברית איז געווען לאחרי מ\"ת, איז בשעת מ\"ת תורה געווען למעלה לגמרי פון מדריגתם וענינם און די נתינת התורה איז בעיקר געווען מצד למעלה<sup data-n=\"46\">46</sup>.\nט. ועפ\"ז יש לבאר דעם חילוק הנ\"ל (ס\"ה) — אז לדעת רש\"י זיינען אין דעם „ויכתוב\" און אין דעם ברית געווען צווי ענינים — תורה און מצות, און לויט די אנדערע דיעות איז דאס איין ענין, (א חלק פון) תורה:\nמצד גדר הנבראים הערט זיך התחלקות פון תורה און מצות, ובמילא אויך אין דער קבלה פון אידן „נעשה\" באזונדער און „נשמע\" באזונדער.\nאבער מצד הבורא הערט זיך ניט קיין התחלקות. פונקט ווי דער אויבערשטער איז אחדות הפשוטה, אזוי זאגט זיך עס אַרויס אויך אין תורה ווי זי איז מצד למעלה: אלעס איז איין ענין פון תורה<sup data-n=\"47\">47</sup>.\n(משיחת ש\"פ משפטים תשמ\"ב)",[["42","42","כי בהתומ\"צ שלפני מ\"ת לא ניתן הכח לשנות (התחתון לעליון) החפצא מחול לקדושה — וראה לקו\"ש חט\"ז ע' 212 ואילך, ובכ\"מ."],["43","43","שבת קה, א (כגירסת העי\"ש שם)."],["44","44","ראה תניא פמ\"ז."],["45","45","לשון המכילתא יתרו שם — „הרי אתם קשורים ענובים תפוסים מחר באו וקבלו עליכם המצוות\"."],["46","46","ראה לקו\"ת ראה כה, ב. סה\"מ תרמ\"ג ע' פד. ובכ\"מ."],["47","47","להעיר מלקו\"ש חי\"ז ע' 415."]]],[1300211159,"<h3>תרומה</h3>\nא. שוין גערעדט פיל מאל¹ בנוגע די שמות הסדרות: כאטש אז בפשטות איז דער נאמען פון יעדער סדרה ע\"ש התחלתה, וויבאלד אבער אז עס איז א מנהג ישראל זיי אזוי רופן, וואס מנהג ישראל תורה היא² און אין תורה זיינען אלע ענינים בתכלית הדיוק, איז מובן אז דער נאמען פון יעדער סדרה דריקט אויס דעם תוכן מיוחד פון דער סדרה³:\nוכמובן אויך פון תורת הבעש\"ט⁴ בנוגע עניני העולם בכלל, אז „שמו אשר יקראו לו בלה\"ק\" איז דער חיות פון דער זאך (ובמילא איז מרמז אויף איר תוכן).\nאון דער ענין, אז דער שם הפרשה איז ניט סתם לסימנא בעלמא, איז מוכח אויך פון דעם שם פון אונזער פרשה — תרומה⁵: אויב מ'זאל אננעמען אז דער נאמען פון יעדער סדרה איז בלויז ע\"ש התחלתה [נאר היות דער נאמען דארף אונטערשיידן איין סדרה פון דער צווי־טער, קען מען דערפאר ע\"פ רוב ניט נוצן אלס שם דעם ערשטן ווארט (אדער ווערטער) ממש פון דער סדרה (ווייל זיי זיינען די זעלבע בכמה סדרות, לדוגמא: אלה תולדות, ויאמר ה' וכיו\"ב), און מען מוז דעריבער אויסקלייבן א ווארט וואס שטייט בסמיכות צו התחלת הפרשה,\nוואס וועט אויסטיילן די סדרה פון אנדערע סדרות] —\nעפ\"ז האט מען לכאורה געדארפט אונזער פרשה אנרופן (ניט מיטן נאמען „תרומה\", נאר מיטן ווארט) „ויקחו\"⁶ וואס שטייט פריער און נעענטער צו התחלת הסדרה.\nפון דעם איז מובן אז דאס וואס מען רופט די סדרה בשם „תרומה\" איז (ניט בלויז צו מסמן זיין דערמיט די פרשה, אויסטיילן איר פון אנדערע פרשיות, נאר) ווייל ער גיט ארויס דעם אינהאלט פון דער סדרה, איר ענין כללי וואס טיילט איר אויס פון אלע אנדערע סדרות.\nדארף מען פארשטיין: לבד זאת וואס לכאורה איז אין ווארט „תרומה\" ניט אויסגעדריקט דער תוכן פון דער גאנצער סדרה (כדלקמן סעיף ב), איז נאכמער: דער ענין פון „תרומה\" איז ניט קיין חידוש וואס איז דוקא אין דער סדרה, ווארום עס זיינען פאראן כמה מיני „תרומה\", ובלשון חז\"ל⁷ „עשר",[["1","1","ראה לקו\"ש ח\"ה ע' 57 ואילך."],["2","2","ראה ירושלמי פסחים פ\"ד ה\"א."],["3","3","להעיר ממדרש תדשא פ\"כ: בכל הספרים הקדושים יש בהן חכמה ובינה ודיעה למה נכתבו ונקרא שמם כו' למה נקרא שמו בראשית כו'."],["4","4","ראה שער היחוד והאמונה פ\"א."],["5","5","עוד הוכחה לזה — מפ' נח ותולדות, כמשנת\"ל במ\"א (ראה לקו\"ש ח\"ה ע' 354 ואילך. ועוד)."],["6","6","עד\"ז נקרא ברמב\"ם בסדר תפלות שלו („ויקחו לי\"). ובראב\"ע ריש פרשתנו: בפרשת ויקחו לי תרומה. אבל במנהג ישראל בכו\"כ מקומות (ברובם), בכל החומשים שראיתי וכו' נקרא — תרומה. וראה עד\"ז בכמה סדרות, דנקראות ברמב\"ם וראשונים באופן א' (ובב' תיבות) ובמנהג ישראל (בדורות אחרונים?) בשם אחר (ובתיבה אחת), ולדוגמא: „ואתה תצוה\", „תצוה\" (הובא ונת' בלקו\"ש חט\"ז ע' 342, וש\"נ); „פקודי\", „אלה פקודי\" (ראה לקמן ע' 250 הערה 3); „זאת תהי'\", „מצורע\" (ראה לקו\"ש ח\"ז ע' 100, 103 ואילך); „ויקח קרח\", „קרח\" (לקו\"ש חי\"ח ע' 191. וש\"נ); „ראשי המטות\", „מטות\"; „אלה מסעי\", „מסעי\" (לקו\"ש חי\"ח ע' 382. וש\"נ). ועוד."],["7","7","ברייתא דמלאכת המשכן בתחלתה. יל\"ש כאן עה\"פ. וראה פי' הר\"א בן הרמב\"ם ריש פרשתנו."]]],[1300211160,"תרומות הן\", און בפרשתנו רעדט זיך נאר וועגן איין מין תרומה — די תרומה פאר מלאכת המשכן (און אפילו לויט דרשת חז\"ל⁸, איז (נאר) „ג' תרומות אמורות כאן\"); ובפרט אז „תרומה\" סתם, איז די תרומה וואס מ'גיט צום כהן⁹ — היינט ווי זאגט מען אז דער נאמען „תרומה\" האט אין זיך דעם תוכן מיוחד פון דער (גאנצער) סדרה, בשעת אז דער ענין התרומה — תרומה סתם — רעדט זיך אין אנדערע סדרות פון תורה (און מיט מער אריכות¹⁰ ווי וועגן תרומת המשכן דא)?\nב. ועוד: דער תוכן מיוחד פון אונזער סדרה איז בפשטות — דער ציווי אויף מלאכת עשיית ובנין המשכן. ולכאורה ווערט אט דער ענין בכלל ניט ארויסגעבראכט אין ווארט „תרומה\", וואס ווייזט נאר אויף דער הפרשה ונדבה פון אידן לצורך המשכן, אבער ניט אויף דער עשיית המשכן — „ועשו לי מקדש\": היינט ווי קען מען זאגן אז דער תוכן הסדרה — עשיית המשכן — ווערט ארויסגעבראכט אין (דעם ווארט) „תרומה\"?\nדי שאלה אין דעם איז נאך שטארקער: לכאורה וואלט מער מתאים געווען, אז די סדרה זאל זיך אנהויבן מיטן פסוק¹¹ „ועשו לי מקדש גו'\", וואס דאס איז די נקודה יסוד והקדמה פון אלע ציווים אין דער סדרה, כולל אויך דעם ציווי „ויקחו לי תרומה\" (וואס איז צוליב\nקענען מקיים זיין דעם ציווי „ועשו לי מקדש\"): האט דאך פריער געדארפט שטיין „וידבר גו' ועשו לי מקדש גו'\", און ערשט נאך דעם די ציווים ווי דאס זאל דורכגעפירט ווערן בפועל: „ויקחו לי תרומה גו'\" — נדבת המשכן, און (לאח\"ז) ווי צו בויען דעם משכן¹².\nפון דעם וואס דער פסוק איז מקדים דעם ציווי „ויקחו לי תרומה\" פארן פסוק „ועשו לי מקדש\", איז משמע להיפך, אז (דער ווארט) „תרומה\" ברענגט ארויס דעם תוכן ענין המשכן מער ווי דער פסוק „ועשו לי מקדש\"!\nויתירה מזו: דער ענין המשכן איז לכאורה דער היפך פון ענין ה„תרומה\": ענינו של משכן איז כשמו — (ע\"ש) „ושכנתי¹¹ בתוכם\"¹³, ד.ה. (ניט די עשיית המשכן, „ועשו לי מקדש\", נאר) די השראת השכינה אין משכן, און כל זמן ס'איז נאך דארט ניטא קיין שכנתי פון דער שכינה (כאטש מ'האט שוין פארענדיקט דעם גאנצן בנין) הייסט עס נאך ניט משכן (לאמיתתו)¹⁴.\nאון השראת השכינה שבמשכן קען זיך אויפטאן נאר דורך רצונו וכחו ית' הכל יכול, וכמאמר שלמה¹⁵: „הנה השמים ושמי השמים לא יכלכלוך אף כי הבית",[["8","8","ירושלמי שקלים פ\"א ה\"א. פרש\"י ר\"פ „אמרו רבותינו\"."],["9","9","בברייתא דמלאכת המשכן שם: תרומה גדולה. אבל ביל\"ש כאן: מתחיל תרומה (סתם), תרומת מעשר. וכ\"ה להלן בברייתא שם כשמתחיל לפרט: תרומה תרומת מעשר כו' לכהנים."],["10","10","ראה בס\"פ קרח."],["11","11","כה, ח."],["12","12","וע\"ד מ\"ש הרמב\"ן ריש פרשתנו (וראה פי' בעקב יוד, ה): הטעם ש„הקדים הארון והכפורת\", אף שקדם במעשה הוא עשיית המשכן את אהלו ואת מכסהו, „כי הוא מוקדם במעלה\" ד„עיקר החפץ במשכן הוא מקום מנוחת השכינה שהוא הארון\"."],["13","13","ראה ראב\"ע כאן כה, ח."],["14","14","ראה פרש\"י שמיני ט, כג. וראה אוה\"ח פרשתנו כה, ח סד\"ה ונראה שזהו הפי' (והחילוק): ועשו לי (ותיכף נעשה) מקדש, וכאשר שרתה בו שכינה — ה\"ז משכן. וראה כלי יקר (כו, א) ד\"ה ואת המשכן תעשה."],["15","15","מלכים א ח, כז."]]],[1300211161,"הזה\"¹⁶ (וואס דאס איז א תמי' קיימת, אז שכינתו ית' הבלתי מוגבלת, וואס „השמים ושמי השמים — כולל עולמות עליונים — לא יכלכלוך\", ווערט נמשך און איז שורה ושוכן „בבית הזה\"), וואס אין דעם איז מודגש, אז דאס קען אויפגעטאן ווערן בלויז מצד כחו ית' הבלתי מוגבל¹⁷, און ניט מצד כחו ופעולתו פון דעם אדם למטה —\nמשא\"כ דער פירוש ותוכן פון ווארט „תרומה\", וואס איז, אדרבה, מדגיש (ניט די השראת והמשכת אלקות במקדש וואס קומט מלמעלה, נאר) דאס וואס דער מענטש טוט אין דעם: און נאך מער אין ווארט „תרומה\" (ניט „מקדש\") איז אפילו ניט מרומז ווי די נדבת המשכן „קומט אן\" און ווערט דעם אויבערשטנ'ס, נאר בלויז די הפרשת האדם¹⁸?\nג. וועט מען דאס פארשטיין בהקדים א שאלה כללית אין דעם ענין: צוליב וואס דערציילט די תורה באריכות הכי גדולה וועגן תרומת המשכן עשיית קרשי המשכן היריעות וכו'? — וע\"ד שאלת חז\"ל¹⁹ „מאי דהוה הוה\"! תורה אליין זאגט אז דער משכן איז אן ארעי כמש\"נ²⁰ „ואהי' מתהלך באהל ובמשכן\", ס'איז נאר א ציווי „לפי שעה\"²¹ כמו שנאמר²² כי לא באתם עד עתה וגו'\", דער ציווי לדורות איז דער בנין המקדש בירושלים²³, דער בית עולמים — היינט וואס זיינען די פרטים פון משכן נוגע צו אידן לדורות בכל הזמנים ובכל המקומות²⁴, אויך נאכדעם ווי דער משכן איז נגנז²⁵ געווארן און במקומו איז געבויט געווארן דער בית המקדש?\nבשלמא דער סיפור (און דינים) וועגן דעם בנין פון די בתי מקדשות, כאטש אז אויך זיי זיינען חרוב געווארן, איז אן ענין וואס אידן דארפן וויסן בשייכות צום מקדש דלעתיד, ווייל דאס רוב ועיקר הבנין דלעתיד איז מיוסד אויפן סדר הבנין פון בית ראשון ושני²⁶; וואס איז אבער איצט נוגע צו וויסן די אלע פרטים פון תרומת ועשיית המשכן²⁷?\nנאך מער: בנוגע דעם בית המקדש איז די קריאה ולימוד פון די פרטי בנין הבית ניט נאר א הכנה והכשרה צום בנין דלעתיד, ווייל „כשיבנה ב\"ב יש לשמור",[["16","16","ועד\"ז אמר משה לגבי המשכן — ראה פסיקתא דר\"כ פ\"ב סוף פ\"ז. פס\"ר פט\"ז. תנחומא תשא יו\"ד (ועוד)."],["17","17","ראה אוה\"ת ויצא קעח, ב ואילך. ביאוה\"ז (להצ\"צ) ויצא ע' קד ואילך. ספר המאמרים פרנ\"ת ס\"ע קפג ואילך. ד\"ה רב ברכי' (פ\"ג) וד\"ה האומנים תרמ\"ג."],["18","18","כפרש\"י עה\"פ ד\"ה תרומה „הפרשה\" (וכן הוא בת\"א ותיב\"ע כאן). וההמשך בפרש\"י: „יפרישו לי מממונם נדבה\", היינו בפי' הכתוב „ויקחו לי תרומה\", וכהמשך (וסיום) לפירושו „ויקחו לי תרומה — לי לשמי\". וראה בארוכה לקו\"ש חט\"ז ע' 284 ואילך."],["19","19","יומא ה, ב. ועוד."],["20","20","שמואל ב ז, ו. ועי' פרש\"י שם. וראה זח\"ב רמא, א. ובכ\"מ."],["21","21","לשון הרמב\"ם ריש הל' בית הבחירה."],["22","22","ראה יב, ט."],["23","23","ראה רמב\"ם שם ה\"ג."],["24","24","בפרש\"י (כה, ט): וכן תעשו לדורות אם יאבד אחד מן הכלים או כשתעשו לי כלי בית עולמים כגון שולחנות ומנורות וכיורות ומכונות שעשה שלמה כתבנית אלו תעשו אותם. אבל זהו רק בנוגע לכלי המשכן, אבל לא בנוגע למשכן עצמו. ולהעיר מרמב\"ן שם: ולא ידעתי שיהי' זה אמת שיתחייב שלמה לעשות כלי בית עולמים כתבנית אלו. וראה רא\"ם גו\"א ט\"ז לפרש\"י. ובארוכה אוה\"ח שם."],["25","25","סוטה ט, א."],["26","26","ראה רמב\"ם בהקדמתו לפיה\"מ בנוגע למס' מדות. ובפתיחה למס' מדות בתוי\"ט."],["27","27","וראה בארוכה אוה\"ח שם."]]],[1300211162,"ולעשות התבנית ההוא כו'\"²⁸, נאר נאכמער: דורך קריאה ולימוד פון צורת הבית איז — ווי דער אויבערשטער האט געזאגט — „אני מעלה עליהם כאילו הם עוסקים בבנין הבית\"²⁹ (און כביאור חז\"ל²⁹ דורך דעם באווארנט מען אז עס זאל ניט זיין „בנין ביתי בטל\")³⁰ —\nבמה דברים אמורים ווען די קריאה ולימוד איז אין די ענינים פון בנין בית המקדש, וואס זיין בנין איז א מצוה לדורות (ס'איז נאר וואס בפועל קען מען איצט אים ניט בויען)³¹; משא\"כ דער משכן איז דאך געווען א ציווי נאר לשעתו.\nד. לכאורה וואלט מען געקענט ענטפערן, ווי מ'האט שוין גערעדט אמאל בארוכה³², אז דער ציווי „ועשו לי מקדש ושכנתי בתוכם\", כאטש עס שטייט בנוגע בנין המשכן, איז דאס אבער א ציווי לדורות אויף בויען א „בית לה'\"³³ — א ציווי אויף אלע בתי מקדשות כולל דעם מקדש דלעתיד (ד.ה. דער ציווי אויף אלע בתי מקדשות לערנט מען אפ פון דעם ציווי אויפן בנין המשכן).\nזאת ועוד: הגם אז דער ציור און פרטים פון מדת ארכו ורחבו פון ביהמ\"ק זיינען געווען אנדערש ווי אין משכן, זיינען אבער די ענינים העיקריים שבו געווען בדוגמת המשכן (כמבואר ברמב\"ם³⁴); אזוי אויך פון דעם ציווי אויף תרומת ונדבת המשכן, לערנט מען ארויס לגבי ביהמ\"ק, אז „הכל חייבין לבנות ולסעד בעצמן ובממונם אנשים ונשים\"³⁵.\nוואס לפ\"ז איז מובן, אז אויך די קריאה ולימוד פון מלאכת המשכן איז נוגע און העלפט אז דער בנין ביהמ\"ק זאל זיין כדבעי.\nויתירה מזו יש לומר (ע\"פ פנימיות הענינים): דאס וואס בפועל איז געווען באופן זה, אז פריער האט מען געבויט א משכן „לפי שעה\" (אין זמן פון „עדיין לא באתם עד עתה וגו'\") און ערשט דערנאך³⁶ א „בית לדורי הדורות\"³⁷, איז עס דערפאר וואס אזוי איז דער סדר און אופן קיום המצוה (מן הקל אל הכבד): פריער משכן (אוהל, ארעי) ולא באופן דנחלת המקום, און ערשט דערנאך האט געקענט זיין (בית, קביעות, נצחיות) דער בית עולמים בירושלים³⁸.\nאון דערפון איז אויך פארשטאנדיק בנוגע דעם לימוד וקריאה אין „צורת הבית\": כדי עס זאל זיך אויפטאן בשלימות דער „כאילו הם עוסקים בבנין הבית\" (פון בית המקדש), איז ניט גענוג די קריאה ולימוד אין תורת הבית, נאר פריער זאל זיין די קריאה ולימוד פון צורת המשכן — אויך פון די פרטים",[["28","28","ל' הרמב\"ם בפיה\"מ שם."],["29","29","תנחומא צו יד. ובכ\"מ."],["30","30","ראה בארוכה לקו\"ש חי\"ח ע' 411 ואילך. וש\"נ."],["31","31","ראה אוה\"ח שם, ח. ובארוכה — לקו\"ש שם."],["32","32","בביאור הרמב\"ם ריש הל' בית הבחירה — ראה לקו\"ש חט\"ז ע' 302 ואילך. וש\"נ."],["33","33","ל' הרמב\"ם שם."],["34","34","שם פ\"א ה\"ה. וראה שם פ\"ז הי\"א. ועוד. וראה לקו\"ש שם ע' 305 (סיו\"ד). וש\"נ."],["35","35","רמב\"ם שם פ\"א הי\"ב."],["36","36","להעיר מזח\"ב שם ואוה\"ח שם — הטעם בזה שלאחרי המשכן הוצרך להיות משכן שילה לפני בנין ביהמ\"ק בירושלים."],["37","37","רמב\"ם שם ה\"ג."],["38","38","להעיר ממשנ\"ת (לקו\"ש חי\"ז ע' 21 הערה 69), שהסדר דמשכן ביהמ\"ק (שלמה) וביהמ\"ק דלעתיד הוא — אור, כלי, דירה לעצמותו. ע\"ש."]]],[1300211163,"וואס זיינען ניטא אין מקדש; און ערשט דערנאך קען זיך אויפטאן (דורך קריאה בצורת הבית) דער „אני מעלה עליהם כאילו הם עוסקים בבנין הבית\"³⁹.\nדאס איז אבער ניט מספיק, ווארום וויבאלד אז התורה היא נצחית⁴⁰, איז כשם ווי בפועל איז געווען אזא זמן ומצב וואס דער משכן איז געשטאנען בפ\"ע, און מיטן בנין המשכן האט מען מקיים געווען די מצוה „ועשו לי מקדש\", דארף מען זאגן, אז אויך דער ענין איז א נצחי⁴¹ — אז ס'איז דא די הוראה ומעמד ומצב ברוחניות פון דעם ענין וקיום בנין המשכן⁴², ווי דאס איז בפ\"ע⁴³.\nה. והביאור בזה:\nבנוגע דעם זמן פון השראת השכינה למטה געפינט מען אין מדרשים צוויי דעות. לויט איין מאמר חז\"ל האט זיך דאס אויפגעטאן במ\"ת, וואס דעמאלט „בטל⁴⁴ גזירה ראשונה ואמר התחתונים יעלו לעליונים והעליונים ירדו לתחתונים ואני המתחיל שנאמר⁴⁵ וירד ה' על ה\"ס⁴⁶, וכתיב⁴⁷ ואל משה אמר עלה אל ה'\"; און אין אן אנדער ארט זאגן חז\"ל⁴⁸: „אימתי שרתה השכינה בארץ ביום שהוקם המשכן\"⁴⁹.\nומובן אז מר אמר חדא ומר אמר חדא ולא פליגי: די השראת השכינה במ\"ת איז געווען ווייל „אני המתחיל וירד ה' על ה\"ס\", און וויבאלד דאס איז געווען מצד למעלה, איז דעריבער, כאטש אז בשעת מעשה ווען „וירד ה' על ההר\", איז „כל הנוגע בהר מות יומת\"⁵⁰, ס'איז דא",[["39","39","וי\"ל שזה גופא מרומז (עכ\"פ) ברמב\"ם — בזה שהאריך להביא שם „וכבר נתפרש בתורה משכן שעשה משה רבינו והי' לפי שעה שנאמר כו' כיון שנכנסו לארץ העמידו המשכן בגלגל כו'\" — הסדר בהקמת המשכן גלגל שילה וכן נוב וגבעון עד ל„נבנה המקדש בירושלים\", שבזה מבואר לא רק הסדר שהי' בקיום המצוה ד„ועשו לי מקדש\" (דמאי דהוי הוי) כ\"א סדר הלימוד דהל' ביהב\"ח, שקיום מצות בנין ביהמ\"ק ע\"י שעוסקים בצורת הבית (כנ\"ל במדרשים, וכמו שמדגיש הרמב\"ם בריש ההלכות בהכתוב (תהלים קכב, ו) שהביא „שאלו שלום ירושלים גו'\" — ראה בארוכה לקו\"ש חי\"ח שם ע' 415־6) הוא כשלומדים ההלכות על סדר הרמב\"ם — כולל ומתחיל ע\"ד המשכן שעשה משה, גלגל שילה וכו'."],["40","40","תניא רפי\"ז."],["41","41","ובדוגמת מ\"ש הצפע\"נ (מפענ\"צ פ\"ה סי\"ב, וש\"נ) לענין שבועת משה, שהמתפתים בו חל הנדר, אף שהתיר שבועתו, ד„כיון שהשבועה כתובה בתורה הוה דבר הנמשך וכאילו השבועה ישנה תמיד\", ד„כל שכתוב בתורה הדבר הוי נצחי ולא רק מה שהי'\"."],["42","42","ולהעיר מהפי' בהגש\"פ: אלו הכניסנו לארץ ישראל ולא בנה לנו את בית הבחירה דיינו, שהרי יש להם משכן ובבנין ביהמ\"ק נתוספו עשרה נסים (רשב\"ם, כל בו, אבודרהם ועוד)."],["43","43","ובפרט שגם כפשוטו המשכן הוא נצחי (ולא נחרב כביהמ\"ק ורק נגנז (סוטה שם*), ויתירה מזו ארז\"ל (יומא עב, סע\"א. סוכה מה, ב) עה\"פ (פרשתנו כה, טו) עצי שטים עומדים — „שעומדים לעולם ולעולמי עולמים\", „שישובו\" — ראה פרש\"י יומא וסוכה שם. וראה בחיי פרשתנו שם. וראה תנא דבי אליהו רבה ספכ\"ה (כג): ומפני מה נטמן המשכן עד היום הזה מפני שעשאוהו הכשרים בנדבת לבם וקשה לפני הקב\"ה להפסיד כל מה שעשו הכשרים בנדבת לבם ולעתיד יבא הקב\"ה וישרה בתוכו כמדה הראשונה שנאמר כו' באתי לגני גו'. וראה לקו\"ש חט\"ז ע' 305. ע' 465 ואילך. *) ראה הערה 36."],["44","44","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["45","45","יתרו יט, כ."],["46","46","ולפי פי' המת\"כ כ\"ה הכוונה בב\"ר פי\"ט, ז."],["47","47","משפטים כד, א."],["48","48","במדב\"ר פי\"ג, ב. פי\"ב, ו. ובכ\"מ."],["49","49","ובלקו\"ת צו י, ד: ומעשה המשכן הוא תיקון לזה להיות דירה בתחתונים כו' וכמ\"ש ברבות בראשית פי\"ט כו'. וראה רד\"ה באתי לגני השי\"ת."],["50","50","יתרו שם, יב. *) וראה חדבא\"ר פי\"ח: אשריהן הצדיקים שאין שונא שולט להם ובמעשי ידיהם שכן מצינו במשכן כו' אבל במשכן שעשה שלמה שלט בו שונא כו'."]]],[1300211164,"קדושה אין דעם גשמי פון הר סיני, איז אבער „במשוך היובל\" — דער „סימן סילוק שכינה\"⁵¹ — איז „המה יעלו בהר\", דער הר סיני איז געבליבן ווי פריער, חול⁵².\nמשא\"כ די השראת השכינה במשכן איז געקומען דורך „ועשו לי מקדש\", ע\"י עשיית בנ\"י (און ווי דער פסוק איז דאס מדגיש אויך בא פרטי המשכן והכלים: ועשו⁵³, ואת המשכן תעשה⁵⁴, וכו'), און וויבאלד די השראת השכינה איז געקומען דורך עשיית האדם⁵⁵, איז די קדושה נקבע געווארן⁵⁶ אין דער\nחפצא (גשם) פון משכן⁵⁷, ס'איז געווארן א קדושה אין דעם משכן וחלקיו.\nבסגנון תורת החסידות ובלשון המדרש הנ\"ל: די השראת השכינה בשעת מ\"ת איז געווען מצד למעלה⁵⁸ — „ואני המתחיל שנאמר וירד ה' על ה\"ס\": און וויבאלד אז דער מכוון פון „עליונים ירדו לתחתונים\" איז, אז „תחתונים יעלו לעליונים\" (וועלט זאל ווערן א דירה לו ית'), און למעלה איז דאך „אין כח חסר פועל\"⁵⁹ — זיינען די „תחתונים\" געווארן א דירה לו ית'⁶⁰ (וואס דערפאר געפינט מען אז דער קול פון די עשה\"ד איז געקומען פון אלע ד' רוחות העולם און שמים וארץ⁶¹, דהיינו, אז וועלט האט „ארויסגעשריען\" דעם ענין פון „אנכי ה' אלקיך\").\nדי שלימות הכוונה איז אבער, אז די „תחתונים\" זאלן ווערן א דירה צום אויבערשטן ניט נאר דורך דעם „פועל\" וואס ווערט מצד כחו ית' (וואס איז ניט חסר פועל), און עס איז נאך אבער ניטא דער „קב שלו\"⁶² עשיית התחתון, נאר",[["51","51","שם, יג ובפרש\"י."],["52","52","לבד בנ\"י שפסקה זוהמתן (שבת קמו, א. וש\"נ) גם לאחרי במשוך היובל ולתמיד (ראה המשך תער\"ב ח\"ב ע' תתקלא). ואף שע\"י חטא העגל חזרה (זח\"א נב, ב. קכו, ב. ח\"ב קצג, סע\"ב) לא חזרה לגמרי (כדמוכח בשבת ושם וכו' שם. וראה חסד לאברהם מעין ראשון (עין כל נהר) פי\"ג. נצוצי אורות לזח\"ג יד, ב. לקו\"ש חי\"א ע' 10). ולהעיר מהדיוק חזרה ולא שהוא דבר חדש. ועצ\"ע."],["53","53","מתחיל מהארון (פרשתנו כה, יו\"ד ואילך) „ועשו ארון\", „ועשית בדי'\", „ועשית כפורת גו'\", וכן בכל פרטי הכלים. והקרשים (כו, טו ואילך)."],["54","54","כו, א."],["55","55","להעיר מאבות דר\"נ (פי\"א): גדולה מלאכה שאף הקב\"ה לא השרה שכינתו על ישראל עד שעשו מלאכה שנאמר ועשו לי מקדש ושכנתי בתוכם. ולהעיר מל' רש\"י פקודי (לט, מג) שמיני (ט, כג): יה\"ר שתשרה שכינה במעשה ידיכם."],["56","56","ראה גם לקו\"ש חט\"ז ס\"ע 205 ואילך (וש\"נ) עד\"ז לגבי קדושת א\"י, שחלות הקדושה בארץ נקבעה דוקא ע\"י מעשה הכיבוש. וגם בנוגע לקדושת המקדש וירושלים מפני השכינה ושכינה אינה בטלה (רמב\"ם הל' ביהב\"ח פ\"ו הט\"ז) קביעת הקדושה בהמקום היא מצד מעשה הקידוש שקדשה שלמה (ראה שם הערה 49). וראה גם לקו\"ש חי\"ט ע' 147. *) דכולל כל בנ\"י. ראה ויקהל לו, ד: העושים את כל מלאכת הקודש איש איש ממלאכתו אשר המה עושים. שם, ז: והמלאכה הי' דים (ובפרש\"י שם). פרש\"י שם לז, א: שנתן נפשו על המלאכה. פקודי לט, לב ובפרש\"י שם: ויעשו בני ישראל את המלאכה גו'."],["57","57","ואולי י\"ל שזהו החילוק בין הענין דהשראת השכינה (שזה הי' במ\"ת) ל„ושכנתי בתוכם\" שע\"ש נק' משכן (ראה תניא פמ\"א (נז, ב). אגה\"ק סכ\"ג (קלו, א)). ולהעיר מפלוגתת הראשונים בהשראת השכינה במקום המקדש והביאור בזה (בהס' שבהערה 17, וש\"נ)."],["58","58","ראה לקו\"ת ראה כח, ב. המשך תער\"ב ־ שם ע' תתקל ואילך. וראה לקו\"ש ח\"ח ע' 23 ואילך."],["59","59","ראה פרדס שי\"א פ\"ג — הובא ונת' בסהמ\"צ להצ\"צ מצות האמנת אלקות פי\"א. המשך תרס\"ו ע' ה ואילך. קלט ואילך. (וראה בהוספות שם ע' תרד ואילך — בהוצאת קה\"ת תשל\"ו. ובהוצאת תנש\"א ע' תרנו ואילך). ד\"ה שובה וד\"ה ולקחתם אעת\"ר."],["60","60","וראה לקו\"ש חי\"ט ע' 194־5, שזה נעשה בתחלת הבריאה מצד נתאוה הקב\"ה כו'."],["61","61","תנחומא שמות כה. שמו\"ר פ\"ה, ט. הובא ברש\"י יתרו כ, ב. תניא פלי\"ז."],["62","62","ב\"מ לח, א."]]],[1300211165,"עס זאל זיין א „פועל\" וואס ווערט געטאן דורך דעם תחתון, אז דער אדם בעבודתו זאל פון עוה\"ז מאכן א דירה לו ית'.\nאון דאס איז דער אויפטו פון משכן לגבי מ\"ת — אז דער „ושכנתי בתוכם\" האבן אידן ממשיך געווען דורך זייער עבודה — דורך „ועשו לי מקדש\".\nאון דערמיט ווערט פארשטאנדיק דער טעם וואס דער פסוק איז מקדים דעם ענין פון „ויקחו לי תרומה\" — ווייל אט דער ענין, אז די השראת השכינה (במשכן) קומט דורך דער עבודה פון אידן, דריקט זיך אויס אין דעם ענין פון „תרומה\", כדלקמן.\nו. „תרומה\" האט צוויי טייטשן: א) פירוש רש\"י⁶³ — הפרשה. ב) הרמה⁶⁴. די צוויי פירושים, וואס זיינען פארבונדן זב\"ז, זיינען ניט נאר מסביר אז די „הרמה\" (פון וועלט (ועניני': זהב וכסף גו')) צו אלקות טוט זיך אויף דורך „הפרשת\" האדם, נאר זיינען אויך מתאר דעם אופן העבודה והעלי':\nדער ווארט „תרומה\" — הפרשה — איז מדגיש, אז ניט אלץ וואס ער האט גיט דער אדם אוועק, ער שיידט אפ (א טייל) פון זיינע נכסים און איז דאס מרים, גיט אוועק אויבן, צום אויבערשטן „לי — לשמי\"⁶⁵.\nאון אין דעם איז דא א חילוק אין די צוויי אופני השראת השכינה הנ\"ל: בשעת דאס ווערט נמשך מצד למעלה — ווי בא מתן תורה — איז די השראת השכינה באופן שוה בכל חלקי העולם.\nמשא\"כ ווען די השראת השכינה ווערט אויפגעטאן דורך דער עבודה ופעולת התחתון, המטה, איז דא דער חילוק לפי דרגת נדיב לבו און דאס איז בסדר והדרגה, מן הקל אל הכבד: „תחתונים\" וואס זיינען ניט (בטל צו) אלקות, און דער איד בעבודתו איז מפריש פון זיי (תפסת מרובה לא תפסת⁶⁶) א חלק (פון וועלט) און איז דאס מרים, הויבט עס אויף צום אויבערשטן, און דערנאך גייט ער מדרגא לדרגא, און ער איז מפריש און מרים נאך (און א שווערן) חלק פון וועלט⁶⁷, ביז די גאנצע וועלט זאל ווערן א דירה פאר דעם אויבערשטן דורך עבודתו⁶⁸.\nאון דער חילוק הנ\"ל איז ניט נאר אין דעם סדר ואופן הבירור והעלי' פון וועלט, נאר דאס דריקט זיך אויך אויס אין אופן הביטול וואס די השראת השכינה איז פועל:\nווען דאס קומט מצד למעלה, פועל'ט דאס א ביטול אין מציאות העולם (ווארום דער גילוי שכינה גיט ניט קיין",[["63","63","ובתרגומים כאן, כנ\"ל הערה 18."],["64","64","זהר פרשתנו קמז, א. וראה לקו\"ש חט\"ז שבהערה 18."],["65","65","פרש\"י ריש פרשתנו. וראה לקו\"ש שם."],["66","66","חגיגה יז, א. וש\"נ."],["67","67","ע\"פ הנ\"ל יש לבאר סדר הפרשיות — יתרו משפטים תרומה (ראה לקו\"ש חט\"ז ע' 247): יתרו הוא פ' מתן תורה, המשכה מלמעלה למטה שפעלה (בישראל — גילוי האמונה, ובעולם) ביטול העולם; אחרי מ\"ת מתחילה העבודה דבירור העולם לייחד מציאות העולם עם אלקות. והסדר בזה הוא, דתחלה הוא פ' משפטים (מצות שכליות), הפעולה בשכל האדם, שנעשה „יחוד נפלא\" עם חכמתו ית' (תניא פ\"ה), ואח\"כ פ' תרומה — בירור והעלי' דעניני העולם. וראה לקו\"ש ח\"ג ע' 907 ואילך."],["68","68","ראה לקו\"ש (שנסמן לקמן הערה 75) יתירה מזו, שי\"ל שבהפרשת ונתינת מתנות כהונה מתבטאת שלימות הענין דדירה בתחתונים, גם בהחלק הנשאר ברשות האדם, שמשתמש בזה לא מפני שהם נכסיו שלו, אלא לפי שהקב\"ה „הוא הנותן לך\" — נתנו לו וצריך להשתמש בזה כפי רצון ה'."]]],[1300211166,"ארט פאר א מציאות וואס איז ניט אלקות), וכמחז\"ל⁶⁹ (ביי מ\"ת): צפור לא צווח כו' שור לא געה; משא\"כ דער ביטול מצד השראת השכינה וואס ווערט אויפגעטאן מצד עבודת ופעולת האדם (ובפרט בתחלת העבודה, ווען מ'הויבט אן „בויען דעם משכן\"), איז עס בלויז אן ענין פון „הפרשה\" — ער נעמט פון זיין מציאות און גיט עס אפ, איז דאס „מרים\" (העכער פון זיך) צום אויבערשטן, אבער ניט באופן אז ער איז מבטל בתכלית, שולל זיין עצם מציאות, א מענטש מצד עצמו קען ניט לגמרי שולל זיין און מבטל זיין דעם עצם המציאות שלו.\nאין מער כללות'דיקע אותיות: במתן תורה — ביטול התחתון, בעשיית המשכן — הזדככות התחתון.\nז. און דאס איז דער טעם וואס די תורה רעכנט אויס די אלע י\"ג⁷⁰ (ט\"ו⁷¹)\nפרטי דברים וואס זיינען דא אין דער תרומה פאר מלאכת המשכן, ווייל אין עבודת האדם צו מאכן פון די עניני העולם א דירה לו ית'⁷², איז די עבודה ועלי' פון יעדן חלק פון וועלט אין אן אנדער אופן⁷³ — ס'איז א באזונדער סארט תרומה (סיי בהפרשה סיי בה־רמה).\nועפ\"ז איז מובן וואס די תורה איז מקדים דעם ציווי „ויקחו לי תרומה\" פאר „ועשו לי מקדש\", און וואס דער שם הסדרה איז „תרומה\" — ווייל דער עיקר ענין וחידוש פון דער סדרה איז דער תכלית פון דירה בתחתונים (בבנין המשכן) וואס ווערט אויפגעטאן ע\"י עבודת ופעולת האדם, וואס סדרה — מן הקל אל הכבד (הפרשה ותרומה און ערשט דערנאך — מקדש) — דוקא דורכדעם פירט זיך אויס די שלימות הכוונה פון בריאת העולם.\nאון דאס איז דער ענין התרומה, די השראת השכינה ע\"י הפרשת האדם באופן הנ\"ל, לאחרי ווי עס איז געווען במ\"ת מצד הבורא (ואני המתחיל) — מצד עבודה, און דוקא דעמאלט ווערט נמשך עיקר שכינה בתחתונים⁷⁴.\nאון דערמיט איז אויך מובן וואס די סדרה הייסט „תרומה\", ווייל די שלימות און מעלה פון אלע (עשר) תרומות⁷⁵, איז",[["69","69","שמו\"ר ספכ\"ט."],["70","70","פרש\"י ריש פרשתנו (ודעת זקנים מבעה\"ת). תנחומא כאן ה. שהש\"ר פ\"ד, יג. זח\"ב קמת, א."],["71","71","בחיי כה, ז. כלי יקר פרשתנו שם, ג. וראה זח\"ב קלה, א. — ובראב\"ע (כה, ג) טז דברים! — וראה רא\"ם וחזקוני. וראה אוה\"ת (פרשתנו ע' א'שפג. א'שצ. א'תי. א'תיד). תיווך ב' הדיעות. ועד\"ז ברע\"ב ושד\"ח עה\"ת כאן. *) מה שמביא לקמן (כה, מ) בשם הגאון (הרס\"ג): „שמונה עשר דברים הם במשכן\" — אינו שייך למנין דידן, כי שם הכוונה להדברים שהיו במשכן (ראה ראב\"ע שם לפנ\"ז ובפי' הקצר: הארון כו' אור השכינה כו' קרבן עוף ובהמה כו' שחיטה כו'), ולא הדברים של תרומות (נדבת) המשכן (שמהם נעשה המשכן וכליו). *) י\"א שהכוונה לרב האי גאון על סמך שנמצאו ביטויים דומים להנ\"ל בשו\"ת רה\"ג שהובאה בפי' הר\"מ בוטריל לס\"י פ\"ד מ\"ב. ותמוה ביותר — לאחרי שבריבוי מקומות בהראב\"ע מובא „הגאון\" ולד\"ה הכוונה להרס\"ג. ואפילו את\"ל שהרה\"ג פי' כך אין זו הוכחה כלל שאין זה פי' הרס\"ג ולהוציא „הגאון\" דכאן — מפי' „הגאון\" בהראב\"ע בכל מקום!"],["72","72","ראה לקו\"ש ח\"ג ע' 907 ואילך."],["73","73","ראה לקו\"ש חי\"א ע' 112 ואילך."],["74","74","ראה המשך תער\"ב שם (ס\"ע תתקלה ואילך), דגילוי אלקות בדרך פשיטות בדוגמת לעתיד לבוא הי' בביהמ\"ק שהוא השלימות ד(ועשו לי מקדש —) משכן ד„בביהמ\"ק הי' התפיסה דאלקות בפשיטות ומי שהי' בביהמ\"ק הי' בו הרגש אלקות כו'\", ע\"ש. משא\"כ במ\"ת (ראה בהנסמן לעיל הערה 58)."],["75","75","ראה בארוכה לקו\"ש חי\"ח ע' 221 ואילך (סעיף ד־ח) דשלימות הענין דדירה בתחתונים הנ\"ל מתבטאת בהענין דהפרשת תרומה וכל מתנות כהונה."]]],[1300211167,"ווי עס ווערט אויסגעדריקט בפרשתנו, אין דער תרומה — הפרשה והרמה, עס ווערט א משכן — השראת השכינה ע\"י פעולת ועבודת האדם.\nח. עפ\"ז יש לבאר ווי אויך דער בנין ומצב המשכן בפ\"ע (ניט נאר אלס הכנה והקדמה צום בית המקדש) איז אויך אן ענין נצחי⁷⁶, התורה היא נצחית:\nדאס וואס דעמאלט האט זיך אנגעהויבן דער ענין ה„תרומה\", די עבודת המטה, איז געווען ניט נאר דערפאר וואס ס'איז נאך מ\"ת, נאך דעם „במשוך היובל\"⁷⁷ (דער סימן לסילוק שכינה⁷⁸) ובמילא האט זיך שוין ניט אנגעהערט בגלוי דער „וירד ה' על ה\"ס\", נאר אויך ווייל ס'איז געווען אין מדבר:\nמדבר ברוחניות⁷⁹ איז אן ארט (ומצב) וואס „לא⁸⁰ ישב אדם (העליון⁸¹ שעל הכסא) שם\" — ס'איז דארטן ניטא קיין ישב — גילוי אלקות; משא\"כ אן עיר מושב איז אן ארט וואו ס'איז דא גילוי אלקות — ישב אדם העליון שם.\nאון דאס איז בכללות דער חילוק צווישן משכן און ביהמ\"ק (בירושלים): דעם ביהמ\"ק האט מען אויפגעבויט נאכדעם ווי אידן זיינען געקומען „אל המנוחה ואל הנחלה\", ווען מ'איז ארויס פון מדבר און געקומען אין א מקום מושב בנ\"א; און געבויט האט מען אים אין אזא ארץ (ישראל) וואס אויף איר שטייט⁸² „תמיד עיני ה\"א בה מרשית\nהשנה ועד אחרית שנה\", און בארץ ישראל גופא — אין ירושלים, אן ארט פון יראת שלם⁸³ (שלימות היראה⁸⁴), ובירושלים עצמה — במקום וואס איז „שער השמים\"⁸⁵ —\nאיז דער ענין המקדש, די דירה לעצמותו, וואס מ'מאכט פון דברים תחתונים, אן אויפטו וואס קומט ניט אינגאנצן מצד עבודת האדם, נאר אויך מצד אשר אבחר, דער ג־טלעכער בחירה (וקדושה) וואס איז דארט שורה און מאכט זי (מער) מוכשר צו ווערן א כלי לאלקות.\nאין מדבר אבער, וואס איז ניט קיין מושב אדם, און איז כלל ניט ראוי צו זיין א כלי לאלקות; ואדרבה — ס'איז מדבר העמים⁸⁶, נחש שרף ועקרב וצמאון אשר אין מים⁸⁷ — דארט איז די עשיית המשכן (אויפמאכן דארט א דירה פאר דעם אויבערשטן) דורכאויס מצד עבודת האדם, באופן של תרומה, כנ\"ל.\nאון דערפאר, דוקא פון „מקדש המדבר\"⁸⁸ נעמט מען די הוראה און נתינת כח, אז אויך אין זמן הגלות ווען „אותותינו לא ראינו\"⁸⁹, אין אונזער „מדבר העמים\", עס זעט זיך ניט קיין גילוי אלקות, ס'איז א חושך כפול ומכופל, איז אויך אין אזא מעמד ומצב האט מען דעם כח צו בויען א משכן — ושכנתי בתוכם — פאר דעם אויבערשטן.",[["76","76","שעפ\"ז יומתק זה שהמשכן הוא קיים לעולם (ראה הערה 43)."],["77","77","יתרו יט, יב-יג."],["78","78","פרש\"י שם, יג."],["79","79","ראה לקו\"ת ראה לב, סע\"ב ואילך. ובכ\"מ."],["80","80","ירמי' ב, ו."],["81","81","לקו\"ת נשא כ, ג. ראה שם."],["82","82","עקב יא, יב."],["83","83","ב\"ר פנ\"ו, יו\"ד. תוד\"ה הר תענית טז, א."],["84","84","לקו\"ת ר\"ה ס, ב. שה\"ש ו, ג. ובכ\"מ."],["85","85","ויצא כח, יז. ובמדרז\"ל שם."],["86","86","יחזקאל כ, לה. וראה בחיי, אוה\"ח ר\"פ מסעי. לקו\"ת ר\"פ נשא. ובכ\"מ."],["87","87","עקב ח, טו."],["88","88","ל' הרמב\"ם הל' ביהב\"ח פ\"א הי\"ב."],["89","89","תהלים עד, ט."]]],[1300211168,"ט. ע\"פ הנ\"ל וועט מען אויך פארשטיין דעם טעם פארוואס דער ציווי אויף בנין המקדש לערנט מען אפ פון משכן דוקא (כנ\"ל סעיף ד'):\nוויבאלד אז דער אויפטו פון השראת השכינה במקדש (לגבי מ\"ת) איז דאס וואס עס ווערט אויפגעטאן מצד עבודת האדם, און דער ענין איז געווען בעיקר און מער בגלוי אין משכן שבמדבר דוקא, און דערפון „לערנט מען אפ\" אז דאס איז דער עיקר הדגשה אויך אין מקדש.\nועפ\"ז יש לבאר בפנימיות הענינים וואס דער רמב\"ם איז מדייק צו אנרופן דעם משכן — „מקדש המדבר\", אין דער הלכה „הכל חייבין לבנות ולסעד בעצמן ובממונם אנשים ונשים כמקדש המדבר\" — כאטש אז דערמאנענדיק דעם משכן אין א פריערדיקער הלכה⁹⁰ זאגט ער ניט דעם לשון „מקדש המדבר\"⁹¹:\nאט דער ענין וואס איז דא ביי בנין ביהמ\"ק „לבנות ולסעד בעצמן ובממונם\" — עבודת האדם באופן של תרומה — נעמט זיך פון (און איז בדוגמת) „מקדש המדבר\", „אשר לא ישב אדם שם\", וואס דארט איז ניט קיין ארט וואס האט א שייכות צו גילוי\nאלקות און דער משכן איז געמאכט געווארן דורכאויס ע\"י עבודת ופעולת האדם, כנ\"ל.\nיו\"ד. דאס איז אויך די הוראה פון ענין המשכן ותרומתו פאר יעדן איינעם בפרט און אין יעדן זמן וואו ער געפינט זיך:\nעס טרעפט זיך לעת מן העתים, אז א איד פילט בא זיך אז ער איז אין א מעמד ומצב פון „מדבר\", „אשר לא ישב אדם שם\" — עס איז ניטא בא עם ר\"ל „ישב\" פון קיין ענין שבקדושה און ג־טלעכקייט, קען ער דעמאלט ח\"ו אריינפאלן אין יאוש — זאגט מען אים, אז ס'איז דא דער „מקדש המדבר\", ואדרבה: דער ציווי „ועשו לי מקדש ושכנתי בתוכם\" האט זיך אנגעהויבן און איז געווען בפועל אויף דעם משכן ווי די אידן זיינען (אין א מעמד ומצב פון) במדבר.\nאון דורך דעם וואס א איד מאכט א משכן זייענדיק אין א מצב פון מדבר, ווערט דער יתרון האור מן החושך⁹², ביז ער קומט צו „מדבר דקדושה\" — צו די בחי' פון „כי לא אדם הוא\", וואס איז העכער פון בחי' אדם העליון⁹³.\n(משיחות ש\"פ תרומה תש\"מ)",[["90","90","בריש הל' בית הבחירה לא כתב (משכן שעשה משה רבינו) במדבר."],["91","91","משא\"כ לפנ\"ז בה\"ה שכתב „כעין קלעי החצר שהיו במדבר\"."],["92","92","קהלת ב, יג."],["93","93","ראה לקו\"ת במדבר ד, ג ואילך. שה\"ש כב, א. כג, סע\"ב ואילך. ועוד. וראה לקו\"ש חט\"ז ע' 473."]]],[1300211169,"<h3>תרומה ב</h3>\nא. אין אנהויב פרק ד פון הלכות בית הבחירה, נאך דעם ווי דער רמב\"ם שרייבט וואס האט זיך געפונען אין „קדש הקדשים\" — אז „אבן היתה בקדש הקדשים במערבו שעלי' הי' הארון מונח כו'\" — איז ער ממשיך:\n„ובעת שבנה שלמה את הבית וידע שסופו ליחרב בנה בו מקום לגנוז בו הארון למטה במטמוניות עמוקות ועקל־קלות, ויאשיהו<sup data-n=\"1\">1</sup> המלך צוה וגנזו במקום שבנה שלמה שנאמר*<sup data-n=\"1\">1</sup> ויאמר ללוים המבינים לכל ישראל הקדושים לה' תנו את ארון הקודש בבית אשר בנה שלמה בן דויד מלך ישראל אין לכם משא בכתף עתה עבדו את ה' אלקיכם וגו' ונגנז עמו מטה אהרן וכו' וכל אלו לא חזרו בבית שני. ואף אורים ותומים שהיו בבית שני לא היו משיבין ברוח הקודש כו'\".\nדארף מען פארשטיין (ווי מפרשים<sup data-n=\"2\">2</sup> פרעגן): למאי נפק\"מ להלכה די גאנצע אריכות וסיפור הדברים, וואו און ווי אזוי און דורך וועמען דער ארון איז נגנז געווארן? דברי הרמב\"ם בספרו יד החזקה זיינען דאך „להלכה אמורים . . ודברים שאין יוצא מהן דין מהדינים ולא מוסר והנהגה וידיעה הצריכה אין מדרכו ז\"ל להטפל בהם בחיבור זה\"?\nנאך מער: אט־דער ענין (ווי אזוי און וואו איז דער ארון נגנז געווארן) איז „במחלוקת שנוי\"<sup data-n=\"3\">3</sup> — היינט צוליב וואס איז דער רמב\"ם מכריע כדברי האחד<sup data-n=\"4\">4</sup> ויבאלד אז דער ענין איז לכאורה ניט נוגע לדינא?\nב. מפרשים<sup data-n=\"2\">2</sup> פארענטפערן, אז „צורך גדול יש לרבינו בדבר זה לפי שיטתו שתפס לו לקמן בפ\"ו מהל' הללו<sup data-n=\"5\">5</sup> . . ש־קדושת הבית לא בטלה . . דסבר רבינו דהך מילתא דקדושת הבית לא בטלה אזלא כמאן דס\"ל ארון במקומו נגנז . . ועכ\"פ לענין ביאת מקדש מסתברא דבהכי תליא דהא כתיב<sup data-n=\"6\">6</sup> (ל)מבית לפרוכת (ו)אל פני הכפורת וכו'\".\nאבער צ\"ע אין דעם תירוץ, ווייל\n[נוסף לזה וואס דער רמב\"ם אליין איז מבאר טעמו<sup data-n=\"7\">7</sup> פארוואס „קדשה לשעתה וקדשה לעתיד לבא\" — „לפי שקדושת המקדש וירושלים מפני השכינה ושכינה אינה בטלה\"<sup data-n=\"8\">8</sup> — וואס אין דעם איז לכאורה ניט נוגע דוקא דער (מקום ה)ארון — איז ניט מובן]:\nלפי זה האט דער רמב\"ם געדארפט זאגן בקיצור ובפירוש, אז „ארון במקומו נגנז\"; אבער דער רמב\"ם איז —\nא) סותם „בנה בו מקום לגנוז בו הארון\" — וואס מ'קען לערנען אז דער ווארט „בו\" באציט זיך צום „בית\" (וואס",[["1","1","יומא נב, ב. וש\"נ. *1) דה\"ב לה, ג. וראה רד\"ק שם, שהעתיק לשון דומה ללשון הרמב\"ם בשם רז\"ל."],["2","2","חידושים וביאורים להיעב\"ץ על אתר. וראה חת\"ס לחולין ז, א ד\"ה קדושה ראשונה."],["3","3","יומא נג, סע\"ב. ברייתא דמלאכת המשכן פ\"ז. ובכ\"מ."],["4","4","ראה לקמן הערה 12."],["5","5","בסופו (הט\"ז)."],["6","6","אחרי טז, ב."],["7","7","שם הט\"ז."],["8","8","ומפורש ברמב\"ם (שם הי\"ד) דקדושה זו נעשית (א) ע\"י מעשה הקידוש „שקדשה שלמה\", (ב) ביחד עם זה ש„קידש (שלמה) העזרה וירושלים\" — ולא מפני שהארון הוא במקומו."]]],[1300211170,"שטייט גלייך פאר דעם), און ניט צו „קודש הקדשים\" (לפני פניו). קומט אויס אז העיקר חסר מן הספר — דער ענין פון „ארון במקומו נגנז\" איז ניט מודגש אין דברי הרמב\"ם.\nב) ער ברענגט ניט דערויף דעם פסוק (וואס ווערט געבראכט אין גמרא<sup data-n=\"9\">9</sup> „ויהי שם עד היום הזה\"<sup data-n=\"10\">10</sup>, וועלכער איז מדגיש אז דער ארון געפינט זיך (אויך איצט<sup data-n=\"11\">11</sup> במקומו.\nג) ועיקר: דאס פארענטפערט אינ־גאנצן ניט פארוואס דער רמב\"ם ברענגט יע (די דיעה) אז יאשיהו האט גונז געווען דעם ארון, וואס דאס איז כלל ניט נוגע להענין, צי דער ארון איז במקומו נגנז<sup data-n=\"12\">12</sup> (אדער אין לשכת העצים)<sup data-n=\"13\">13</sup>.\nד) נאך מער: אין די ביידע ענינים\n(בנוגע דעם מקום גניזת הארון, און ווער עס האט אים גונז געווען) איז דער רמב\"ם מאריך מיט כמה וכמה פרטים:\n(א) אז שלמה המלך האט געבויט דעם ארט וואו צו גונז זיין דעם ארון:\n(ב) אז דער מקום איז געווען „למטה במטמוניות עמוקות ועקלקלות\":\n(ג) אז יאשיהו המלך צוה וגנזו — ניט סתם גנזו<sup data-n=\"14\">14</sup>:\n(ד) אז „וגנזו במקום שבנה שלמה\" — ניט „וגנזו שם\":\n(ה) ער ברענגט דערויף א ראי' פון פסוק,\n(וא\"ו) איז דערצו מעתיק פון פסוק אויך די ווערטער („ללוים המבינים לכל ישראל הקדושים לה' . . בן דויד מלך ישראל אין לכם משא בכתף עתה עבדו את ה\"א וגו'\"), וועלכע זיינען, לכאורה, ניט נוגע צו דער הוכחה אז „יאשיהו המלך צוה וגנזו במקום שבנה שלמה\" —\nוואס איז די נפקותא לדינא פון די אלע פרטים הנ\"ל?\nג. אויך דארף מען פארשטיין:\nא) פון פשטות לשון הרמב\"ם („וידע שסופו ליחרב בנה בו מקום\") איז משמע, אז שלמה האט דעם „מקום\" אין ביהמ\"ק געבויט מדעת עצמו (ווייל „ידע שסופו ליחרב\"). איז תמוה: אלא חלקי ופרטי הבית זיינען דאך געבויט גע־וארן ע\"פ ציווי ה' — „הכל בכתב מיד ה' עלי השכיל\"<sup data-n=\"15\">15</sup> — איז ווי קומט עס אז",[["9","9","יומא שם. ברייתא דמלאכת המשכן שם."],["10","10","מלכים א ח, ח."],["11","11","שהרי זה נוגע בעיקר לדברי היעב\"ץ, שלכן הנכנס לשם בזמן הזה חייב. עיי\"ש."],["12","12","ובפרט דהא דיאשיהו גנזו אין מכריח לומר שלא גלה לבבל, כמ\"ש בכמה מפרשים (גבורת ארי ליומא (מילואים) נג, ב ד\"ה תנו. שער יוסף (להחיד\"א) להוריות יב, א ד\"ה צוה וגנזום) שי\"ל דכו\"ע מודו דארון נגנז בימי יאשיהו גם למ\"ד דגלה לבבל (אלא שלמ\"ד זה נתגלה למחריבים מקום גניזתו ונטלוהו). ואף שמזה שהרמב\"ם מסיים כאן (לאחרי שכותב „וגנזו\") „וכל אלו לא חזרו בבית שני\" לא משמע כ\"כ שס\"ל שגלה לבבל (וראה מאירי יומא נב, ב שמ\"ד שבמקומו נגנז גנזו יאשיהו), הרי סו\"ס לא מודגש בלשון זה (דיאשיהו גנזו) עיקר המכוון בדבריו דבמקומו נגנז ונמצא שם עד היום. וראה חסדי דוד לתוספתא סוטה (פי\"ג, ב) דמ\"ד דארון במקומו נגנז פליג אתנא קמא, דסבר שלא גנזו יאשיהו כלל אלא נגנז מעצמו."],["13","13","ולהיעב\"ץ שם נוגע רק הא דבמקומו נגנז (אף שהביא זה רק בניגוד לדעה שגלה לבבל, ולא הביא הדיעה דנגנז בלשכת העצים), לפי שרק אז שייך האיסור דביאת מקדש מצד „מבית לפרוכת אל פני הכפורת\"."],["14","14","כביומא (נב, ב. נג, סע\"ב). ברייתא הנ\"ל [משא\"כ בהוריות יב, רע\"א (ועד\"ז בתוספתא סוטה פי\"ג, ב): יאשיהו מלך יהודה . . צוה וגנזום]."],["15","15","דה\"א כח, יט — הובא בהקדמת הרמב\"ם לפיה\"מ (בנוגע למס' מדות). וראה עירובין קד, א. סוכה נא, סע\"ב."]]],[1300211171,"שלמה זאל צובויען א „מקום\" אין ביהמ\"ק מדעת עצמו?\nב) וואס איז דער רמב\"ם מסיים הנ\"ל (ובאריכות) בנוגע אורים ותומים בבית שני — לכאורה: אמת טאקע די אורים ותומים האבן א צד השווה מיט דעם וואס „לא חזרו בבית שני\"<sup data-n=\"16\">16</sup> — אבער דער גאנצער ענין פון אורים ותומים געהערט ניט צו הלכות בית הבחירה, נאר צו בגדי כהונה, וואס מקומם איז אין „הלכות כלי המקדש והעובדים בו\" (און דער רמב\"ם ברענגט עס טאקע דארטן<sup data-n=\"17\">17</sup>) — צוליב וואס ברענגט דער רמב\"ם דעם ענין דא אין הלכות בית הבחירה?\nמוז מען זאגן, אז די שייכות פון אורים ותומים צום ארון איז ניט נאר אין דעם וואס „לא חזרו בבית שני\", נאר זיי האבן א שייכות צום עצם ענין הארון, און מהאי טעמא ווערט עס געבראכט אין הלכות בית הבחירה צוזאמען מיט דיני הארון.\nד. וועט מען דאס פארשטיין בהקדים א דיוק בנוגע דעם ארט, וואו די דאזיגע הלכה שטייט אין רמב\"ם:\nאין אנהויב הלכות בית הבחירה זאגט דער רמב\"ם<sup data-n=\"18\">18</sup> „אלו הן הדברים שהן עיקר בבנין הבית, עושין בו קדש וקדש הקדשים . . אולם כו'\", און דערנאך<sup data-n=\"19\">19</sup> זאגט ער „ועושין במקדש כלים וכו'\", און רעכנט אויס די כלי המקדש ומקומן.\nאין די ווייטערדיקע פרקים — פרק ב' וג' — איז דער רמב\"ם מבאר צורת הכלים כו', און אין פרק רביעי — צורת\nהבית (כותלי הבית, היכל, שערים וכו').\nשטעלט זיך די שאלה: דער ארון בא־לאנגט לכאורה צו כלי המקדש — היינט ווי פאסט אריין די (אריכות אין דער) הלכה הנ\"ל וועגן גניזת הארון, אין פרק רביעי (צורת הבית)?\nאיז דערפון גופא געדרונגען, אז דאס וואס דער ארון געפינט זיך אין קדה\"ק, איז (לדעת הרמב\"ם) א פרט פון צורת הבית; דער ארון איז ניט נאר א כלי, וואס געפינט זיך אין קדש קדשים (ע\"ד ווי די אנדערע כלי המקדש וועלכע גע־פינען זיך אין היכל וכו'), נאר ער איז א טייל פון דעם קדש הקדשים (בנין) עצמו<sup data-n=\"20\">20</sup> — וויבאלד אז דער ארון מאכט דעם ביהמ\"ק פאר א „בית לה'\"<sup data-n=\"21\">21</sup>, כמ\"ש<sup data-n=\"22\">22</sup> ונועדתי לך שם.\n[און דערמיט איז מוסבר וואס דער רמב\"ם רעכנט ניט דעם ארון צווישן די כלי המקדש וואס ער איז מפרט אין דער הלכה הנ\"ל (אין אנהויב הלכות בית ה־בחירה)<sup data-n=\"23\">23</sup>: „ועושין במקדש כלים וכו' — ווייל דער ארון איז ניט קיין כלי (בפ\"ע): ס'איז א טייל פון קדש הקדשים<sup data-n=\"24\">24</sup>].",[["16","16","ראה יומא (כא, ב) שהאו\"ת והארון הם מה„חמשה דברים שהיו בין מקדש ראשון למקדש שני\". ראה כס\"מ כאן."],["17","17","פ\"י ה\"י."],["18","18","פ\"א ה\"ה."],["19","19","ה\"ו ואילך."],["20","20","משא\"כ שאר הכלים, דאף שלדעת הרמב\"ם גם הם נכללים בכלל מצות בנין ביהמ\"ק, כמ\"ש בסהמ\"צ מ\"ע כ ושם שרש יב — הרי זה רק שהם בכלל המ\"ע דועשו לי מקדש באופן שיהי' בית לה' מוכן להיות מקריבים בו הקרבנות (רמב\"ם ריש הל' בית הבחירה. וראה בארוכה לקו\"ש חי\"א ע' 120 ואילך), אבל סו\"ס הם כלי המקדש (כלשונו שם ריש הלכה ה'), משא\"כ הארון שהוא (היינו מציאותו בבית קדה\"ק) חלק „בבנין הבית\"."],["21","21","ל' הרמב\"ם ריש הל' ביהב\"ח."],["22","22","פרשתנו כה, כב. וראה לקו\"ש ח\"ד ע' 1346 ובהערות שם."],["23","23","ועד\"ז בסהמ\"צ שם, כשמפרט הכלים שהם מכלל המ\"ע דבנין המקדש."],["24","24","לכללות ענין זה — ראה גם לקו\"ש ח\"ד שם. חי\"א ע' 118 הערה 24. וש\"נ. *) וראה לקמן ע' 252 ואילך."]]],[1300211172,"עפ\"ז ווערט אבער א תמיהה גדולה: לויט דעם וועט אויסקומען, אז אין בית שני, וואס דארט האט זיך דער ארון ניט געפונען (במקומו), איז דער קדש הקדשים (פון וועלכן דער ארון איז א חלק) ניט געווען בשלימותו: דאס הייסט, אז בבית שני האט געפעלט (ניט נאר א פרט, נאר) איינער פון די דברים וואס זיינען אן „עיקר בבנין הבית\"?!\nאון אויף צו אראפנעמען אט די תמיהה, ברענגט דער רמב\"ם די גאנצע אריכות וועגן גניזת הארון, וואס דער־מיט ווערט פארשטאנדיק אז אויך בבית שני האט ניט געפעלט „בבנין הבית\"<sup data-n=\"25\">25</sup>.\nה. דער ביאור בזה:\nדאס וואס דער רמב\"ם זאגט „ובעת שבנה שלמה את הבית כו' בנה בו מקום לגנוז בו הארון כו'\" איז הכוונה בזה ניט צו מכריע זיין וואו דער ארון איז נגנז געווארן (ווארום מאי דהוה הוה), נאר ער מיינט מיט דעם מחדש זיין א דין אין בנין הבית.\nדי גניזת הארון איז ניט נאר אן ענין פון „בדיעבד\" ולית ברירה<sup data-n=\"26\">26</sup>, נאר ביים בנין הבית איז מלכתחילה אויסגע־שטעלט געווארן, אז דער ארון זאל (כאילו) האבן צוויי מקומות אין ביהמ\"ק: א) א מקום גלוי, אויף דער אבן שתי' בקדש הקדשים: ב) א מקום צו גונז זיין אים, „למטה\" מקדש הקדשים („במטמו־ניות עמוקות ועקלקלות\") — אויך דער\nארט איז מלכתחילה א חלק פון דעם בית<sup data-n=\"27\">27</sup>.\nדאס הייסט: די גניזת הארון איז ניט קיין ענין נוסף אויפן בית המקדש (וואס איז געטאן געווארן כדי צו (און בשעת מ'האט געדארפט) באהאלטן און פאר־היטן דעם ארון), נאר דאס איז א דין אין בנין הבית: כשם ווי צוליב שלימות המקדש מוז געבויט ווערן א מקום (קדש קדשים) וואו דער ארון זאל שטיין באופן גלוי, אזוי דארף דער ביהמ\"ק אויך האבן א מקום גניזה (אין קדה\"ק<sup data-n=\"28\">28</sup>) פאר דעם ארון (און דערמיט ווערט באווארנט די נצחיות פון קדש הקדשים, היות אז דער ארון איז א חלק (עיקרי) פון קדה\"ק, כנ\"ל).\nאון דאס איז דער פירוש פון דברי הרמב\"ם „ובעת שבנה שלמה כו' וידע שסופו ליחרב בנה בו מקום כו'\": ניט אז שלמה האט געבויט דעם מקום מדעת עצמו, ח\"ו, נאר ער האט ביים בויען געמוזט וויסן אז יחרב און מ'האט אים געהייסן און בנה דעם מקום גניזה:\nדער ארון דארף דאך געפינען זיך אין קדש הקדשים; איז ווען שלמה וואלט סתם אויסגעגראבן א מקום למטה (ע\"פ ציווי), ניט וויסנדיק דעם תכלית דער־פון, וואלט אויסגעקומען, אז בעת הבנין<sup data-n=\"29\">29</sup> איז דער מקום ניט נתקדש גע־",[["25","25","והרי לימוד צורת בית שני נוגע למ\"ע לדורות של בנין ביהב\"ח (ראה פיהמ\"ש להרמב\"ם בהקדמתו בנוגע למס' מדות. תויו\"ט בפתיחתו למס' מדות. לקו\"ש חי\"ח ע' 416 ואילך)."],["26","26","להעיר מחסדי דוד לתוספתא שם דלמ\"ד ארון במקומו נגנז — „בשעה שבאו האויבים למקדש, מעצמו נגנז במקומו\"."],["27","27","ראה תוס' הרא\"ש להוריות יב, א. צפע\"נ עה\"ת בהפטרת פ' פקודי — שזהו מה שאמר שלמה (מלכים א ח, כא) ואשים שם מקום לארון."],["28","28","ועפ\"ז הנ\"ל ס\"ד — שתוכן פרק זה ברמב\"ם הוא ע\"ד צורת הבית, ובהלכה א' מפרש ע\"ד קדש הקדשים (ושהארון הוא פרט וחלק ממנו) — מובן בפשטות שכוונת הרמב\"ם ב„בנה בו מקום כו'\" היא לקדה\"ק."],["29","29","דבעינן קידוש בשעת בנין — ראה שבועות טו, ב."]]],[1300211173,"וארן אלס א מקום ל(קדושת) ארון<sup data-n=\"30\">30</sup> (אין קדש קדשים).\nאיז דער רמב\"ם מדגיש, אז „שלמה . . ידע שסופו ליחרב (און דערפאר) בנה בו מקום לגנוז בו הארון\" — ער האט מלכתחילה געבויט א מקום גניזה פארן ארון [ווי דער רמב\"ם איז מדגיש, אז עס איז געווען א מקום (מתאים לגניזה —) „למטה במטמוניות עמוקות ועקל־קלות\"], איז במילא מובן אז ער האט עס מקדש געווען<sup data-n=\"31\">31</sup> אלס (מקום הארון, ובמילא) א טייל פון קדש קדשים<sup data-n=\"32\">32</sup>.\nו. על פי זה וועט אויך זיין פאר־שטאנדיק דער טעם וואס דער רמב\"ם איז ממשיך ומוסיף, אז „יאשיהו המלך צוה וגנזו במקום שבנה שלמה\":\nכדי נאך מער צו מוכיח זיין אז גניזת הארון במקום זה איז (ניט אן ענין פון „בדיעבד\", נאר איז) געווען מלכתחילה אויסגעשטעלט (— אז דאס זאל זיין מקומו (הגנוז) של הארון, אלס א טייל פון קדש הקדשים) —\nאיז דער רמב\"ם מבאר, אז אויך גניזת הארון איז פארגעקומען (ניט בעת החורבן — דער זמן פון בדיעבד,<sup data-n=\"26\">26</sup> נאר) בעת דער ביהמ\"ק איז ניט געווען בסכנה כלל — כידוע תוקף יד ישראל\nבזמן יאשיהו — און וואס נאך מער, אז די הכנסה למקום גניזתו איז געווען ע\"ד ומעין הכנסת הארון לקדש הקדשים ע\"י שלמה:\n(א) יאשיהו המלך איז געווען דער וואס „צוה\" לגנוז (ע\"ד ווי הכנסתו לקדש הקדשים ע\"י שלמה המלך)<sup data-n=\"33\">33</sup>, (ב) די הכנסה איז דורכגעפירט געווארן דורך „הלוים המבינים לכל ישראל הקדושים לה'\" — ע\"ד ווי ביי שלמה וואס „ויביאו<sup data-n=\"34\">34</sup> הכהנים את ארון ברית ה' אל מקומו\"<sup data-n=\"35\">35</sup>.\nאון דערפאר איז דער פסוק מדייק צו זאגן דעם לשון „תנו את ארון הקדש בבית אשר בנה שלמה גו'\" — ס'איז ניט א פעולה פון סילוק ונטילת הארון ממקומו, נאר פארקערט, עס איז נתינה בבית<sup data-n=\"36\">36</sup>. און דערפאר ברענגט דער רמב\"ם אויך דעם סיום הכתוב „אין לכם משא בכתף עתה עבדו את ה' אלקיכם גו'\", כאטש דער ארון וועט פון יעצט אן זיין אין א מצב פון גניזה, ובמילא „אין לכם (די אפשריות פון) משא בכתף\", איז עס אבער ניט אז ס'איז דא איצט א חסרון אין דער עבודה פון ביהמ\"ק, נאר „עבדו את ה' אלקיכם גו'\" אין ביהמ\"ק (ווייל דורך דעם פעלט ניט אין בנין הבית).",[["30","30","ראה מנחות כז, סע\"ב — דמקום הארון יש לו קדושת ארון „מקום המקודש לקודש\"."],["31","31","כי אף שדוד קידש עד התהום (זבחים כד, א), הרי גם שלמה קידש (הוסיף בקידוש) כל' הרמב\"ם הל' ביהב\"ח פ\"ו הי\"ו (ובפרט ע\"י הקרבנות שלו וכו'). ואכ\"מ."],["32","32","עפ\"ז יש לבאר מה שכייל הרמב\"ם בהלכה זו ע\"ד צנצנת המן ומטה אהרן — הן בתחלת ההלכה „ולפניו צנצנת המן ומטה אהרן\", והן בסופה „ונגנז עמו מטה אהרן והצנצנת ושמן המשחה וכל אלו לא חזרו כו'\" — כי מזה מוכח עוד יותר שגם במקום שנגנז הארון הוי מקום ארון, שלכן בענינים אלה שדינם הוא להיות במקום הארון, נגנזו עמו (וראה גבורת ארי יומא נב, ב. וש\"נ)."],["33","33","עפ\"ז תומתק הדגשת הרמב\"ם „ויאשיהו המלך\", וכן בלשון הפסוק שהביא „שלמה בן דויד מלך ישראל\", כי הקידוש וכו' קשור עם המלך — ראה רמב\"ם שם פ\"ו הי\"א."],["34","34","מלכים א ח, ו."],["35","35","כדמוכח מסיום הפסוק שהביא כאן „אין לכם משא בכתף\", שלדעת הרמב\"ם (סהמ\"צ מ\"ע לד) שהיא מצות הכהנים, שישאו הארון בכתף. וגם לדעת הרמב\"ן שם (שורש ג) שהיא מצות הלויים, בנדו\"ד מוכרח שהכוונה כאן הוא לכהנים כיון שהוצרכו ליכנס לקדה\"ק, וכמו שפירש הרמב\"ן שם בהפסוק דמלכים הנ\"ל „ויביאו הכהנים גו'\"."],["36","36","להעיר מרש\"י יומא נב, ב ד\"ה תנו. תוס' הרא\"ש להוריות שם."]]],[1300211174,"ז. ע\"פ כל הנ\"ל וועט מען אויך פארשטיין וואס דער רמב\"ם איז מסיים די הלכה מיט דער אריכות וועגן אורים ותומים בזמן בית שני:\nדער רמב\"ם ברענגט א דוגמא צו דעם וואס ער זאגט אין תחלת ההלכה וועגן ארון — אז אויך אין בית שני איז גע־ווען דער ארון בשלימות (היינו במקומו), חאטש ס'איז געווען א שינוי גדול בגלוי, מ'האט עס ניט געזען אין ביהמ\"ק —\nאון אזוי געפינט מען אויך בנוגע האורים ותומים בבית שני: די אורים ותומים — לדעת הרמב\"ם — זיינען גע־ווען בשלימותם אויך בבית שני<sup data-n=\"37\">37</sup>; חאטש ס'איז געווען א שינוי גדול, „לא היו משיבין כו'\" מ'האט זיי ניט געהערט, עס האט געפעלט זייער גילוי (אלס אורים ותומים) ווי דאס איז געווען בבית ראשון; אבער זיי זיינען געווען בשלימותם און דערפאר (ווי דער רמב\"ם איז מסיים) האבן זיי משלים געווען דעם מנין הבגדים פון כהן גדול.\nח. ע\"פ כל הנ\"ל קומט אויס א חידוש והפלאה ניט נאר בשייכות צו שלימות המעלה והקדושה פון בית שני — אז אויך דעמולט האט מען געהאט דעם קדש הקדשים בשלימותו און דעם ארון במקומו — נאר דערמיט ווערט ארויסגעבראכט א מעלה אויך אין קדושת בית ראשון:\nאע\"פ אז בחיצוניות איז דער בית ראשון ניט געווען קיין בנין נצחי, עס האט געקענט זיין און געווען חורבן\nהבית — אבער בפנימיות איז אויך אין אים אריינגעגעבן געווארן אן ענין פון „נצחיות\" — ס'איז דא אין בית ראשון א מקום גניזה וואס אין עם איז ניט געווען חורבן, און דער ארון איז במקומו „עד היום הזה\".\nדאס וואס „קדושה ראשונה קדשה לשעתה ולעתיד לבא\" — דאס איז מצד קדושת המקום, „מפני השכינה\", אבער דא איז דער רמב\"ם מחדש א טיפערן ענין, אז אויך דער בנין גופא האט אין זיך אן ענין, א חלק וועל־כער איז „לשעתו ולעתיד לבא\" — דער קדש קדשים איז מלכתחילה געבויט גע־וארן לשעתו ולעת\"ל, ער האט אויך א מקום גניזה.\nט. ע\"פ הנ\"ל וועט אויך צוקומען א נייער עומק אין דעם פארבונד פון די דריי בתי־מקדש:\nס'איז ניט אז עס זיינען דריי (באזון־דערע) בתי־מקדש וועלכע האבן א שייכות זל\"ז, נאר בעיקר<sup data-n=\"38\">38</sup> זיינען זיי איין בית<sup data-n=\"39\">39</sup>: דער ביהמ\"ק השני וכן השלישי איז (בחלק עיקרי) ניט קיין נייער בית, נאר — דער (ערשטער) בית ווערט געבויט איבעראנייס.\nשוין אין דעם בנין פון ערשטן בית איז נקבע געווארן אן ענין לשעתו ולעת\"ל (כנ\"ל), נצחי, השני והשלישי.\n[וי\"ל שעד\"ז הוא בתחיית המתים<sup data-n=\"40\">40</sup>: דאס מיינט ניט אז דעמולט וועלן בא־שאפן ווערן אינגאנצן נייע גופים, נאר",[["37","37","כמ\"ש המפרשים (באר שבע סוטה מח, א. ועוד) שלדעת הרמב\"ם (הל' ביהב\"ח כאן. הל' כלי המקדש פ\"י ה\"י) אבני החושן הם האורים ותומים (ולא שם המפורש שהי' חסר בבית שני). וראה לקו\"ש חי\"א ע' 136 הערה 16. וש\"נ."],["38","38","ובפרט לדעת הרמב\"ן (ריש פרשתנו): עיקר החפץ במשכן הוא מקום מנוחת השכינה שהוא הארון."],["39","39","ראה לעיל ע' 149 ואילך. לקמן ע' 261 ואילך."],["40","40","ראה בכ\"ז לקו\"ש ח\"ו ע' 83 ואילך. חי\"ח ע' 248. וש\"נ."]]],[1300211175,"די גופים וועלן אויפגעבויט ווערן פון דעם „עצם לוז\"<sup data-n=\"41\">41</sup> — וואס דאס איז דער עצם הגוף שלפנ\"ז, אין וועלכן ס'איז ניט שייך קיין („חורבן\") הפסד.\nאון דאס איז דער ענין פון „בנה בו מקום לגנוז בו הארון\" — דער מקום הארון איז דער „עצם\" (עיקר, כנ\"ל) פון דעם בית המקדש, אין וועלכן ס'איז ניט שייך קיין חורבן והפסד<sup data-n=\"42\">42</sup>, און פון אים בויט זיך אויף דער מקדש השני והשלישי].\nיו\"ד. די הלכה אין רמב\"ם ברענגט אויך ארויס דברים נפלאים אין כללות ענין החורבן והגלות:\nאין דעם ביהמ\"ק מצ\"ע וואלט ניט געקענט זיין קיין ענין של חורבן — גוים בכח עצמם קענען ניט האבן ח\"ו קיין שליטה אין דעם ביהמ\"ק, דעם בית לה';\nדאס וואס בפועל האט געקענט זיין דער חורבן הבית, איז דערפאר וואס אין דעם ביהמ\"ק גופא, בעת בנינו, איז געווען א נתינת מקום און אן אפשריות אויף דעם חורבן.\nוע\"ד ווי דאס איז בנוגע צו א אידן בכלל, אז א גוי מצ\"ע האט ניט קיין שליטה אויף א אידן, סיידן ווען דער איד (דורך מעשיו ופעולותיו) גיט אויף דעם אן ארט.\n[און נאכמער: ניט בלויז א גוי קען ניט האבן קיין שליטה אויף א אידן, נאר אויך להבדיל וכו' ב\"ד ופמליא של מעלה האבן כביכול קיין שליטה ניט אויף א אידן, און דער „דין\" וואס זיי פסק'נען אויף א אידן מוז זיין מיט דער „הסכמה\" פון דעם אידן<sup data-n=\"43\">43</sup>].\nאון דאס זאגט דער רמב\"ם, אז דאס וואס עס האט געקענט זיין דער חורבן הבית, איז ווייל בעת שלמה האט געבויט דעם מקדש, האט ער ניט בלויז גע־וואוסט אז סופו ליחרב, נאר ער האט אין דעם בנין גופא אריינגעטאן דעם (נתינת) מקום אויף חורבנו — „בנה בו מקום לגנוז בו הארון\".\nיא. אבער פון דעם גופא וואס אין דעם זמן פון בנין ביהמ\"ק מיט דער גאנצער שמחה און שטורעם וואס ס'איז דעמולט געווען, האט שלמה המלך גאר געטראכט וועגן דעם חורבן הבית און האט נאך געטאן א פעולה בקשר לזה, איז מובן, אז (אויך) דער חורבן איז באמת נוגע און ברענגט צום תכלית פון בנין הבית.\nוהביאור בזה:\nדער חורבן הבית איז ניט געווען צוליבן חורבן עצמו ח\"ו וח\"ו — נאר כדי אז עס זאל דורכדעם צוקומען אן עלי' נעלית יותר — ירידה צורך עלי' — ביז צום בנין הבית השלישי וואס וועט זיין א בית נצחי, און דעמולט וועט זיין די שלימות אין בנין ביהמ\"ק, ווארום ער וועט זיין „בנינא דקוב\"ה\"<sup data-n=\"44\">44</sup> („מקדש אדנ־י כוננו ידיך\"<sup data-n=\"45\">45</sup>.\nאון דאס איז ווי דער רמב\"ם זאגט „בעת שבנה שלמה את הבית ו(בדרך ממילא) ידע שסופו ליחרב\" — וויבאלד ס'איז „בנינא דבר נש\"<sup data-n=\"46\">46</sup> — און דער־פאר „בנה בו מקום לגנוז בו כו'\", ער האט מלכתחילה אריינגעגעבן אין דעם בנין די (נתינת) מקום לחורבן, כדי",[["41","41","ב\"ר פכ\"ח, ג. וש\"נ."],["42","42","ראה בארוכה לקו\"ש חט\"ז (ע' 471 ואילך) לענין הארון. וראה לעיל הערה 30."],["43","43","ראה לקו\"ש ח\"ד ע' 1207 ואילך."],["44","44","זח\"ג רכא, א. ועד\"ז שם ח\"א כח, א."],["45","45","בשלח טו, יז."],["46","46","כמ\"ש בזח\"ג שם „ושלמה הוה ידע דבגין דהאי עובדא דבר נש לא יתקיים\"."]]],[1300211176,"מ'זאל דערנאך צוקומען צו דער עלי' (דורך דער ירידה של החורבן) פון בית שלישי.\nאון דער ענין, אז דער „סופו ליחרב\" איז צוליב דער עלי' שלאח\"ז, איז מודגש אין דעם ענין גופא וואס שלמה האט געטאן — „בנה בו מקום לגנוז בו את הארון\", וואס דאס האט אין זיך ביידע קצוות:\nדאס ווייזט אז דער בית איז אזא וואס „סופו ליחרב\", אבער לאידך איז די מטרה פון בונה דעם מקום גניזה — צו באווארענען די נצחיות פון דעם ארון וביהמ\"ק: דורך דעם האט מען בא־וארנט אז אויך אין בית שני זאל ניט פעלן אין „בנין הבית\", און וואס נאכ־מער — דאס האט באוארנט אז דער ארון גופא זאל בלייבן גאנץ און פון אים וועט צוריק אויפגעבויט ווערן דער בית השלישי (כנ\"ל ס\"ט).\nיב. עפ\"ז יש לפרש ג\"כ (בפנימיות הענינים) די דריי לשונות וואס דער רמב\"ם זאגט וועגן דעם מקום שנגנז בו הארון — „במטמוניות עמוקות ועקל־קלות\":\nדערמיט איז דער רמב\"ם מרמז דעם עילוי וואס איז אריינגעגעבן געווארן אין דעם מקדש דורך דעם וואס „בנה בו מקום לגנוז בו הארון\": אע\"פ אז בחיצוניות איז דאס פארבונדן מיט ענין\nהחורבן, „סופו ליחרב\", איז אבער דוקא דורך דער ירידה (דורך דעם תיקון ותשובה אויף דער ירידה —) די עלי': עס ווערט נתגלה די בחי' פון „מטמוניות עמוקות\" — די העכסטע מדריגות אין אלקות וואס מצ\"ע זיינען זיי „מטמוניות עמוקות\" (ל' רבים), „עמוק מי ימצאנו\"<sup data-n=\"47\">47</sup>, וואס דורך אן עבודה רגילה, באופן ישר, קענען זיי ניט נמשך ווערן:\nדוקא דורך עבודת התשובה, וואס קומט ווען דער אדם פירט זיך (ניט ווי האלקים עשה את האדם ישר<sup data-n=\"48\">48</sup>, נאר) בדרך של „עקלקלות\" — ווערן דערפון „עקלקלות\" למעליותא, אז מ'איז ממשיך די „מטמוניות עמוקות\" (וואס ווערן ניט נמשך בדרך אור ישר, נאר בדרך אור חוזר, „עקלקלות\"),\nוואס דאס וועט זיין בגלוי אין דעם ביהמ\"ק השלישי, דער בנין נצחי, שיבנה ויתגלה במהרה בימינו ממש, בגאולה האמיתית והשלימה ע\"י משיח צדקנו.\n(משיחת ש\"פ דברים תשמ\"א)",[["47","47","קהלת ז, כד. ובפרש\"י שם: אין לו רשות להרהר בהן מה למעלה כו' ומה לאחור — וראה חגיגה רפ\"ב, תקו\"ז ת\"ע (קכז, סע\"א) חו\"ב ובשל\"ה (ו, ב. ח, א) קוצו של יו\"ד. וראה לקו\"ת ר\"פ מסעי. ואכ\"מ."],["48","48","קהלת שם, כט."]]],[1300211177,"<h3>תרומה ג</h3>\nא. וועגן דעם ציור פון די גביעים (פון דער מנורה) זאגן חז״ל¹: „למה הן דומין כמין כוסות אלכסנדריים״. איז דער רמב״ם מפרש (בפירוש המשניות שלו²) אז דאס מיינט א כוס וואס „שולים שלו צרים״³ — דער דעק איז שמאל. און אזוי פסק׳נט דער רמב״ם להלכה (בספר היד⁴): „הגביעים דומין לכוסות אלכסנ־דריאה שפיהן רחב ושוליהן קצר״.\nגעפינט מען אין דעם א דבר תמוה: עס איז פאראן דער ציור פון דער מנורה וואס דער רמב״ם האט מצייר געווען בגוף כתב יד קדשו (בפירוש המשניות שלו)⁵, און דארט איז ער מצייר די גביעים אין א פארקערטן אופן — דעם ברייטן חלק הגביע („פיהן״) צום אונטן פון דער מנורה און דעם שמאלן טייל („שוליהן״) אויבן, דאס הייסט — א ציור פון א איבערגעקערטן כוס (של אלכסנדריאה)!\nאון אע״פ אז דער רמב״ם אליין באַ־וארנט⁶, אז מיט דעם ציור וויל ער נאר באווייזן „כללותה היאך היתה״ — „ידיעת מנין הגביעים כו׳ ומקומותם כו׳״ — אבער ניט „שתדע ממנו תבנית הגביע בדקדוק״\n[וואס דערפאר איז ער מצייר די גביעים אין א „תבנית משולש״, אע״פ אז א כוס אלכסנדרית איז ניט ווי א משולש ממש⁷ — ווי ס׳איז פארשטאנדיק בפשטות אז די שוליים פון א כוס מאכט מען ניט שפיציק ממש (ווייל דעמאלט קען מען דעם כוס ניט אוועקשטעלן⁸) — זיי זיינען נאר „צרים״, שמאל (ובפרט) לגבי דער ברייט פון „פיהם״],\nאיז דאס אבער ניט קיין טעם צו מצייר זיין פארקערט (שוליים — למעלה און דעם אויבן — למטה) „מיטן קאפ אראפ״⁹:\n[ובפרט אז דער רמב״ם איז געווען א דייקן בכל ענין ובכל פרט — לייגט זיך כלל ניט צו זאגן, אז דער רמב״ם זאל מצייר זיין די גביעים באופן הפוך (און באַ יעדן גביע) — צוויי און צוואנציג מאלן!].\nב. לכן נראה לומר כפשטות הדבר, אז דער רמב״ם האט מצייר געווען די גביעים באופן זה¹⁰ ווייל לדעתו איז אזוי",[["1","1","מנחות כח, ב. ברייתא דמלאכת המשכן פרק יו״ד."],["2","2","מנחות ספ״ג. אבל רש״י מנחות שם (וכן בפי׳ עה״ת פרשתנו כה, לא) פי׳ באו״א. וראה ס׳ הזכרון לפרש״י פרשתנו שם."],["3","3","כ״ה הלשון בהעתקת קאפח (וכן שאר העתקות ל׳ הרמב״ם, בפיה״מ דלקמן הן מהעתקה זו. ובפיה״מ לפנינו הוא בשינוי לשון אבל בתוכן דומה)."],["4","4","הל׳ בית הבחירה פ״ג ה״ט."],["5","5","צילום ממנו נדפס בפיה״מ הוצאת קאפח. ולתועלת המעיינים — נדפס לקמן ע׳ 172."],["6","6","בפיה״מ שם."],["7","7","כמפורש בפיה״מ שם לפנ״ז (ושם: ואם תרצה אמור . . שנחתך מלמעלה מעט כו׳)."],["8","8","ראה פסחים (סד, א): ולא היו לבזיכין שוליים כו׳."],["9","9","וראה רלב״ג עה״ת פרשתנו: שוליהם לצד יציאתו מקנה המנורה. וכן מוכח בחזקוני ובבכור שור עה״ת פרשתנו, שהגביעים היו מתמלאים מן השמן כשהנר מתמלא יותר מדאי. וראה לקמן סעיף ה והערה 26."],["10","10","וצע״ק בפי׳ ר׳ אברהם בן הרמב״ם (לונדון תשי״ח) פרשתנו שם (בעברית — עם תרגום): בדמיון הכוס רחב מלמעלה וקצר מלמטה, דמשמע קצת כבמפרשים שבהערה הקודמת. ויש לומר שתיבות אלו קאי על צורת כוס זה (אלכסנדרי׳) בכלל, אבל לא נחית לפרט אם במנורה היו כתבנית"]]],[1300211178,"געווען זייער קביעות במנורה (אדער מצד הקבלה פון מלמד צו מלמד מדור לדור¹¹), אדער ווייל אזוי האט ער געפו־נען אין א מדרז״ל שלא הגיע לידינו [ע״ד ווי מען געפינט בכמה מקומות אין רמב״ם (און אנדערע ראשונים) ענינים וואס זייער מקור איז א מדרש (וכיו״ב) שלא הגיע לידינו].\nאון ער בריינגט עס ניט בספר היד¹¹* — פונקט ווי ער בריינגט ניט בספרו די ציורים שבפיה״מ שלו (אע״פ וואס במילא זיינען אויך ניטא בספרו כמה פרטים וועלכע מ׳זעט אין ציור).\nוי״ל כמה טעמים בזה. ומהם: א) מלכתחילה איז דאס (ציורים) ניט געווען אין זיין תכנית פון ספרו משנה תורה. ב) ע״פ הידוע¹² אויף וויפל דער רמב״ם איז ממעט בתכלית בריינגען בספרו זאכן וועלכע זיינען ניט מפורש בש״ס וכיו״ב. ג) כמה מהפרטים האלה, זיינען, לדעתו, ניט לעיכובא כלל. ועוד טעמים.\nויש להאריך בכ״ז וביותר. ואכ״מ.\nג. הנ״ל פארענטפערט, איז מבאר דעם רמב״ם — עס בלייבט אבער די שאלה: הלמאי זיינען די גביעים פון דער מנורה געווען איבערגעקערט, מיטן אויבן אראפ?\nובפרט אז מען געפינט אז די קרשי המשכן האבן געדארפט זיין „עומדים דרך גדילתן״¹³ דוקא — „התחתון למטה והעליון למעלה״¹⁴ און דערפון לערנט מען אפ¹⁵ א כלל אז „כל המצות כולן אין אדם יוצא בהן אלא דרך גדילתן״ — פארוואס־זשע זאלן די גביעים זיין היפך פון „דרך גדילתן״?\nויש לומר, אז דאס וועט זיין מובן לויט דעם וואס מען געפינט בנוגע דער כללות ענין המנורה אן ענין וועלכער איז מעין ודוגמת הנ״ל:\nוועגן דעם אור המנורה זאגן חז״ל¹⁶: „לא לאורה אני צריך . . עדות הוא לכל באי עולם שהשכינה שורה בישראל״ — דער אור המנורה איז ניט געווען כדי צו באלייכטן דעם ארט וואו מ׳האט זי גע־שטעלט (משכן ומקדש), ואדרבא — דארט איז „אינו צריך לאורה״, נאר עס איז געווען אן „עדות . . לכל באי עולם שהשכינה שורה בישראל״.\nאון מהאי טעמא¹⁷ האט מען געמאכט די חלונות פון בית המקדש אין אן אופן היפך פון חלונות סתם — נאר „שקופים אטומים״¹⁸ — „שקופים מבחוץ¹⁹ ואטומים מבפנים״¹⁹ (ברייטער אין דרויסן און שמאלער אינעווייניק), ווי מפרשים²⁰ זיי־נען דאס מבאר:",[["","","כוס העומדת ביושר או הפוכה — דבזה מובן דס״ל כאביו. — ראה לקמן בפנים ס״ח בפי׳ הראב״ם בזה."],["11","11","עדמש״כ בהקדמת פיה״מ (ד״ה וכאשר מת יהושע) דאין שייך ספק מהו פרי עץ הדר כיון שנלקח בכל שנה. 11*) הערה לאחר זמן: שוב נתפרסם כת״י דס׳ היד, ושם בהל׳ ביהב״ח פ״ג סה״י (איתא „וזו היא צורתה״,) ו)יש ציור המנורה (כמו בפיה״מ) — וגם שם הגביעים מצויירים פיהם למטה ושוליהם למעלה (כציור המנורה שבגוף כ״ק הרמב״ם). וכן הקנים עולים באלכסון (ראה לקמן סעיף ח)."],["12","12","ראה יד מלאכי כללי הרמב״ם אות ב׳ וד׳."],["13","13","סוכה מה, ב."],["14","14","רש״י שם ד״ה דרך גדילתן."],["15","15","סוכה שם. וראה הנסמן בגליוני הש״ס (להר״י ענגל) שם."],["16","16","מנחות פו, ב."],["17","17","מנחות שם. וראה גם ויק״ר פל״א, ז. תנחומא (תצוה ו. בהעלותך ב)."],["18","18","מ״א ו, ד."],["19","19","כ״ה הגירסא ברש״י כת״י מנחות שם. שטמ״ק שם. וגם לפי הגירסא שלפנינו (וכ״ה גירסת רש״י שם) „שקופין מבפנים ואטומים מבחוץ״ — הכוונה בזה צר מבפנים ורחב מבחוץ (ראה רש״י שם. וראה חדא״ג מהרש״א שם)."],["20","20","רש״י כת״י מנחות שם. וכ״ה במדרשים שצויינו בהערה 17."]]],[1300211179,"א פענסטער ווערט געבויט אזוי, אז די פענסטער־עפענונג איז אינעווייניק ברייטער ווי אין דרויסן, כדי די ליכ־טיקייט פון דרויסן זאל זיך מתפשט זיין אויך אין די „צדדין״ פון דעם חדר; אבער די חלונות פון בית המקדש זיי־נען געווען פארקערט — „קצר מבפנים ומרחיב והולך לצד חוץ כדי שתהא אורה יוצא מהיכל שתאיר לעולם״²¹, ווייל דער תפקיד פון אור המנורה איז — „עדות הוא לכל באי עולם כו׳״.\nד. על דרך זה קען מען מבאר זיין בנוגע די גביעים:\nדער בחיי²² איז מבאר דעם רמז אין די גביעים פון דער מנורה: א גביע איז א „כלי שיש לו בית קיבול והוא משקה ומרוה״, און דאס איז א רמז אויף די „גלגלים שהם מקבלים כחות העליונים ומשפיעים כח בעולם השפל״.\nוואס די הדגשה אין דעם איז — די השפעה²³ מעליון להשפל, „משקה ומרוה״.\nדער (עיקר) תפקיד פון א כוס באַשטייט ניט אין זיין א כלי קבול²⁴\n— דאס איז דער תפקיד פון א „חבית״ וכיו״ב, אין וועלכע מ׳האלט מים, יין וכו׳.\nא כוס אבער איז א כלי דורך וועל־כער די מים וכו׳ פון דער „חבית״ (אדער „מעין״ וכיו״ב) קומט אן און איז „משקה ומרוה״ דעם אדם השותה²⁵.\nקומט אויס, אז דער ביאור הנ״ל פון בחיי איז מתאים מיטן מאמר רז״ל הנ״ל (וועגן כללות ענין המנורה) „לא לאורה אני צריך . . (נאר) עדות הוא לכל באי עולם כו׳״ — אז דער תפקיד פון אור המנורה איז (ניט אינעם „אני צריך״ — „קיבול״ — נאר) כדי צו באלייכטן די וועלט (שמבחוץ), ובלשון הבחיי: צו משפיע זיין „בעולם השפל״.\nה. עפ״ז יובן פארוואס די גביעים במנורה זיינען אין אן אופן פון פיהן למטה ושוליהן למעלה:\nווען די גביעים זיינען (צייטוויילי׳ג) צוליב דעם „קיבול״, בשעת „אומר קידוש על הכוס״ איז זייער מצב פיהן למעלה ושוליהן למטה (וואס דעמאלט האלטן זיי אויף אין זיך משקה²⁶):\nוויבאלד אבער אז די גביעים שבמנו־רה איז לרמז אויפן ענין פון „משקה",[["21","21","ל׳ רש״י כת״י מנחות שם."],["22","22","פרשתנו כה, לא (הועתק בס׳ תורת העולה ח״א פ״כ). ועד״ז בפי׳ הרקאנטי עה״ת פרשתנו שם, לג."],["23","23","וכמודגש בל׳ הרקאנטי שם „הם מקבלים . . להשפיע כו׳״ (ולא „מקבלים . . ומשפיעים״ כבחיי שם) — משא״כ לפי׳ העקידה (פרשתנו שער מט) שענינם (רק) קבלה. וראה הערה הבאה."],["24","24","וצע״ק לתווך עם המבואר במקומות שבהערה הבאה בהחילוק בין גביע לכוס, דכוס היא כנגד ספי׳ המלכות שענינה מקבל. אבל להעיר שגם במל׳ יש ב׳ ענינים (כידוע): א) מקבלת מהספירות שלמעלה ממנה, ב) משפיעה בעולמות שלמטה ממנה. וראה לקו״ש חט״ז ע׳ 447 (וש״נ) בנוגע לב׳ הענינים שב„דלת״ ומהו העיקר."],["25","25","ראה מקץ (מד, ב־ה) „גביע הכסף . . אשר ישתה אדוני בו״. וראה ערכי הכינויים (לבעל סה״ד) מע׳ גביע. — בכ״מ מבואר (ראה ס׳ הליקוטים (ממאמרי כ״ק דהצ״צ) מע׳ גביע. וש״נ) שגביעים הם גדולים מכוס ובהם מביאים היין, ומהגביע מוזגין לתוך הכוס (וא״כ הוא דלא כפשוטו של מקרא הנ״ל). אבל גם עפ״ז הרי ענינו של הגביע הוא שממנו מוזגין („משקה ומרוה״) לתוך הכוס (ולא כחבית וכיו״ב שבה אוצרין יין). וראה ס׳ הליקוטים שם (מאוה״ת מקץ שמא, ב. וראה ד״ה גביע הכסף לאדהאה״מ): שהגביע הוא ביסוד ז״א אשר הוא מקור המשפיע לבחי׳ הכוס שהוא המל׳, כמו שמהגביע שופכים להכוס. ושם (מאוה״ת במדבר ע׳ א׳תפה) מפורש כן בנוגע לגביעי המנורה."],["26","26","כמ״ש בחזקוני ובבכור שור שבהערה 9. וראה הערה 24."]]],[1300211180,"ומרוה״ — איז, אדרבה: דער מצב זייערער להיפך פיו למטה ושוליו למעלה (מען קערט איבער דעם כוס כדי די משקה זאל זיך אויסגיסן פון אים).\nועד״ז בענינינו: וויבאלד דער אור המנורה דארף באלייכטן די „באי עולם״ וועלכע זיינען למטה (ברוחניות) פון דעם מקדש [אדער בלשון הבחיי הנ״ל: ומשפיעים בעולם השפל], דעריבער, איז מצב הגביעים שבמנורה פיהם למטה ושוליהם למעלה (ע״ד ווי די חלונות המקדש „שקופים אטומים״, היפך ווי חלונות הבית).\nו. ע״פ הנ״ל קען מען אויך מסביר זיין בעבודת האדם דעם רמז ולימוד וואס די גביעים זיינען געווען דוקא „פיהן רחב ושוליהן קצר״:\nוויבאלד אז די גביעים זיינען מרמז אויפן ענין פון „משקה ומרוה״, איז מובן, אז דאָ פאדערט זיך א „פה רחב״.\nווען עס קומט צו משפיע זיין אויף א צווייטן אידן, אדער (בכללות יותר —) צו פארנעמען זיך מיט דער עבודה פון לעשות לו ית׳ דירה בתחתונים („עדות הוא לכל באי עולם״) — דארף דאס גע־טאן ווערן מיט דער גרעסטער רחבות, ביז למעלה ממדידה והגבלה. — דארף ער (מקבל זיין) זיך אננעמען מיט די גרעסטע כחות, פיו (דורך וועלכן ער איז מקבל לתוכו איז) רחב.\nאויב ווען עס רעדט זיך וועגן זיך אליין און ער האלט גאר בתחלת העבודה, אדער אפילו שפעטער אבער זיין עבודה איז (מאיזה סיבה שתהי׳) אן עבודה מוגבלת²⁷ — איז זיין מצב: פיו למעלה,\nאבער ווען ס׳קומט צו דער עבודה פון טאן מיט א צווייטן אידן, ובפרט — צו דער עבודה פון מאכן די וועלט פאר א דירה לו ית׳ — מוז מען וויסן, אז דא מוז זיין למעלה מהגבלות, ווערט דער רחב — כלפי (המקבל ממנו — ה)מטה.\n[ע״ד ווי געהעדט אמאל בארוכה²⁸ וועגן דעם חילוק צווישן די תרומת האדנים (ותרומת השקלים) און תרומת המשכן:\nתרומת האדנים (והשקלים) איז גע־ווען באגרענעצט צו א דבר מסויים (כסף ומחצית השקל), משא״כ תרומת המשכן האט אין זיך כולל געווען אלע סוגי הבריאה — דומם צומח און חי (ובצירוף „איש . . ידבנו לבו״²⁹ — מדבר) —\nווייל תרומת האדנים (והשקלים) זיי־נען מרמז אויף (דער הנחת האדנים ו)התחלת העבודה פון א אידן, וואס עבודת תמידים (איז) כסדרם, עבודה מסודרת — אנהייבנדיג פון מודה אני און גיין מדרגא א׳ לשני׳ וכו׳.\nמשא״כ תרומת המשכן איז מרמז אויף דער כללות העבודה פון לעשות לו מקדש ושכנתי בתוכם — דירה בתחתונים, וואס אין דעם זיינען ניטא קיינע הגבלות³⁰, זי נעמט ארום כל עניני העולם].\nז. און דאס איז דער רמז אין דעם וואס אע״פ אז „כל המצות״ דארף מען טאן „דרך גדילתן״ דוקא — ווי עס ווערט געבראכט לגבי (און אפגעלערנט פון) לולב ומיני¹³ — אעפ״כ זיינען די גביעים שבהמנורה היפך „דרך גדילתן״:",[["28","28","לקו״ש חי״א ע׳ 113 ואילך (ובהערה 51 שם)."],["29","29","פרשתנו כה, ב."],["30","30","וראה אוה״ת פרשתנו (ע׳ א׳שנא) דתרומת המשכן (דפרשתנו) הו״ע בכל מאדך."],["27","27","בערך ה„רחב״ ובל״ג שבהעבודה עם הזולת, כי סו״ס גם בהעבודה עם עצמו צ״ל בכל מאדך. וראה הערה 30."]]],[1300211181,"יעדער מצוה³¹ ובפרט לולב ומיני זיינען בדוגמת גאנץ סדר ההשתלשלות — דארף עס זיין בכללות ב„סדר״ וב„השתלשלות״, „דרך גדילתן״:\nאון דערפאר איז דער סדר הקיום פון מצוה³² אין אן אופן פון „דרך גדילתן״.\nאויך די גביעים עצמם זיינען „שוליהם קצר ופיהם רחב״ — ווען זיי ווערן אבער א טייל פון דער מנורה (מקשה) און זייער ענין במנורה איז משקה ומרוה לשפל, מאיר זיין בחוץ — איז עס פאר־בונדן מיט משנה זיין טבעו ורגילותו — ער דארף ארויסגיין פון „זיך״; ובמילא זיינען (די חלונות ביתו אין אן אופן פון „שקופים אטומים״, און) די גביעים פיהם למטה ושוליהם למעלה — היפך „דרך גדילתן״,\nאון זיין עבודה והשפעה למטה איז פון א פה „רחב״ — למעלה ממדידה והגבלה.\n* * *\nח. עס איז פאראן נאך א פרט אין דעם ציור הנ״ל פון דער מנורה שבגוף כתב יד הרמב״ם, וואס איז אנדערש פון די ציורים הרגילים של המנורה — אז די ששה קני המנורה ציען זיך ארויף (פון דעם קנה האמצעי) אין א גלייכן אלכסון, ניט ווי אין די ציורי המנורה הרגילים, אז זיי ציען זיך ארויף ווי חצאי קשת.\nאון אע״פ אז בנוגע דעם פרט, וואלט אפשר בדוחק הכי גדול געווען אן ארט צו זאגן, אז דער רמב״ם האט אזוי מצייר\nגעווען „להקל על הציור״ — שטייט אבער בפירוש אין פירוש ר׳ אברהם בן הרמב״ם³³, אז די „ששה קנים . . נמ־שכים מגופה של מנורה לצד ראשה ביושר כמו שצייר אותה אבא מרי ז״ל, לא בעיגול כמו שצייר אותה זולתו״.\nאון אזוי שטייט אויך אין פירוש רש״י על התורה³⁴ אז די ששה קנים „באלכסון נמשכים ועולין״.\nקומט אויס, אז די ציורים הרגילים של המנורה זיינען ניט ווי דעת רש״י און ניט ווי דער רמב״ם האט זיי מצייר געווען!\nט. דער בעל משנת חסידים בספרו „מעשה חושב״³⁵ (על מלאכת המשכן) שרייבט בפשטות אז די ששה קנים זיינען געווען „נמשכין בעיגול״.\nאון ער איז מבאר, אז אע״פ אז פון פי׳ רש״י³⁴ איז מוכח אז „לא היו בעיגול״ — „אבל הרמב״ם בחבורו³⁶ לא הזכיר תיבת אלכסון אלא כתב³⁷ ונמשכים ועולים״, און ער ברענגט וואס דער בעל „חכמת המשכן״³⁸ שרייבט, אז פון דעם איז „נראה . . שהיו עולים הקנים כמעט בעיגול״; און דער „מעשה חושב״ איז מסיים: „והכי מסתברא דבהכי הם דומים לגלגלי הרקיע³⁹ כו׳ שכנגדם הם השבעה⁴⁰ נרות״.\nאבער לפענ״ד: וויבאלד דער „מעשה חושב״ שרייבט בפירוש, אז זיין יסוד צו",[["33","33","פרשתנו כה, לב."],["34","34","פרשתנו שם."],["35","35","פ״ז."],["36","36","הל׳ בית הבחירה פ״ג ה״י."],["37","37","„וכן הוא בברייתא דמלאכת המשכן (פ״י) וכן בש״ס (מנחות כח, ב)״ — מעשה חושב שם."],["38","38","להר״י ריקיטי (מנטובה, תל״ו)."],["39","39","ולהעיר שהגלגלים שייכים לבחי׳ עיגולים (ע״ח ש׳ עיגולים ויושר ענף ג. ש׳ ציור עולמות אבי״ע פ״ב. ועוד)."],["40","40","וצע״ג האם מפרש שגם הנר האמצעי יהי׳ „כמעט בעיגול״!"],["31","31","להעיר ש„מצוה״ אותיות „הוי׳״ (בחילוף י״ה באתב״ש) — לקו״ת ויקרא ב, א. ועוד. — וכל מצוה כלולה מכל המצות (המשך תרס״ו ע׳ סח. ע׳ תקצב. ובכ״מ)."],["32","32","וכן קרשי המשכן, שהם כותל המפסיק בין המשכן וה„חוץ״ (עולם)."]]],[1300211182,"לערנען אז „נמשכין בעיגול״ איז פון סתימת לשון הרמב״ם בחיבורו („לא הזכיר תיבת אלכסון״), וואס דערפון איז „נראה . . שהיו עולים . . כמעט בעיגול״ [און „הכי מסתברא כו׳״] —\nאיז אבער נאכדעם ווי ס׳איז נתגלה געווארן גוף כתי״ק הרמב״ם בציור המנורה⁴⁰* ועדותו של בן הרמב״ם בזה [ובהדגשה אז דאס וואס אביו האט מצייר געווען „ביושר״ איז מיט אויס־דריקלעכער כוונה — דוקא אזוי און „לא בעיגול כו׳״] — איז בטל היסוד ובטל הבנין⁴¹.\nובמחכ״ת ולפענ״ד נראה ברור, אז אויב דער „מעשה חושב״ ובעל חכמת המשכן וואלטן געזען דעם ציור הרמב״ם און דעם פירוש פון ר׳ אברהם בן הרמב״ם, וואלטן אויך זיי געשריבן אז ס׳איז ניטא קיין פלוגתא בזה ולכולי עלמא זיינען די קנים געווען „ביושר״\n[ע״ד ווי דער אלטער רבי שרייבט בשו״ע שלו⁴², אז „הרבה מספרים הראשונים ז״ל לא יצאו לאור הדפוס עדיין בימי האחרונים ז״ל . . ולזאת ודאי אין לסמוך כו׳״].\nיו״ד. ואם כנים הדברים, איז מהנכון להחזיר עטרה ליושנה — אז די אלע וועלכע מאכן ציורים פון דער מנורה (בכדי צו לערנען ווי ס׳איז געווען דער אויסזען פון דער מנורה שבמשכן ומקדש), זאלן מצייר זיין די קני המנורה באלכסון, כדעת רש״י (פשוטו של מקרא) והרמב״ם (וע״פ הנ״ל — איז י״ל אז במסקנא אין חולק בדבר⁴³).\nועד״ז די מוסדות חינוך וכיו״ב וועלכע זיינען מצייר אויף זייערע „גליונות״ „בלאנקען״ וכיו״ב דעם ציור המנורה און זיי צייכענען די קני המנורה ווי חצאי קשת —\nאיז וויבאלד די מטרה פון דעם ציור איז צו דינען אלס דערמאנונג אויף דער מנורה שבמשכן ובמקדש — איז כדאי וביותר אז זיי זאלן משנה זיין דעם ציור און מצייר זיין די קנים באלכסון⁴⁴.\nיא. דערביי קומט דא צו נאך אן ענין:",[["","","40*) הערה לאחר זמן: וראה לעיל הערה 11* שכ״ה גם בכת״י של ספר היד, היינו שנתגלה שגם „בחבורו״ לא סתם הרמב״ם."],["41","41","ובכלל לא זכיתי לפענ״ד להבין כלל הראי׳ דמסתימת כהנ״ל דנראה שהי׳ „כמעט בעיגול״ — שהרי תיבת „קנה״ מובאה בכו״כ מקומות בתושב״כ, ובכ״מ מוכרח שהוא קו ישר. ולא מצאתי ע״ע אף פ״א שמוכרח שזהו באופן אחר."],["42","42","ריש הל׳ מכירת חמץ (נדפסו לאחרי הל׳ פסח — בהוצאות קה״ת תקס, ב). וראה גם בשו״ע חיו״ד שלו סקפ״ט ס״ג סקמ״ג."],["43","43","בזית רענן (לבעל מג״א) ר״פ בהעלותך מפרש מ״ש בספרי זוטא (והובא בילק״ש) ר״פ בהעלותך „שהן חוזרין חלילה כמין עטרה״ — „שהקנים בעצמן היו עגולה כמין עטרה״. אבל מסיים שפי׳ זה „דוחק״ (ושם לפנ״ז: הלשון משמע דס״ל שהקנה האמצעי הי׳ באמצע וששה קנים מקיפין אותו סביב כמין עטרה. וא״כ ה״ז פי׳ שלישי. וראה בזה בתו״ש מילואים לכרך כב ע׳ לב׳)."],["44","44","ועפ״ז מקום לומר שגם החנוכיות (לימי חנוכה) כדאי לעשות קניהן באלכסון. — ובלאה״כ צ״ל שאין בזה חשש איסור ד„מנורה תבנית מנורה״ (ע״ז מג, סע״א. רמב״ם הל׳ ביהב״ח פ״ז ה״י. שו״ע יו״ד סר״ס קמא), כי משנים מספר הקנים (ראה ע״ז ורמב״ם ושו״ע שם), ולמה לשנות בגוף צורת המנורה שקני׳ היו ביושר ולא כחצי עיגול. *) ושם, שזוהי גם כוונת הראב״ע (תצוה כז, כא. וכן בפי׳ הקצר פרשתנו כה, לז) אשר ששה הנרות היו כחצאי עיגול, והיינו שהקנים הקיפו קנה האמצעי כמין עטרה. אבל תמוה, כי בספרי זוטא סתם „חוזרין חלילה כמין עטרה״, שמשמעו „מקיפים אותו סביב (מכל הצדדים)״, ולא „כחצי עיגול״, ואולי הכוונה שהקיפו רק מלפנים — כדוגמת חצי גורן עגולה בסנהדרין. וכמדומה שישנם עטרות המקיפות הראש רק מלפנים."]]],[1300211183,"דער ציור הרגיל פון דער מנורה (אז די ששת הקנים זיינען ווי חצאי קשת) איז ע״פ השערה א נאכמאכונג פון דעם ציור המנורה וואס ניט־אידן האבן מצייר געווען ברומי, און אויף דער „נצחון־ארקע״ (דעם „שער הנצחון״) פון טיטוס ימ״ש⁴⁵!\nווען טיטוס הרשע האט חרב גע־מאכט דעם ביהמ״ק, האט ער געהייסן אוועקצונעמען כלי המקדש און זיי ברענגען קיין רוים; און „לכבודו״ פון דעם רשע האט מען אין רוים געבויט א „שער נצחון״ וואס טראגט זיין נאמען: שער טיטוס. אויף דעם שער האט מען מצייר געווען ווי מ׳טראגט די געפאנ־גענע כלי המקדש ובתוכם די מנורה — און אין דעם ציור פון דער מנורה אויפן שער טיטוס זיינען די ששת הקנים ווי חצאי קשת.\nוואס נוסף אויף דעם אז דער ציור המנורה אויפן שער טיטוס איז כלל ניט מדויק⁴⁶ — איז דאך דאס געטאן גע־ווארן, כמובן, כדי צו אַרויסברענגען די שליטה און הערשאפט פון רוים איבער אידן ר״ל, ביז אז מ׳האט דארט אויסגעקריצט בכ״מ די ווערטער „יודעא קאפטא״ („יהודה (אידן) איז גע־פאנגען״). און עס זיינען געווען זמנים, ווען מען פלעגט מכריח זיין אידן צו קומען צו דעם שער, זיי זאלן זען וואס דארט איז געשריבן און געצייכנט, בכדי צו דערנידעריקן וכו׳ וכו׳.\nקומט אויס, אז דאס וואס מצייר זיין די קני המנורה ווי חצאי קשת (ווי זיי זיינען מצוייר אויף שער טיטוס) דארף אַרויס־רופן א געוואלד געשריי — נוסף וג״ז עיקר וואס דאס איז היפך רש״י והרמב״ם וכו׳ — אויך ווייל דאס גיט א געוויסן הסכם וכו׳ ח״ו ור״ל צו דעם ציור אויפן שער טיטוס, וואס איז גע־מאכט געווארן כדי צו מצער זיין אידן און זיי נידעריק מאכן!",[["45","45","כהערת הר״י קאפח בפיה״מ דהרמב״ם שהו״ל. וכן בתו״ש שם."],["46","46","כמו שהעירו כו״כ — שאין בה רגלים וכו׳, אף שבמנחות (כח, ב) מפורש שהיו בה רגלים. — י״א אשר המנורות שנשבו ע״י טיטוס היו מהעשר מנורות שעשה שלמה (ראה יוסיפון פצ״ה — הוצאת הומינר). אבל [נוסף לזה שמסתבר לומר שהמנורות דשלמה לא היו בבית שני•), הרי גם אם נאמר שצורת המנורה שעל שער טיטוס היא ע״פ צורת מנורות דשלמה] בפשטות, נ״ל שמנורות שלמה נעשו כצורת מנורת משה••), כי [נוסף לזה שכן מפורש בפי׳ רש״י עה״ת פרשתנו (כה, ט), הנה גם ע״ד ההלכה מסתבר לומר כן, כין: א) למה ישנה ויחדש צורה אחרת?! ב) מפורש (ברייתא דמלאכת המשכן פ״י. וראה ירושלמי שקלים פ״ו ה״ג. תוספתא מנחות פי״א, ו) שגם מנורות שלמה היו כשרים לעבודה (וכן מוכח במנחות צח, ב: מצינו מנורה בצפון); ולפרש״י (ד״ה על כולן מנחות צט, א)••• — לדיעה אחת (מנחות שם. וכן ברייתא דמלאכת המשכן, ירושלמי שקלים ותוספתא מנחות שם) היתה הדלקת המנורה (לפעמים) רק בשל שלמה. וכן סתם במדרש הגדול פרשתנו כה, כג••. ובכל אופן: גם את״ל דמנורות שלמה לא היו כצורת מנורת משה (וע״פ זה ציירו המנורה שעל שער טיטוס) — למה לצייר עתה המנורה בצורת מנורות שלמה, ולא כמנורת משה, דלכו״ע הוא העיקר! וראה גם לקו״ש חכ״ו ע׳ 201. •) ראה ר״ה כד, ב (וש״נ) בזמן החשמונאים. אבל ראה תוס׳ רי״ד ליומא (נא, ב) בנוגע לשולחנות שעשה שלמה. אלא שגם הוא מסיים שמסתבר שלא היו בבית שני. ע״ש. ••) וכן מוכח במדרש הגדול פרשתנו (כה, כג) שהוצרך לשלול שאין בעשיית שולחנות (ומנורות) דשלמה משום „לא תוסיף עליו״ (ואתחנן יג, א), כי „כך היתה בידם מסורת מפי משה . . יהו בו עשר שולחנות עשר מנורות . . הכל בכתב מאת ה׳״. ועד״ז הוא בבחיי פרשתנו (כה, י). •••) בנוגע לשולחנות דשלמה, שמזה מובן גם בנוגע למנורות שלמה."]]],[1300211184,"תמורת זה וואס א ציור פון דער מנורה דארף דערמאנען און מעורר זיין א אידן אז זיין תפקיד איז צו זיין „לאור גוים״⁴⁷ — „עדות הוא לכל באי עולם שהשכינה שורה בישראל״⁴⁸ — ווערט די צורת המנורה געמאכט באופן כזה וואס דערמאנט דעם היפך ממש — ווי רוים האט מנצח געווען די אידן, ר״ל!\nיב. ויהי רצון, אז בקרוב ממש זאל קומען די גאולה האמתית והשלימה און מ׳וועט האבן די מנורה כפשוטה ובשלי־מותה⁴⁹ אין דעם בית המקדש השלישי, און אלע וועלן זען ווי די מנורה זעט אויס.\nאון משה ואהרן עמהם⁵⁰, און מען וועט זען בעיני בשר, ותחזינה עינינו — דעם קיום הציווי „דבר אל אהרן גו׳ בהעלותך את הנרות״, צינדן די מנורה, כפשוטה ממש ובמהרה בימינו ממש.\n(משיחות ש״פ מטו״מ, ש״פ דברים ואדר״ח אלול תשמ״ב)",[["47","47","ישעי׳ מב, ו. שם מט, ו."],["48","48","להעיר מיל״ש מלכים (רמז קפה): מנורה . . כנגד שבעים אומות שכל זמן שהנרות דולקות היו מתכבשים."],["49","49","דכל מעשי משה נצחיים (ראה סוטה ט, א. צפע״נ עה״ת ריש פרשתנו. ועוד)."],["50","50","תוד״ה אחד פסחים קיד, ב. וראה יומא ה, ב."]]],[1300211185,""],[1300211186,"<h3>תצוה</h3>\nא. וועגן פ׳ תצוה שטייט אין בעל הטורים¹: אז דאס איז די איינציקע סדרה „משעה שנולד משה” אין וועלכער עס ווערט ניט דערמאנט דער נאמען פון משה רבינו („עד משנה תורה”²). און דער טעם אויף דעם איז, ווייל משה האט געזאגט „מחני נא מספרך אשר כתבת”³ און „קללת חכם אפילו על תנאי באה”⁴ — איז דאס נתקיים געווארן אין דער סדרה.\nיעדער ענין און פרט אין תורה איז בדיוק. דארף מען זאגן, אז דאס וואס דוקא פ׳ תצוה איז אויסגעקליבן גע־ווארן, אז אין איר זאל אויסגעפירט ווערן דער „מחני נא מספרך” (וואס שטייט אין פ׳ כי תשא³)\n[ובפרט, אז לכאורה וואלט מער מתאים געווען צו מרמז זיין אט דעם ענין — אז אמירת משה איז מקוים גע־ווארן „אפילו על תנאי” — אין איינער פון די סדרות וואס קומען נאך⁵ (און ווען מ׳ווייס שוין וועגן) אמירת „מחני נא”⁶]\nאיז דאס דערפאר, וואס דער ענין פון „מחני נא מספרך” איז מתאים צום תוכן פון דער סדרה⁷.\nדארף מען פארשטיין: וואס פאר א שייכות האט דער ענין פון „מחני” צום תוכן פון פ׳ תצוה, וואו עס רעדט זיך וועגן דעם ציווי אויף העלאת נרות המנורה, עשיית בגדי כהונה, חינוך אהרן ובניו, און עשיית מזבח הקטורת?\nב. אויך דארף מען פארשטיין: די כוונה אין דעם וואס „לא הזכיר משה בזה הסדר”⁸ איז (ניט אז דא רעדט זיך",[["1","1","ריש פרשתנו. וכ״ה בזוהר חדש שה״ש בתחלתו (ס, ג). רבותינו בעה״ת ובחיי תשא לב, לב. פי׳ הרא״ש עה״ת ריש פרשתנו. וראה זח״ג רמו, א."],["2","2","פי׳ הרא״ש (ועד״ז הוסיפו בחצע״ג בבעה״ט). וראה לקו״ש ח״ב ע׳ 675."],["3","3","תשא לב, לב."],["4","4","מכות יא, א."],["5","5","וכמו שהקשה בז״ח שם „והא לבתר ואתה תצוה אמר משה האי מלה” (ומתרץ „אין מוקדם ומאוחר בתורה”. וראה הערה הבאה)."],["6","6","לכאורה אפ״ל להיפך, שצ״ל דוקא בא׳ הפרשיות שכבר נכתבו, כדיוק הלשון „מחני נא מספרך אשר כתבת” (ראה גם פי׳ הרא״ש שם: מן הספר אשר כתבתי כלומר מס׳ ואתה תצוה שכתבתי לפני כי תשא) — אבל (נוסף לזה שלכמה דעות (רש״י תשא לא, יח. לג, יא. תנחומא תרומה ח. ז״ח שם) פ׳ תצוה עכ״פ נאמרה לאחרי כי תשא — הרי) בפרש״י תשא (לב, לב) מפורש „מספרך — מכל התורה כולה”, ועכצ״ל שאפ״ל „מחני נא מספרך אשר כתבת” אף שלא נכתב בפועל „ספרך אשר כתבת” [ראה רא״ם שם (ומ״ש הרא״ם (בפי׳ הב׳) שקאי רק על מה שנכתב עד מ״ת — צע״ג, שהרי מפורש ברש״י „מכל התורה כולה”). וראה לקו״ש ח״ב שם]. או כמ״ש בגו״א כאן שכוונת רש״י לתורה „שהיתה כתובה מאז לפניו באש שחורה כו׳” (רש״י ברכה לג, ב. וראה רש״י פנחס כז, ז). ועפ״ז מתרץ דיוק הלשון הכתוב „מספרך אשר כתבת”. ואולי י״ל, דזה שקללת חכם אפילו על תנאי באה, הוא רק בנוגע לדבר שהי׳ במציאות בעת אמירת הקללה (והקללה חלה עליו), משא״כ בדבר שמציאותו נתהוה לאחרי שלא נתקיים התנאי (ובמילא — בטלה הקללה), אין שייך שהקללה (שבטלה) תחול עליו."],["7","7","במאור עינים ריש פרשתנו (ועוד) שזהו לפי שז׳ אדר — יום הסתלקות משה — חל (ברוב השנים) בפ׳ תצוה. ובז״ח שם „דהו״ל למיכתב שמי׳ דמשה בכל מלה ומלה ובכל פיקודא ופיקודא דתמן” — אבל מובן שצ״ל שייכות גם לתוכן הסדרה. וראה טור הארוך, פענח רזא, וש״ך עה״ת ריש פרשתנו. וראה גם לקו״ש חכ״ו ע׳ 204 ואילך. סה״ש תשמ״ט ח״א (ע׳ 257 ואילך. ע׳ 271 ואילך). ועוד."],["8","8","ל׳ בעה״ט כאן."]]],[1300211187,"ניט וועגן משה׳ן, נאר) אז משה ווערט ניט דערמאנט בשמו, אבער אין דער סדרה רעדט זיך וועגן משה׳ן, און אין א ריבוי פסוקים⁹;\nנאך מער: די התחלת הסדרה — און שם הסדרה (וואס איז מרמז, כידוע, אויפן תוכן פון דער גאנצער סדרה) — „ואתה תצוה”¹⁰, באציט זיך דוקא צו משה׳ן; און זאת ועוד — „ואתה תצוה” מיינט (כפירוש הכלי יקר¹¹) „ממהות עצמותך”, וואס מהות ועצמות פון א מענטשן איז טיפער און העכער פון דער דרגא אין מענטשן וואס איז פארבונדן מיטן שם:\nענינו פון א שם איז בכדי אז א צווייטער זאל אים קענען רופן: אבער דער עצמות ומהות פון א מענטשן, איז העכער און טיפער פון האבן א שייכות צו א זולת, ובמילא העכער פון ענין ה„שם”¹².\nקומט לפ״ז אויס, אז אדרבא, דער אופן ווי עס איז מקויים געווארן דער „מחני” — אז משה ווערט דא דער־מאנט (ניט בשמו, נאר) דורך די ווער־טער „ואתה תצוה” — ווייזט אויף נאך א גרעסערער מעלה ווי שם משה.\nג. וועט מען דאס פארשטיין בהקדים הביאור אין דעם גודל הענין פון בקשת משה „מחני נא מספרך אשר כתבת”, ופרש״י¹³ „מכל התורה כולה”:\nענינו פון משה איז — תורה, וכמחז״ל¹⁴ אז (תורה „נקראת על שמו” ווייל) משה „נתן נפשו על תורה”. דער־פון איז פארשטאנדיק, אז דער ענין פון „מחני נא מספרך — מכל התורה כולה”, רירט אן די עצם מציאות פון משה׳ן, ווי עס איז איינס מיט תורה¹⁵;\nאון צוליב וואס האט זיך משה אזוי איינגעשטעלט — אויף פועל׳ן א כפרה אויפן חטא העגל, וואס חטא העגל איז א חטא הכי חמור, ביז אז אלע שפעטער־דיקע חטאים און זייערע עונשים זיינען פארבונדן מיט חטא העגל, וכמ״ש¹⁶ „וביום פקדי ופקדתי עליהם חטאתם”.\nאיז תמוה: ווי קומט עס, אז משה זאל איינשטעלן זיין עצם מציאות, וואס איז פארבונדן מיט תורה, פאר די טייל אידן וואס האבן חוטא געווען בעגל, כולל די עושי העגל וואס זיינען געווען היפך פון לא יהי׳ לך גו׳ לא תעשה גו׳, אינגאנצן אפגעריסן¹⁷ ר״ל פון תורה?\nאויך דארף מען פארשטיין: וואס איז דער תוכן פון בקשת משה „ואם אין מחני נא מספרך — מכל התורה כולה”: וואס איז דער קשר צווישן די צוויי ענינים, אז אויב דער אויבערשטער וועט",[["9","9","וראה לשון הז״ח שנעתק בהערה 7."],["10","10","כן נקראת פרשה זו בזח״ג וז״ח שם ובכ״מ (ראה הנסמן בלקו״ש חט״ז ע׳ 342 הערה 9)."],["11","11","ריש פרשתנו. וראה ג״כ ד״ה זאת תורת הבית תרפ״ט (בסה״מ קונטרסים ח״א) פי״י־יא. וראה לקמן סעיף ו."],["12","12","כי גם זה ש„יש שייכות ממש להשם אל עצם הדבר”, ה״ז ש„השם מקשר הנשמה בגוף”, אבל „הנשמה עצמה קודם בואה בגוף אינה נקראת בשם כלל” (לקו״ת בהר מא, ג). ועצ״ע."],["13","13","תשא שם, משמו״ר פמ״ז, ט."],["14","14","מכילתא לבשלח טו, א. שמו״ר פ״ל, ד. וש״נ."],["15","15","ויתירה מזו — גם במציאות התורה עצמה, שקשורה עם משה (ע״ד הנ״ל שנק׳ על שמו) — עיין רמב״ם הל׳ יסוה״ת פ״ח־ט. לקו״ש חי״ט ע׳ 179 ואילך."],["16","16","תשא לב, לד ובפרש״י שם. ובזהר (ח״א נב, ב ואילך. קכו, ב. ח״ב קצג, סע״ב) שע״י חטא העגל חזרה זוהמתן. וראה לעיל ע׳ 151 הערה 52."],["17","17","ראה שבת פז, א. הובא בפרש״י תשא לב, ט (אבל ראה תוד״ה ומה שבת שם)."]]],[1300211188,"די אידן ניט מכפר זיין אויפן חטא העגל, איז „מחני” פון תורה¹⁸?\nרש״י¹⁹ איז מבאר²⁰, אז דערמיט האט משה געוואלט באוארענען „שלא יאמרו עלי שלא הייתי כדאי לבקש עליהם רחמים”. אבער דער פירוש איז לכאורה ניט גלאטיק, ווייל פון לשון הפסוק איז משמע, אז מיט דער טענה ותביעה צום אויבערשטן האט משה געוואלט פועל׳ן א כפרה אויף חטא העגל און ניט צו בא־וארענען זיך „שלא יאמרו עלי כו׳”.\nאויך ועיקר — ווען עס רעדט זיך וועגן ניט אויספירן, ח״ו, „תשא חטאתם” „חטאה גדולה”, וואס פאר א תפיסת מקום האט בא משה רעיא מהימנא וואס מען וועט זאגן וועגן עם?!\nד. דער ביאור בזה:\nמשה רבינו איז איין זאך ממש מיט כלל ישראל, ביז אז ס׳איז ניט שייך צו אפטיילן אים פון אידן בכלל ובפרט, ובלשון רש״י²¹: משה הוא ישראל וישראל הם משה.\nוואס דערפאר האט דער חטא העגל געפועל׳ט א ירידה אין משה, כמחז״ל אויפן פסוק „לך רד — רד מגדו־לתך”²². דלכאורה: משה האט דאך ניט געהאט קיין שייכות כלל צום חטא העגל, אפילו ניט אינעם גדר פון „מי שיש בידו למחות”, ווארום ער איז דע־מאלט געווען בהר (כפשוטו, ובפרט ועאכו״כ — במצבו ברוחניות). היינט פארוואס זאל דער חטא העגל אנרירן אים?\nנאר ווייל משה איז איין זאך מיט ישראל (ובמילא — גדולתו ניתנה און איז געווארן איין זאך מיט גדולת ישראל), האט דער חטא (העגל) און ירידה פון ישראל בדרך ממילא גע־פועל׳ט א ירידה אין משה׳ן.\nאון אט די התאחדות פון משה מיט אידן איז נאך טיפער ווי זיין התאחדות מיט תורה:\nכשם ווי מ׳געפינט ביי דער פאר־איינציקונג פון אידן מיט דעם אוי־בערשטן, אז אע״פ אז „אורייתא וקוב״ה כולא חד”²³ (ווי דער פירוש הפנימי²⁴ פון מחז״ל²⁵ „אנא נפשי כתבית²⁶ יהבית”, אז דער אויבערשטער האט זיך אליין („נפשי”) „אריינגעשריבן” און „אפגעגעבן”²⁷ אין תורה), פונדעסט־וועגן איז די התאחדות פון אידן מיט",[["18","18","משא״כ להפירוש (רמב״ן אברבנאל ועוד עה״פ. וראה תיב״ע עה״פ. ר״ה טז, ב) שמחני מספר החיים, שרצה לסבול עונשם וכיו״ב. וראה מכילתא לבא יב, א. זח״א סז, ב. קו, א. רנד, ב. זח״ג יד, ב ואילך. מקומות שצויינו בהערה 14."],["19","19","עה״פ."],["20","20","בשמו״ר פמ״ז שם, „כל התורה שנתת לי . . דבר אל בנ״י כו׳ אם הם כלים מה אני עושה בתורתך” — אבל עפ״ז אין זו בקשה ותביעה, כ״א הדגשה שבאם ישמיד אותם בדרך ממילא יהי׳ „מחני” (אבל ביפה תואר שם: כל המקומות כו׳ דבר אל בנ״י אין להם מקום וצריך להגיהם). [במהרז״ו שם, „וכשתשמיד אותם בהכרח שתמחה גם שמם מן התורה, מחה גם שמי שלא דברת עמי רק בשבילם”. ועפ״ז „מחני נא” היא בקשה נוספת. אבל עדיין צע״ג (ע״ד הקושיא שבפנים): זה ש„תמחה גם שמם מן התורה” הוא תוצאה מהעיקר („שתשמיד אותם”): וא״כ למה היתה בקשת משה רק „מחני נא מספרך” — מן התורה. וראה בהעלותך יא, טו]."],["21","21","חוקת כא, כא."],["22","22","תשא לב, ז ובפרש״י שם. ברכות לב, א. ועוד."],["23","23","זהר הובא בתניא פ״ד, רפכ״ג. וראה זח״א כד, ב. זח״ב ס, א. תקו״ז ת״ו (כא, ב), תכ״ב (סד, א). ועוד."],["24","24","ראה לקו״ת שלח מה, סע״ד."],["25","25","שבת קה, א."],["26","26","כ״ה גירסת הע״י שבת שם."],["27","27","ראה גם תניא פמ״ז."]]],[1300211189,"קוב״ה נאך טיפער און העכער דערפון, וכמחז״ל²⁸ אז „ישראל קדמו” לתורה;\nעד״ז (וכתוצאה מזה) איז ביי נשיאי הדור — וואס (בלשון רש״י²¹) „נשיא הדור הוא ככל הדור” — אז זייער התאחדות מיט די אידן פון זייער דור איז נאך העכער פון זייער התאחדות מיט תורה —\n[און אזוי איז אויך ביי צדיקים בכלל (וואס „דומים לבוראם”²⁹): אע״פ אז זיי „גיבן זיך אריין” אין די עניני תורה³⁰ וואס זיי לערנען ובפרט זייערע חידושי תורה³¹, קומט דאס אבער ניט צו זייער פאראיינציקונג מיט אידן, ובפרט די וואס האבן צו זיי א שייכות (ובמילא אחריות) מיוחדת, עניי עירך, בנים ותלמידים כו׳ (בלשון הפסוק³²: הנפש אשר עשו)].\nה. דאס איז אויך דער ביאור אין בקשת משה „מחני נא מספרך” און דער טעם וואס ער האט איינגעשטעלט זיין עצם מציאות ווי זי איז פארבונדן מיט תורה צוליב (אויך) די עושי העגל:\nווייבאלד אז די התאחדות פון משה מיט אידן איז נאך העכער פון זיין התאחדות מיט תורה, דערפאר איז די תוצאה דערפון געווען אין ביידע ענינים:\n(א) אז אויך זיין מסירת נפש פאר אידן³³ איז פריער און העכער פון זיין מסירת נפש אויף תורה.\n[ע״ד ווי עס שטייט אין מגיד מישרים, אז דער בית יוסף האט געדארפט זוכה זיין צו מסירת נפש על קידוש השם³⁴, נאר צוליב א געוויסער סיבה האט מען אים מעניש געווען און ער האט בפועל דערצו ניט זוכה געווען —\nוואס אויב ער וואלט אומגעקומען על קידוש השם וואלט ער ניט געהאט די מעגלעכקייט צו מחבר זיין דעם שולחן ערוך שלו כולו³⁵, שממנו תצא תורה",[["28","28","ב״ר פ״א, ד. תנא דבי אליהו רבה פי״ד."],["29","29","רות רבה פ״ד, ג. ב״ר פס״ז, ח. ועוד."],["30","30","כמשנ״ת במ״פ (לקו״ש חי״ז ע׳ 423. ועוד) במ״ש כ״ק אדמו״ר מהורש״ב נ״ע לפני הסתלקותו: איך גיי אין הימעל און די כתבים לאז איך אייך."],["31","31","להעיר ממחז״ל (ע״ז יט, א) — כנ״ל בפנים — שתורתו נקראת על שמו."],["32","32","לך יב, ה ובפרש״י שם. סנהדרין צט, ב. ועוד."],["33","33","ראה במקומות שצויינו לעיל סוף הערה 18."],["34","34","ריש פרשתנו. ועד״ז ר״פ בראשית סד״ה הלא לך למנדע. פ׳ אמור ד״ה אח״כ פ׳ לי. פ׳ ברכה ד״ה אור ליום א׳. ובכ״מ."],["35","35","שהרי סיום חיבור ד׳ חלקי השו״ע בשנות שט״ו־שכ״ג (כמ״ש הב״י בסוף כ״א מחלקי השו״ע (נעתק בדפוס ראשון)) — סמוך לסוף ימיו; ואילו בשורת המגיד שיזכה לקדה״ש הי׳ קודם עלייתו לא״י (ראה במגיד מישרים שם פ׳ בראשית תצוה וברכה הנ״ל), והב״י עלה לא״י בשנת רצ״ז. [ומ״ש בפ׳ ברכה (בהמשך ל„אזכך לאתוקדא בא״י כו׳”) „ואזכך למגמר חיבורא דילך”, הרי מסיים שם „דאקריא בית יוסף” — ב״י על הטור. וכ״מ מהא שאמר „למגמר חיבורא דילך”, והשו״ע משמע בכ״מ שהתחילו לכתוב לאחרי שעלה לא״י (משא״כ הב״י שהתחיל בשנת רפ״ב בחו״ל, כמ״ש בסוף ספרו ב״י לטחו״מ)]. ואכ״מ. ד״ע העירוני אשר ב„אזהרות ותקונים וסייגים” שבתחלת הספר. פ׳ בשלח ד״ה אור ליום שבת י״א שבט — מפורש שיזכה לקדה״ש לאחרי שיגמור „כל חיבוריך (ופרשיך) ופסקיך . . ולהדפיסם ולפשטם בכל גבול ישראל” — וא״כ נכלל גם השו״ע. ובפרט עפמ״ש שם בפ׳ צו (סד״ה אור לי״ד ניסן): חיבורא דילך מלבד השם הראשון שאמרתי לך שיקרא בית יוסף עוד יקרא שולחן ערוך. אלא שאין בזה סתירה להמבואר בפנים השיחה, כי בפשטות, בשורות השונות מהמגיד להב״י (במשך שנים רבות) שיזכה לאיתוקדא על קדה״ש כשכר עבודתו בתנאים שונים: לאחרי שיעלה לא״י: כשיגמור חיבור הב״י: כשיגמור כל חיבוריו ועוד — אינן בשורה אחת (שפעם אמרה בפרטיות ופעם בקיצור) — שהרי פשוט שבמשך השנים היו כו״כ שינויים בדרגות ובמצבו של הב״י (ועד לשינוי העיקרי בנדו״ד — שניטלה ממנו הזכות להשרף על קדוה״ש)"]]],[1300211190,"והוראה לכל ישראל, אעפ״כ איז דאס אן ענין של עונש, ווייל ווי הויך ס׳איז דער עילוי אין תורה, קומט עס אבער ניט צו מסנ״פ על קידוש השם³⁶, וואס דאס איז מסנ״פ ווייל מ׳איז א איד³⁷ און אז מען זאל זיין א איד — איינס מיט השם].\n(ב) די התאחדות (ובמילא — די מסירת נפש) איז מיט (און פאר) יעדער אידן, אין וואס פאר א מצב ער זאל נאר זיין (אפילו די עושי העגל). ווייבאלד דאס איז העכער פון תורה, ווערט עס ניט בטל דורכדעם וואס א איד איז אפגעריסן פון תורה, כמחז״ל³⁸ „אע״פ שחטא ישראל הוא”.\nאון דאס איז אויך דער פירוש אין „אם תשא חטאתם ואם אין מחני נא מספרך גו׳”: אויב דער חטא העגל איז אזוי חמור אז תורה גיט ניט קיין ארט אויף „תשא חטאתם” (השם וואלט מכפר געווען נאר תורה איז כביכול תובע און מונע³⁹), איז משה׳ס בקשה און תביעה: „מחני נא מספרך” — פון תורה; דא־מאלס שטייט בגלוי, בלי לבוש כלל משה׳ס עצמיות׳דיקע התאחדות מיט אידן, און דורך דעם — דער יחוד פון אידן מיט קוב״ה וואס איז העכער פון דער התאחדות מיט תורה, וואס מצד דער התאחדות קומט די כפרה⁴⁰ אפילו אויפן חטא העגל (און דאס פארבינדט זיי דערנאך צוריק אויך מיט תורה).\nו. ע״פ כהנ״ל וועט מען אויך פאר־שטיין די שייכות פון בקשת משה „מחני” צו „ואתה תצוה”:\nאט די התאחדות פון משה׳ן מיט אלע אידן וואס איז נאך העכער פון תורה (וואס דריקט זיך אויס אין דער בקשה „מחני נא מספרך”), ווערט ארויסגע־בראכט אין דעם⁴¹ „ואתה תצוה את בני ישראל”, וואס איינער פון די פירושים אין דעם „ואתה” — די עצמיות פון משה׳ן — איז מקשר ומחבר („תצוה” לשון צוותא וחיבור⁴²) אלע אידן צוזאמען אין איין מציאות.",[["","","ובהכרח שיהיו שינויים גם בשכרו (בהתאם לדרגת עבודתו), כי אם שכל בשורה היא שכר לפ״ע עבודתו אז, והרי כו״כ דרגות במסנ״פ ובמסנ״פ על קדה״ש — (ראה פסחים ג, א הרוגי לוד. הקדמת תקו״ז (י, ב). ע״ח שליט, ד״א ועוד), ולאידך — כו״כ דרגות בתורת ובמצב הב״י. ולפעמים היתה עבודתו במסנ״פ וקדה״ש נעלית על תורתו ולפעמים להיפך."],["36","36","ראה בכ״ז אוה״ת אחרי (כרך ב) ע׳ תקמט. דרושים ליוהכ״פ (אוה״ת דברים כרך ה) ע׳ ב׳קלז־ח."],["37","37","וכמו שמצינו ענין המסנ״פ על קידוש השם אפילו בקל שבקלים (תניא ספי״ח) שנפרד ר״ל מכל התורה. וראה סה״מ תרנ״ט (ע׳ יג) שהכח למסנ״פ בא מזה שנעשו שרשו למעלה מן התורה. וראה בארוכה (במעלת מסנ״פ על קדה״ש — על כל התורה) שער האמונה בתחלתו. ס׳ הליקוטים לספרי הצ״צ ע׳ מס״ג (ע׳ תתצ ואילך), וש״נ."],["38","38","סנהדרין מד, רע״א (וברש״י שם: עדיין שם קדושתם עליהם). וראה המשך תער״ב ח״ג ע׳ א׳רנב ואילך. ובכ״מ."],["39","39","ע״ד מחז״ל (פסיקתא דר״כ פ׳ שובה. יל״ש יחזקאל יח, ד. יל״ש תהלים מזמור כה. וראה ירושלמי מכות פ״ב ה״ו) „שאלו לתורה חוטא מה ענשו כו׳ שאלו להקב״ה כו׳ אמר יעשה תשובה ויתכפר לו”. וראה לקו״ש חי״ד ע׳ 1152 ובהערה שם."],["40","40","עפ״ז יש לפרש (בפנימיות הענינים) מענה הקב״ה למשה (תשא שם, לג) „מי אשר חטא לי אמחנו מספרי” להפירוש שקאי על ספר התורה (וכקושיית הרמב״ן) — שיש בזה גם ענין למעליותא, שנמשך להחוטאים הכפרה שלמעלה מ(כפרת) התורה („ספרי”)."],["41","41","ע״ד הידוע (המשך תער״ב שם ע׳ א׳תח. ועוד) בענין התשובה, שאף שהיא למעלה מן התורה (שלכן בכחה למלאות מה שנחסר ב(לימוד ה)תורה כו׳), הנה זה גופא נתגלה בתורה דוקא."],["42","42","תו״א פרשתנו פב, א. סד״ה זאת תורת הבית הנ״ל. ד״ה וקבל היהודים (תרפ״ז) בסה״מ תרפ״ז ותשי״א פ״ד."]]],[1300211191,"מצד די מדריגות פון משה וואס זיינען פארבונדן מיט א „שם” — וואס דאס איז כולל אפילו יחידה שבנפש, וואס איז איינער פון די „חמשה שמות נקראו לה”⁴³ (די נשמה) — דערגרייכט מען די גילויים שלמעלה, וואס זיינען ניט העכער פון תורה (ווארום „כל התורה כולה שמותיו של הקב״ה”⁴⁴); און דערפאר קען מען מצד דער מדריגה ניט אויפטאן דעם צוותא וחיבור וואס נעמט ארום אלע אידן בשווה.\nדוקא „ואתה (תצוה)”, די עצמיות פון משה וואס איז העכער פון שם ותואר (דער עצם הנפש וואס ווערט ניט נתפס אין די „חמשה שמות”), וואס פארבינדט זיך מיטן „אתה” העיקרי והאמתי „אתה” שלמעלה, עצמותו ומהותו ית׳⁴⁵ (וואס באמת לאמתתו איז דוקא נאר אויף עצמות שייך זאגן „אתה”⁴⁶, לשון נוכח, ושם שמים שגור בפי כל⁴⁷) — פועל׳ט דעם „תצוה את בנ״י”, דעם צוותא וחיבור פון אלע אידן — אפילו די עושי העגל⁴⁸ — אין איין מציאות.\nאון דאס איז אויך דער קשר פון „ואתה תצוה” צום המשך הציווי „ויקחו אליך שמן גו׳ להעלות נר תמיד” — דלכאורה: די העלאת הנרות איז דאך געווען דורך אהרן, היינט פארוואס איז דער אנזאג „ויקחו אליך” (צו משה׳ן)⁴⁹?\nשטייט אויף דעם דער ביאור⁵⁰: אהרן מצד עצמו איז פועל⁵¹ אויף אידן וועלכע זיינען „נרות”, וועלכע (זיינען מוכן) לייכטן מיט „נר מצוה ותורה אור”⁵² — עובדי ה׳; אבער דורך דעם וואס „ויקחו אליך שמן גו׳” — צו משה׳ן, וואס ער איז מצוה ומחבר אלע אידן (כנ״ל) — ווערט דאס אויפגעטאן אין אלע אידן („אפילו הפשוטים ביותר”⁵³), זייער עצם שבנפשם ווערט נתגלה⁵⁴.\nז. עפ״ז וועט מען אויך פארשטיין די שייכות פון „ואתה תצוה” צום תוכן פון כללות הסדרה (וואס דערפאר ווערט ניט דערמאנט שמו של משה אין דער גאנצער סדרה):\nאין דעם גאנצן סיפור וועגן כהונת אהרן ובניו אין דער סדרה איז מודגש, ווי דאס דארף געטאן ווערן דורך משה׳ן דוקא. ווי עס שטייט אויך גלייך בהתחלת הענין⁵⁵ „ואתה הקרב אליך את אהרן גו׳ לכהנו לי”, „ועשית בגדי קדש לאהרן אחיך גו׳”; ועד״ז איז דער גאנצער חינוך לכהונה פון אהרן ובניו דורכגעפירט געווארן דוקא דורך משה, ווי דערציילט בארוכה אין דער פרשה",[["43","43","ב״ר פי״ד, ט. דב״ר פ״ב, לז."],["44","44","רמב״ן בפתיחת פי׳ עה״ת, ע״פ זח״ב פז, א."],["45","45","ראה סד״ה זאת תורת הבית שם."],["46","46","כי „כל הנמצאים . . לא נמצאו אלא מאמתת המצאו ואם . . (ש)הוא אינו מצוי אין דבר אחר יכול להמצאות” (רמב״ם בתחלתו)."],["47","47","ראה תו״א יד, ב. ד״ה חכמות בחוץ תרצ״ד (בסה״מ קונטרסים ח״ב) פ״ב. ובכ״מ."],["48","48","להעיר גם מאוה״ת פרשתנו (ע׳ א׳תקנא) בפי׳ „ואתה תצוה” — „שתקשר ותחבר . . ב׳ שמות הוי׳ . . להיות יגיה חשכי של דורות האחרונים דבחי׳ עקביים”."],["49","49","כקושיית המפרשים."],["50","50","ד״ה זאת תורת הבית שם פי״י־יא. ולהעיר ג״כ מד״ה וקבל היהודים הנ״ל ע״ד משה רעיא מהימנא (ע״ש באורך)."],["51","51","ע״י עבודתו בהעלאת הנרות, שושבינא דמטרוניתא — אף שבכלל מדתו „אוהב את הבריות” (אבות פ״א מי״ב)."],["52","52","משלי ו, כג."],["53","53","ד״ה זאת תורת הבית שם. וראה אוה״ת הנ״ל (הערה 48)."],["54","54","ראה תניא ספי״ח."],["55","55","כח, א־ב."]]],[1300211192,"— וואס איינער פון די ביאורים בזה איז (ע״ד הנ״ל בענין נרות המנורה):\nאהרן הכהן מצד עצמו, איז ענינו כהונה וקדושת המשכן, ובמילא וואלט אויך זיין עבודת הכהונה געהאט א ווירקונג (בעיקר) נאר אויף „עובדי ה׳” וואס האבן א גלוי׳דיקע שייכות צום (מנורת ה)משכן ומקדש; דורך דעם אבער וואס „ואתה⁵⁶ (משה) הקרב אליך את אהרן אחיך גו׳ לכהנו לי”, איז כהונת אהרן באופן אז עס טוט אויף אין אלע אידן („אפילו הפשוטים ביותר”).\nאון דאס איז אויך פון די טעמים וואס גלייך נאך חינוך אהרן שטייט⁵⁷ דער ציווי אויפן „מזבח מקטר קטורת”⁵⁸ — דלכאורה האט דער ציווי אויף עשיית מזבח הפנימי געדארפט שטיין פריער אין פ׳ תרומה צוזאמען מיטן ציווי אויף אלע כלי המשכן (כולל דעם מזבח החיצון)⁵⁹ —\nנאר ווייל אט דער ענין (אז כהונת אהרן דארף זיין פארבונדן מיט אלע אידן) דריקט זיך אויס אין דעם ענין הקטורת⁶⁰, וכמחז״ל⁶¹ אז „כל תענית שאין בה מפושעי ישראל אינה תענית שהרי חלבנה ריחה רע ומנאה הכתוב עם סממני קטורת” (ע״ד ווי גערעדט פריער, אז משה האט זיך מוסר נפש געווען אפילו פאר די עושי העגל)⁶².\nאון בפרט קומט דאס ארויס בגלוי אין עבודת הקטורת פון יוהכ״פ⁶³, ווי עס שטייט בסיום וחותם הסדרה: וכפר אהרן על קרנותיו גו׳ אחת בשנה יכפר עליו לדורותיכם⁶⁴ גו׳.\nח. דערפון האט מען אויך א הוראה נפלאה אין עבודת ה׳:\nאזוי ווי משה רבינו איז געווען גרייט צו מוותר זיין אויף אן ענין הכי נעלה ועיקרי שבו (זיין פארבונד מיט תורה) צוליב אידן, און אפילו פאר עושי העגל — וואס דאס איז נאך מער ווי „ואהבת לרעך כמוך”⁶⁵: דער „כמוך” פון משה׳ן איז דאך תורה, זיין גאנצע מציאות איז געווען דורכגענומען מיט תורה; איז משה געווען גרייט צו מוותר זיין אויף דעם כדי צו זיין אינאיינעם⁶⁶ מיט אידן — כולל וועלכע זיינען געווען אפגע־ריסן ר״ל פון תורה:",[["56","56","כמו „ואתה תצוה”."],["57","57","לאחרי הציווי על קרבן תמיד. ולהעיר מד״ה זאת תורת הבית שם, שהענין ד„נר תמיד” (למעלה משינויים) נעשה ע״י משה דוקא, ע״ש."],["58","58","ל, א ואילך. — ועפ״ז המבואר בפנים מובן הקשר בין תחלת הסדרה וסיומה (דנעוץ תחלתן בסופן)."],["59","59","כקושיית המפרשים (רמב״ן, ספורנו ועוד שם)."],["60","60","גם להעיר דקטרת הוא לשון קשר והתקשרות (ובצרור המור סוף פרשתנו: ומקשר הדברים התחתונים בעליונים כו׳), ע״ד „תצוה” (כנ״ל בפנים)."],["61","61","כריתות ו, ב."],["62","62","ושייך זה למזבח הפנימי — כי ענינו של מזבח הפנימי הוא עצמיות פנימיות הלב, בחי׳ יחידה שבנפש (ראה לקו״ש ח״ב ס״ע 675 ואילך, וש״נ) שבזה כל ישראל שוין."],["63","63","וראה בארוכה לקו״ש חי״ט ע׳ 302 ואילך. ועיי״ש שי״ל שלכן ביוהכ״פ דוקא מתירין להתפלל עם העבריינים (טושו״ע ודאדה״ז או״ח ר״ס תריט)."],["64","64","להעיר גם מתחלת הסדרה (כז, מא) „לדורותם”. וראה אוה״ת הנ״ל."],["65","65","קדושים יט, יח."],["66","66","ראה ע״ח שליב פ״ב „ניצוצין של משה בסוד . . שחת עמך . . ע״כ טרח בעבורם כ״כ ומת במדבר בעבורם כי רצה לתקנם”. וראה ש׳ הפסוקים בפ׳ שמות בארוכה. *) להעיר מדברים רבה פ״ב, ט. זח״ב קנז, סע״א."]]],[1300211193,"עד״ז האט ער אלס רעיא מהימנא⁶⁷, געוואלט און געגעבן כח יעדער אידן ובכל זמן ומקום ער זאל זיך אזוי אויפ־פירן:\nאון דאס איז טענתו: אויב עס וועט ניט זיין ח״ו „תשא חטאתם” (ובמילא — „אשר חטא לי אמחנו מספרי”) און ער וועט בלייבן „בספרך”, יאמרו עלי שלא הייתי כדאי כו׳ ווארום ער האט זיך ניט געוואלט מוסר נפש זיין ביז מחני מספרך — און מען וועט זיך אפלערנען פון דעם לדורי דורות!\nההוראה מכ״ז ווי עס דארף זיין בעבודת כאו״א: ס׳איז ניט גענוג וואס מ׳האט אהבת ישראל, און צו יעדער איד (אין וואס פאר א מצב ער זאל נאר זיין)⁶⁸, און די אהבה איז „כמוך” — נאר עס מאנט זיך מסירת נפש פאר א צווייטן אידן, און פאר יעדער אידן, וואס דארף זיך אויסדריקן אין „אוהב את הבריות ומקרבן לתורה”⁶⁹.\n(משיחת ש״פ תצוה תש״מ)",[["67","67","ראה תניא רפמ״ב."],["68","68","ראה בארוכה קונטרס אהבת ישראל. לקו״ש חי״ז ס״ע 216 ואילך. וש״נ."],["69","69","אבות פ״א מי״ב. וראה בארוכה לקו״ש שם ע׳ 220 ואילך."]]],[1300211194,"<h3>תצוה ב</h3>\nא. די פרשה אין אונזער סדרה פון עשיית ולבישת בגדי כהונה פאַר־ענדיקט זיך מיטן אנזאָג1 „והיו על אהרן ועל בניו בבואם אל אהל מועד או בגשתם אל המזבח לשרת בקודש ולא ישאו עון ומתו\". איז רש\"י מעתיק דעם וואָרט „ומתו\" און איז מפרש: „הא למדת שהמשמש מחוסר בגדים במיתה\"2.\nפרעגן מפרשים3: לויט פרש\"י האָט מען שוין פריער געלערנט4 „והי' על אהרן לשרת ונשמע קולו בבאו אל הקודש לפני ה' ובצאתו\": „ולא ימות — מכלל לאו אתה שומע הן, אם יהיו לו לא יתחייב מיתה, הא אם יכנס מחוסר אחד מן הבגדים הללו חייב מיתה בידי שמים\" — פארוואָס דארף מען נאָכאמאָל לאָזן הערן („הא למדת\") דעם זעלבן דין?\nלולא פירוש רש\"י ביים צווייטן פסוק, וואָלט מען געקענט לערנען אז דער פסוק חזר׳ט עס איבער נאָכאמאָל נאָר בכדי צו מוסיף זיין אין דעם חומר הענין, ע\"ד ווי מען געפינט בכ\"מ, אז די תורה חזר׳ט איבער מער ווי איין מאָל דעם זעלבן איסור ואזהרה „לעבור עליו בב' לאוין\"5 וכיו\"ב.\nרש\"י זאָגט אבער דאָ בפירוש „הא למדת\" — דוקא פון דעם (צווייטן) פסוק לערנט מען אָפ דעם דין — איז ניט מובן: רש\"י אליין האָט שוין געזאָגט, אַז מ'לערנט דאָס אָפ פון דעם פריערדיקן פסוק?\nב. דער ראַ\"ם6 איז מסביר, אַז פון פריערדיקן פסוק לערנט מען נאָר בנוגע די ששה בגדים וועלכע ווערן דער־מאָנט אין די פסוקים ביז דאָרטן7 — חושן אפוד מעיל כתונת מצנפת ואבנט — אבער ניט בנוגע די צוויי בגדים (ציץ ומכנסים) וועלכע זיינען פריער ניט דערמאָנט; און דעם דין (אַז ווען ס'פעלט ציץ אדער מכנסיים איז מען חייב מיתה), לערנט מען אָפ פון דעם (צווייטן) פסוק „ולא ישאו עון ומתו\", וועלכער שטייט נאָכן ציווי אויף ציץ ומכנסים.\nולכאורה קען מען אזוי מדייק זיין פון די שינויי הלשונות בפרש\"י:\nאין פריערדיקן פסוק זאָגט רש\"י „הא אם יכנס מחוסר אחד מן הבגדים הללו\", משא\"כ אין דעם פסוק זאָגט רש\"י „מחוסר בגדים\" סתם — ווייל פון פריערדיקן פסוק ווייס מען (לפרש\"י) נאָר וועגן „בגדים הללו\" — די וועלכע ווערן פריער דערמאָנט; אָבער ביים צווייטן פסוק איז רש\"י סותם „משמש מחוסר בגדים\", אָ „מחוסר\" פון איינעם פון בגדים (אלע שמונה בגדים) איז חייב מיתה.\nעפ\"ז איז אבער ניט פארשטאַנדיק לאידך גיסא: ווייבאַלד אַז עס שטייט אין",[["1","1","פרשתנו כח, מג."],["2","2","כ\"ה בדפוסים שלפנינו. אבל בדפוס ראשון שני וכת\"י רש\"י שתח\"י „חייב מיתה\" (וכן הועתק ברמב\"ן שבהערה 8 וברא\"ם כאן)."],["3","3","כו\"כ מהם הובאו ונסמנו לקמן."],["4","4","שם, לה."],["5","5","ראה פרש\"י תשא לד, כג. צו ו, ו. שמיני יא, מד. אמור כג, לא. ועוד."],["6","6","עה\"פ כאן (וכן בשפ\"ח). וראה בארוכה בפירושו פרשתנו שם, לה."],["7","7","פרשתנו שם, ד."]]],[1300211195,"פסוק דער עונש נאָכדעם ווי די תורה רעכנט אויס אַלע שמונה בגדים — צוליב וואָס דארף שטיין פריער אַ אַזונדערע אזהרה בנוגע די „בגדים הללו\" (די ששה בגדים הנ\"ל), וועלכע זיינען אין כלל פון די שמונה בגדים?8\nג. אַנדערע מפרשים לערנען9, אַז די ביידע פסוקים רעדן ניט וועגן סתם (וועגן אַלע) בגדי כהונה — דער ציווי אין ערשטן פסוק באַציט זיך נאָר צום מעיל10, וואָס וועגן אים איז מדובר אין יענעם פסוק און אין די פסוקים שלפנ\"ז דאָרט; די צווייטע אזהרה „והי' על אהרן ועל בניו גו' ולא ישאו עון ומתו\" איז נאָר בנוגע די מכנסים וועגן וועלכע עס רעדט זיך אין פריערדיקן פסוק11. און דאָס וואָס רש\"י זאָגט דעם לשון „המשמש מחוסר בגדים\" סתם, און אזוי אויך פריער „אם יכנס מחוסר אחד מן הבגדים הללו\", איז ניט כוונתו, אז דאָס ווערט אָפגעלערנט פון די צווייי פסו־קים\n(די עצם ילפותא איז פון אָ ווייטער־דיקן פסוק אין דער פרשה12 — „וחגרת אותם גו' והיתה להם כהונה לחקת עולם\", אז דוקא דורך די בגדים ווערט אויפגעטאָן ביי די כהנים דער ענין הכהונה, און ווי די גמרא13 לערנט אָפ\nפון דעם פסוק אז „בזמן שבגדיהם עליהם כהונתם עליהם, אין בגדיהם עליהם אין כהונתם עליהם והוו להו זרים\" און „זר ששימש במיתה\"),\nנאָר ווייבאַלד ס'איז „קושטא דמילתא\" אַז אָ „מחוסר אחד מן הבגדים\" איז חייב מיתה איז רש\"י מפרש „לפי האמת\"14.\nלפי זה איז אבער אינגאַנצן ניט פאַר־שטאַנדיק פירוש רש\"י אין די פסוקים, וועלכער איז פשוטו של מקרא [נוסף על כלל הידוע אז רש\"י15 פארלאָזט זיך ניט אויף דעם וואָס עס שטייט אין אַ ווייטערדיקן פסוק]:\nא) אויפן ווייטערדיקן פסוק „וחגרת אותם אבנט גו' והיתה להם כהונה\" ווערט אין רש\"י אינגאַנצן ניט דער־מאָנט דרשת חז\"ל הנ\"ל „בזמן שבגדיהם עליהם כהונתם עליהם כו'\" — רש\"י טייטשט דאָרט נאָר „והיתה להם, מילוי ידים זה לכהונת עולם\"16, און דאָס איז בכלל אַן ענין וועלכער איז פארבונדן מיט די שבעת ימי המילואים17 —",[["8","8","ועד\"ז קושיית הרמב\"ן (שם, מג (במהדורת שעוועל — שם, לה)) על פרש\"י. וראה ברא\"ם שם מה שהקשה על הרמב\"ן."],["9","9","ראה גו\"א בפסוק לה ובפסוק מג. ובאר\"א קצת — לבוש שם, לה."],["10","10","ראה ויק\"ר פ\"ב, ט."],["11","11","וכ\"ה ברבותינו בעה\"ת פסוק מג. ריב\"א שם. חזקוני שם. רמב\"ן הנ\"ל („לפי העולה מן הסוגיות שבגמרא\"). וכדעת הר\"י דאורליינש בתוד\"ה אין (סנהדרין פג, סע\"ב. זבחים יז, סע\"ב. תוד\"ה להביא יומא ה, ריש ע\"ב)."],["12","12","כט, ט."],["13","13","סנהדרין שם."],["14","14","גו\"א שם, לה. ועיי\"ש באריכות ובפסוק מג שמבאר הצריכותא דכל הג' לימודים."],["15","15","ולהעיר אשר גם בכמה ספרים שע\"ד ההלכה כן הוא. ולדוגמא בס' היד (יד מלאכי כללי הרמב\"ם אות ר')."],["16","16","וכמ\"ש ברא\"ם (שם כט, ט) ובמשכיל לדוד (שם כח, לה) שאותה הדרשה שבגמ' „בזמן שבגדיהם עליהן כו'\" אינה קרובה לפשט, ולכן לא ביאר רש\"י כן הפסוק שם."],["17","17","בגו\"א שם מפרש בכוונת רש\"י שם, מילוי ידים זה שהוא ג\"כ ע\"י לבישת הבגדים לכהונת עולם כי לבישת הבגדים הוא כהונתם כו' עיי\"ש. אבל גם לפירושו אי אפשר ללמוד משם, כי שם המדובר בלבישתם במשך ז' ימי המילואים, שעיי\"ז נכנסים לכהונת עולם — והיינו בהתחלת כל עיקר ענין הכהונה שנעשה ע\"י כל הפעולות כו' במשך ז' ימי המילואים כולל לבישת הבגדים. ואין מזה ראי' להדין דבכל כהן שלאח\"ז, שבזמן שבגדיהם עליהם כהונתם עליהם. וכמו רוב העבודות כו' דשבעת ימי המילואים דהוראות שעה הן, דאינם בכל כהן, אפילו"]]],[1300211196,"קען מען דאָך ניט זאָגן, אז רש\"י פאַר־לאָזט זיך דאָ אויף דעם ווייטערדיקן פסוק בשעת אז דאָרט איז ער מפרש באופן אחר18.\nב) אין דעם ערשטן פירוש רש\"י הנ\"ל, וואו ער זאָגט סתם „הא אם יכנס מחוסר אחד מן הבגדים כו'\", וואָלט מען אפשר געקענט לערנען (בדוחק גדול עכ\"פ), אַז רש\"י זאָגט עס „לפי האמת\" (כאטש מען לערנט עס ניט אָפ פון דאַנעט): אַבער בפירושו אויפן צווייטן פסוק זאָגט רש\"י בפירוש „הא למדת כו'\" — און דאָס ווערט אָפגעלערנט פון דעם פסוק.\nד. לכאורה וואָלט מען דאָס געקענט פארענטפערן באופן אחר, לויט נאָך אַ שינוי צווישן די צוויי פירושי רש\"י:\nאין פריערדיקן פסוק זאָגט רש\"י דעם לשון „הא אם יכנס מחוסר אחד מן הבגדים\" און אין דעם צווייטן פסוק זאָגט רש\"י „שהמשמש מחוסר בגדים\".\nזיינען מפרשים מסביר19, אַז פונעם\nערשטן פסוק, וועגן דעם מעיל, וואו דער לשון הכתוב איז „ונשמע קולו בבואו אל הקודש\", לערנט מען אָפ דעם איסור ועונש פון אַ מחוסר בגדים אויף כניסתו למקדש בלבד (אפילו ווען ער איז ניט עובד עבודה דאָרט<sup data-n=\"20\">20</sup>; און דער פסוק „ולא ישאו עון ומתו\", וועלכער שטייט בסמיכות צו „בגשתם אל המזבח לשרת בקודש\", איז בא ללמד אַז „המשמש מחוסר בגדים במיתה\", ד.ה. אויב ער איז עובד עבודה מחוסר בגדים.\nאון אע\"פ אַז נאָכדעם ווי מ'ווייס שוין אַז אַ מחוסר בגדים איז חייב מיתה אפילו אויף כניסה בלבד, דארף מען שוין ניט קיין באַזונדער לימוד אויף „המשמש מחוסר בגדים\" (ער איז דאָך שוין נתחייב מיתה געווארן תיכף בכניסתו)21 — זיינען דאָס מפרשים מבאר בכמה אופנים:\nא) אַז דער חיוב מיתה אויף דער כניסה פון אַ מחוסר בגדים איז נאָר „בבואו אל הקודש\", אין אוהל מועד, אבער ניט בחוץ, „בגשתם אל המזבח\" — און דאָס איז מוסיף דער צווייטער פסוק „בגשתם אל המזבח לשרת בקודש\", אַז דאָרטן איז (ער ניט מחוייב אויף דער כניסה וגישה, נאָר דוקא —",[["","","כשמתחנך לעבודה לשרת בביהמ\"ק. וראה בית האוצר להר\"י ענגל מערכת ב-ג אות יז (ח\"ב כו, א ואילך). וראה לקמן הערה 27."],["18","18","ואין לומר דאפשר ללמדו ממה שפירש בהתחלת הפרשה עה\"פ (כח, ג) ועשו את בגדי אהרן לקדשו לכהנו לי — „לקדשו להכניסו בכהונה ע\"י הבגדים שיהא כהן לי ולשון כהונה שירות הוא\", שהרי: א) שם מדובר בהתחלת כל עיקר ענין הכהונה, חינוכם לעבודה במשכן בשבעת ימי המילואים וכנ\"ל שלפנ\"ז, ואין מזה הוראה לדורות. ב) לפרש\"י שם גם בלי הבגדים נעשה לכהן לכהנו לי (שם, א) ואינן נקראים זרים, אלא שזה מכניסם לשירות דכהונה — ראה בארוכה לקו\"ש ח\"ו ע' 171 ואילך. ובמילא גם אין לומר שמפני זה יהי' חייב מיתה, ועד\"ז בפרש\"י ויקרא (א, ז-ח) דמדובר רק דעבודתו פסולה לא דחייב מיתה."],["19","19","א' מהתירוצים במשכיל לדוד פסוק לה. מלאכת הקודש שם. נחלת יעקב שם."],["20","20","כ\"ה דעת הריצב\"א בתוס' יומא שם*. אלא שלדעתו למדים זה מפסוק מג — „דאצטרך לחייב אפילו בביאה ריקנית אאוהל מועד מי שנכנס מחוסר בגדים\" [אבל להעיר שלפי הגירסא בתוס' סנהדרין שם דמיתה כתיב אמכנסיים (וכן ג' המהרש\"א בתוס' יומא שם) נמצא לכאורה שחיוב מיתה בביאה ריקנית הוא רק במכנסיים]. ובפנחה רזא פרשתנו שם פסוק לה בהגהה פירש כן בפרשי' דשם. וראה שעה\"מ הל' כלי המקדש פ\"ז ה\"ד. ואכ\"מ."],["21","21","וצ\"ע בדין הנכנס מלובש בכל הבגדים ופשט אחד מהם ואח\"כ יצא. וראה לקמן ס\"ת. *) ועד\"ז „יש מפרשים\" בתוס' סנהדרין שם (ושם מסיים בתוס': וא\"א לומר כן כדפרישית לעיל מתוך הברייתא)."]]],[1300211197,"לשרת) „המשמש מחוסר בגדים במיתה\"22.\nב) דאָס וואָס מען קען (לויט רש\"י) אָפלערנען דעם עונש, הן ביי „יכנס\" און הן ביי „משמש\" (ווי רש\"י לערנט) איז ווייל ס'זיינען דאָ צוויי פסוקים — איין פסוק (דער ערשטער) בא ללמד „אם יכנס מחוסר כו'\", און דער צווייטער — „המשמש מחוסר בגדים\"; אַבער ווען עס וואָלט געשטאַנען נאָר איין פסוק וואָלט מען געלערנט אז דער חיוב איז נאָר בא „המשמש מחוסר בגדים\"23.\nאַבער אויך דעם פירוש קען מען ניט אַננעמען לויט דרך הפשט, ווייל אין צווייטן פסוק שטייען ביידע זאכן — „בבואם אל אהל מועד או בגשתם אל המזבח לשרת גו' ולא ישאו עון ומתו\". קען מען דאָך פון דעם פסוק אליין אָפ־לערנען דעם חיוב מיתה אויף ביידע זאכן: סיי אויף כניסה (בבואם אל אהל מועד), און סיי אויף משמש מחוסר בגדים (בגשתם גו' לשרת)24.\n[ונוסף לזה: ווי גערעדט אַמאָל בארוכה25, איז ע\"ד הפשט ניט געווען אַ כניסה לאהל מועד (בהיתר) סיידן צוליב טאָן עבודה. ובמילא, ווען דער פסוק זאָגט אז מען דארף טראָגן בגדים „בבואו אל הקדש\", מיינט עס (בדרך הפשט) — דער אריינגיין לשרת בקודש]26.\nועפכ\"ז הדרא קושיא לדוכתא: פאַר וואָס דארף מען צוויי לימודים הנ\"ל?\nוגם: וואָס איז דער טעם פונעם שינוי הלשון אין די צוויי פירושי רש\"י: „יכנס מחוסר א' מן הבגדים הללו\"; „המשמש מחוסר בגדים (סתם)\".\nה. וועט דאָס פארשטיין בהקדם אַ שינוי כללי צווישן די צוויי פירושי רש\"י —\nדער לשון פון רש\"י אויפן צווייטן פסוק (מג) איז אינעם סגנון פון אַ דין „הא למדת שהמשמש מחוסר בגדים במיתה\"; און זיין פירוש אויפן פריער־דיקן פסוק (לה) איז בסגנון של סיפור „הא אם יכנס מחוסר אחד מן הבגדים הללו\".\nוי\"ל אַז אין דעם באַשטייט טאַקע דער חילוק צווישן די צוויי פירושי רש\"י:\nאין פסוק (מג) „והיו על אהרן ועל בניו גו' ולא ישאו עון ומתו חקת עולם לו ולזרעו אחריו\", רעדט זיך וועגן דעם דין כללי ביי אַלע כהנים, כהן גדול וכהן הדיוט, ובכל הדורות:\nמשא\"כ דער פריערדיקער פסוק (לה) וואו עס שטייט „והי' על אהרן לשרת\", רעדט וועגן אהרן כהן גדול בפרט, וואָס פון דעם וואָלט מען ניט געוואוסט בנוגע אַנדערע כהנים (הדיוטים)27.",[["22","22","נחלת יעקב שם. וכן משמע מפשטות לשון התוס' (יומא) הנ\"ל בהערה 20. אלא שהנח\"י דחה פירוש זה."],["23","23","מלאכת הקודש הנ\"ל."],["24","24","ומ\"ש במשכיל לדוד אינו ע\"ד הפשט."],["25","25","ראה בארוכה לקמן ע' 215 ואילך."],["26","26","ומזה מובן שאין לפרש כהתירוץ במלאכת הקודש."],["27","27","לכאורה יש לתרץ שהחילוק הוא רק בזה דבפסוק לה מדבר בכה\"ג ומפסוק מג למדין מחוסר בגדים גם לכהן הדיוט (ראה משכיל לדוד. וראה פענח רזא וריב\"א עה\"ת כאן בפי' הב'), ותרווייהו צריכי: בכה\"ג סברא לומר דבגדיו מוכרחים בו במיוחד, כנראה מזה שבעת מינויו צריך ללבוש הבגדים שבעה ימים רצופים, כמפורש בפרשתנו (כט, ל. ובפרש\"י), משא\"כ בכהן הדיוט; ומכש\"כ שלא היינו אומרים שבגדיו מוכרחים עד כ\"כ שמחוסר בגדים במיתה. ולאידך יש מקום לומר להיפך: דאם הי' נאמר מפורש רק בנוגע לכהן הדיוט לא מצינו למילף מזה לכה\"ג, כי י\"ל דשאני כהן הדיוט כיון שכהונתו לא „נתמלאה\" בתחילה ע\"י לבישת הבגדים לכן כל פעם שמשמש צ\"ל שיהיו"]]],[1300211198,"און כאטש אַז דער מחוסר בגדים פון פסוק מג, מיינט ניט נאָר דעם חסרון פון (איינעם פון) די ד' בגדים, אין וועלכע אַ כהן גדול און כהן הדיוט זיינען גלייך, נאָר ווי רש\"י איז מפרש בתחלת הכתוב, „והיו על אהרן — כל הבגדים האלה על אהרן הראויין לו\", ועל בניו „האמורין בהן\" — ווייס מען דאָך פון דעם לכאורה דעם דין אויך בנוגע די שמונה בגדים פון אהרן כהן גדול — היינט צוליב וואָס דארף מען אַ קרא מיוחד?\nאיז דאָס קיין קשיא ניט, ווייל פון פריערדיקן פסוק לערנט מען אָפ אַ לימוד ודין מיוחד, ווי דער דיוק לשון רש\"י דאָרט „אם יכנס מחוסר אחד מן הבגדים הללו\", כדלקמן.\nו. לויט פשטות הלשון י\"ל, אַז מיט די ווערטער „בגדים הללו\" מיינט רש\"י ניט די אַלע ששה בגדים (חושן אפוד מעיל מצנפת כתונת ואבנט)28 — וואָס ווערן (בלויז) דערמאָנט פריער ובתחלת הפרשה29 — נאָר בלויז די ג' בגדים אפוד חושן ומעיל, וואָס אויף פרטי עשייתם איז משה דאָ נצטווה געווארן.\nבאָ די דריי בגדים געפינט מען אין פסוק אַן ענין מיוחד — ביים סיום הציווי אויף יעדן פון די דריי בגדים איז דער פסוק מוסיף דעם תוכן פון זייער ענין און אויפטו:\nבסיום הציווי אויף מעשה האפוד30 —\n„ושמת את שתי האבנים על כתפות האפוד אבני זכרון לבני ישראל ונשא אהרן את שמותם לפני ה' על שתי כתפיו לזכרון\":\nביים סיום פון ציווי על החושן31 — „ונשא אהרן את שמות בני ישראל בחושן המשפט על לבו בבואו אל הקודש לזכרון לפני ה' תמיד\", „ונשא אהרן את משפט בני ישראל על לבו לפני ה' תמיד\"32:\nאון בסיום פון פ' המעיל: „והי' על אהרן לשרת ונשמע קולו בבואו אל הקודש לפני ה' ובצאתו\".\nד.ה. דער ענין ומכוון פון די בגדים איז פארבונדן מיט דער כניסה בלבד — מיט דעם אליין וואָס אהרן קומט לפני ה' אָנגעטאָן אין אַט די בגדים טוט זיך אויף אַ פעולה [דער ענין פון „לזכרון לפני ה'\" פון שמות בנ\"י דורכן אפוד וחושן, דער „משפט בני ישראל על לבו\" ע\"י החושן (ווי רש\"י טייטשט דעם תוכן במקומות הנ\"ל), און „ונשמע קולו בבואו אל הקודש\" באָם מעיל]:\nמשא\"כ בא די שאר הבגדים שטייט ניט בכתוב וואָס ענינם איז, נאָר נאָכדעם ווי עס שטייט בנוגע כללות כל הבגדים33 „והלבשת אותם את אהרן אחיך ואת בניו אתו ומשחת אותם ומלאת את ידם וקדשת אותם וכהנו לי\" — אַז זיי זיינען פארבונדן מיט מילוי ידים, קידוש און שירות פון די כהנים עצמם — פירט אויס דער פסוק, אַז דוקא דעמאָלט, קענען זיי אריינגיין און טאָן די עבודה, „והיו על אהרן ועל בניו",[["","","עליו כל הבגדים בפועל, משא\"כ בכה\"ג שכהונתו נתמלאה ע\"י לבישת הבגדים ז' ימים רצופים, יש מקום לומר דלבישת הבגדים לאח\"ז היא רק למצוה. אמנם אינו — כי נוסף על הדיוקים בשינוי הל' בפרש\"י „יכנס מחוסר אחד מן הבגדים הללו כו'\", הרי בפסוק מג „והיו על אהרן ועל בניו גו'\", מפורש בפרש\"י בכל אחד בגדיו הראויין לו, כדלקמן בפנים."],["28","28","כפי' הרא\"ם הנ\"ל."],["29","29","כמ\"ש הרמב\"ן שם, מג."],["30","30","כח, יב."],["31","31","כח, כט-ל."],["32","32","הנאמר על נתינת האורים והתומים בחושן המשפט."],["33","33","כח, מא."]]],[1300211199,"בבואם אל אוהל מועד או בגשתם אל המזבח לשרת בקודש\".\nד.ה. אַז אין זיי פאַר זיך איז ניטאָ קיין ענין מיוחד, און ענינם איז נאָר בכדי דער כהן זאָל קענען טאָן34 די עבודה35.\nז. און צוליב דעם דארף מען בײדע לימודים פון די פסוקים, און דערפאַר איז דער חילוק בפרש\"י עליהם:\nבנוגע אַלע בגדים לערנט מען אָפ אַז „המשמש מחוסר בגדים במיתה\", ווייל ענינם איז פארבונדן מיט עבודה ושימוש.\nאַבער „בגדים הללו\", די דריי בגדים אפוד חושן ומעיל, ביי זיי איז דער חיוב מיתה (פון אַ מחוסר בגדים) ניט מצד דעם שימוש שלאחר זה, נאָר מצד דער עצם כניסה להיכל: ווען ביי דער כניסה פעלט איינער פון די ג' בגדים, פעלט די פעולה ועבודה וואָס דער בגד טוט אויף, און דערפאַר איז ער מחויב מיתה.\n[און אע\"פ אַז אויך ביים ציץ שטייט מפורש (בגמר הציווי על עשייתו<sup data-n=\"36\">36</sup>: „והי' על מצח אהרן ונשא אהרן את עון הקדשים אשר יקדישו בני ישראל גו' והי' על מצחו תמיד לרצון להם לפני ה'\" —\nוואָס לפי\"ז באַשטייט זיין פעולה ועבודה אינעם עצם זיין „על מצח\nאהרן\", און פונדעסטוועגן איז דער פסוק כולל דעם חיוב מיתה ביי מחוסר ציץ ניט מיט די דריי בגדים הנ\"ל, נאָר צוזאַמען מיטן כללות'דיקן דין פון „המשמש מחוסר בגדים\" אין דעם צווייטן פסוק37 —\nאיז די הסברה בזה, אַז ענינו של הציץ איז ניט דומה צו ענינים פון די ג' בגדים, ווי רש\"י איז מסביר דעם פי' פון וואָרט „תמיד\" וואָס שטייט ביי ציץ: „תמיד לרצות להם אפי' אינו על מצחו שלא הי' כה\"ג עובד באותה שעה\"38, דהיינו, אַז די פעולה פונעם ציץ איז ניט פארבונדן מיט דער כניסה (און אפילו ניט מיט זיין געפינען זיך על מצח אהרן), נאָר דאָס איז אַ פעולה תמידית וואָס טוט זיך אויף מצד עצם הציץ39].\nח. ועפ\"ז קומט אויס אַ חידוש לדעת רש\"י, אַז אין דעם דין פון מחוסר בגדים איז פאַראַן אַ חילוק צווישן די ביידע סוגי בגדים: ווען אַ כה\"ג גייט אַריין אין היכל מחוסר בגדים, און (ניט טוען־דיק קיין עבודה) איז ער ארויס40 פון",[["34","34","כי לפי פרש\"י י\"ל ד„לשרת בקודש\" קאי גם על „בבואם אל אוהל מועד\". וראה לקמן ע' 217 ואילך."],["35","35","להעיר (ע\"ד ההלכה) מסהמ\"צ להרמב\"ם מ\"ע לג, ד„משמע שם דיש נ\"מ בין בגדי כה\"ג לבגדי כהן הדיוט דבגדי כה\"ג הלבישה היא מצוה, לא משום דבל\"ז הוה מחוסר בגדים כו' משא\"כ גבי בגדי כהן הדיוט דזה הוה רק לצורך קרבן שלא יהא מחוסר בגדים\" (צפע\"נ הל' כלאים פ\"י ה\"ב (יד, א)). ולהעיר מפירוש הראב\"ד לתו\"כ שמיני פרשה א ברייתא ד. בית האוצר שם (כג, ד ואילך). ואכ\"מ."],["36","36","כח, לח."],["37","37","וראה לבוש האורה בפסוק לה."],["38","38","ומובן מלשון רש\"י שזהו פשש\"מ לדעת רש\"י, אלא שממשיך „ולדברי האומר עודהו על מצחו מכפר ומרצה ולאו אינו מרצה נדרש על מצחו כו'\". אבל גם לדיעה זו מובן דשאני ציץ, כבהערה הבאה."],["39","39","ועוד ועיקר: פעולת הציץ היא „לרצות על הדם ועל החלב שקרבו בטומאה\" (פרש\"י שם ד\"ה את עון הקדשים) וא\"כ פעולתו בכלל אינה שייכת לעצם הכניסה (ואינה פעולה תמידית גם לפי' הא' ד„תמיד לרצות להם אפי' אינו על מצחו\"), כ\"א כשאירעה טומאה על הקרבן (ראה פרש\"י ד\"ה בין יומא ז, ב. סנהדרין יב, רע\"ב) מרצה להכשיר הקרבן."],["40","40","לכאורה י\"ל גם נפק\"מ אם פשט א' מן הבגדים לאחרי גמר העבודה קודם שיצא (וראה ראב\"ד שנסמן לעיל הערה 35) דישנו חילוק בין ג' הבגדים לשאר הבגדים, אלא שלשון רש\"י הוא „אם יכנס מחוסר כו'\". וגם בכתובים הנ\"ל אצל החושן"]]],[1300211200,"היכל41, איז אַ נפק\"מ צי עס פעלט איינער פון די דריי בגדים אַדער פון די אַנדערע חמש בגדים:\nאויב ביי אים פעלט איינער פון די אַנ־דערע חמש בגדים איז ניטאָ קיין חיוב מיתה, ווייל ער האָט ניט משמש געווען: אַבער ווען עס פעלט ביי אים איינער פון די „בגדים הללו\" איז „חייב מיתה בידי שמים\" אויך ווען ער האָט ניט משמש געווען, וכ(פשטות) לשון רש\"י „אם יכנס מחוסר אחד מן הבגדים הללו חייב מיתה\".\nט. וי\"ל מיינא של תורה שבפרש\"י:\nדי צוויי ענינים הנ\"ל בשייכות מיטן כהן גדול — (א) זיין כניסה לקודש, וואָס איז פארבונדן מיט די דריי בגדים, חושן אפוד ומעיל, און (ב) זיין עבודה בקודש (— מיט אַלע שמונה בגדים) — זיינען בהתאם צו די צוויי ענינים וואָס ווערן דורכדעם אויפגעטאָן ביי אידן:\nדער אויפטו פון עבודת כה\"ג (און אזוי אַלע כהנים) אין ביהמ\"ק, וואָס ער טוט אַלס שליח (אַדער42 פארשטעער — בא כח) פון כלל ישראל, איז צו פאַר־בינדן — דורך זיין עבודה בקודש „לפני ה'\" — אַלע אידן מיטן אויבערשטן.\nאון דער פארבונד פון אידן מיטן אויבערשטן איז אויף צוויי אופנים:\nא) ווי אידן פארבינדן זיך מיטן אויבערשטן דורך עבודה בפועל, דורך זייער עבודה בתורה ומצות, וכ־מארז\"ל43 אני נבראתי לשמש את קוני.\nב) ווי אידן, מצד זייער עצם מציאות, זיינען בניו אַדער עבדיו פון אוי־בערשטן44 (נאָך איידער זיי פירן דורך תפקידם בעולם).\n[ווי גערעדט אַמאָל בארוכה45 דער טעם פארוואָס אידן ווערן צוגעגליכן צו אַן „אוצר חביב . . כלי יקר ואבנים טובות שהמלכים גונזים אותם\"46: פונקט ווי די אוצרות הגנוזים של המלך איז ענינים ותכליתם ניט אויף צו דורכפירן מיט זיי אַ באַשטימטן תפקיד אין עניני המלוכה: זייער מציאות איז נאָר בכדי דער מלך זאָל זיך מיט זיי משתעשע זיין, האָבן פון זיי תענוג — עד\"ז איז די עצם מציאות פון אַ אידן העכער פון דעם תכלית וואָס דורך זיי ווערט דירה לו ית' בתחתונים: דער אויבערשטער איז זיך משתעשע מיט אידן].\nי. און דאָס זיינען די צוויי ענינים הנ\"ל בעבודת הכהן הגדול:\nפריער קומט זיין כניסה אל הקודש, וואָס דאָס איז מרמז אויף דער כניסה, אריינקום פון אַלע אידן (אין וועמענס שליחות וכו' ער גייט אריין) אל הקודש אין אַן אופן פון „לזכרון לפני ה'\". דער אויפטו איז ניט פארבונדן מיט דער עבודה פון כהן גדול בקודש, נאָר די",[["","","(כח, כט-ל) נאמר „בבואו אל הקודש . . בבואו לפני ה'\". ורק במעיל נאמר „ונשמע קולו גו' בצאתו\": אבל י\"ל שדיבור הכתוב בהווה (רש\"י משפטים כא, כה. ועוד), ואינו רגיל כלל שבהיותו בפנים, ובפרט לאחר גמר עבודתו — ימהר לפשוט בגד קודם צאתו. ואכ\"מ."],["41","41","ולהעיר שעצם היציאה מאה\"מ ע\"פ ההלכה אינה אסורה אלא כשיצא בשעת עבודה לדעת הרמב\"ם (הל' ביאת מקדש פ\"ב ה\"ה). וראה ראב\"ד שם. ואכ\"מ."],["42","42","דכהני שלוחי דרחמנא, או דישראל (נדרים לה, ב. וש\"נ). ולהעיר מענין שליח להולכה או לקבלה (משנה גיטין רפ\"ו. ועוד) ואם אפשר להיות שניהם (גיטין שם סב, ב)."],["43","43","משנה סוף קידושין."],["44","44","ובפרט ע\"פ מחז\"ל דישראל וקוב\"ה כולא חד — ראה זח\"ג עג, א. וראה שם צג, ריש ע\"ב."],["45","45","ראה לקו\"ש חכ\"ד ע' 162 ואילך. וש\"נ."],["46","46","ל' רש\"י יתרו יט, ה."]]],[1300211201,"עצם כניסה אל הקודש פועלט דעם „זכרון\" פון אידן ווי זיי זיינען מצד זייער עצם מציאות בניו אַדער עבדיו פון הוי' (נאָך איידער זיי פירן דורך זייער עבודה)47.\nאון ערשט דערנאָך הויבט זיך אָן די עבודה פון כהן גדול, ער איז „משמש\" בקודש, וואָס דאָס איז פארבונדן מיט די עבודה פון אידן, „לשמש את קוני\".\nיא. עפ\"ז וועט מען פארשטיין די שייכות פון כניסת הכה\"ג אל הקודש צו די דריי בגדים — חושן אפוד ומעיל — ווייל אין די בגדים זיינען מרומז די אידן לויט זייערע פארשידענע סוגים ודרגות:\nאויף אבני החושן והאפוד זיינען גע־ווען אויסגעקריצט „שמות בנ\"י\", וואָס דאָס זיינען די העכערע מדריגות פון אידן ביי וועמען מען זעט בגילוי (ובאופן דחקיקה<sup data-n=\"48\">48</sup> זייער „שם\" — בני ישראל\n[און אין דעם גופא זיינען פאַראַן צווי דרגות49:\n„חושן\" — וואָס מקומו איז „על לב אהרן\" — די מדרי' פון אידן וואָס האָבן אינגאַנצן מהפך געווען די מדות פון נה\"ב לקדושה;\nאון „אפוד\", וואָס די שתי האבנים זיינען „על כתפות האפוד\" (ניט מלפניו, על לב — ווי דער חושן) — איז דאָס מרמז אויף די אידן וואָס האַלטן נאָך ביי דער עבודה פון אתכפיא, וואָס איז בחי' „אחוריים\"50],\nאון דער מעיל איז פארבונדן מיט די מדריגות התחתונות פון אידן, וועלכע זיינען שייך בלויז צו מעשה בפועל. ווי גערעדט אַמאָל בארוכה51 אין דעם טעם וואָס בשולי המעיל זיינען געווען „רמונים\", ווייל זיי זיינען מרמז אויף די אידן וואָס זיינען אין דער דרגא פון „רמונים\"52 — „כפלח הרמון רקתך53 — ריקנים שבך מלאים מצות כרמון\"54.\nאון בשעת דער כהן גדול גייט אריין מיט אַלע סוגים פון אידן, ווערט דער „זכרון לפני ה'\", כנ\"ל55.\nאון אויף דעם זאָגט מען „אם יכנס מחוסר אחד מן הבגדים הללו חייב מיתה\" — כדי צו אויפטאָן דעם „זכרון לפני ה'\" פון בני ישראל, מוז מען האָבן אַלע סוגים פון אידן, און ווען עס פעלט",[["47","47","ראה אוה\"ת פרשתנו ע' א'תרפג בפירוש „לזכרון לפני ה' תמיד\" הנאמר בחושן המשפט, „וזהו ג\"כ ע\"ד שימני כחותם על לבך דקאי על תשר' אשר נאמר בהם ומי כעמך ישראל כו' והו\"ע וה' האמירך היום . . א\"כ בחושן המשפט היינו ענין וה' האמירך\". והרי וה' האמירך גו' להיות לו לעם סגולה גו' הוא מה שישראל הם אוצר חביב — ראה רש\"י תבוא כו, יח. נתבאר בלקו\"ש שם."],["48","48","ראה אוה\"ת שם ע' א'תרפד."],["49","49","ראה בארוכה אוה\"ת שם ע' א'תרסו-ז ואילך. *) כ\"ה בברכות ו, א. ולהעיר מנוסח אדה\"ז במנחת שבת (ראה שער הכולל שם)."],["50","50","ראה תו\"א פרשתנו פד, ד."],["51","51","לקו\"ש חט\"ז ע' 338 ואילך."],["52","52","ראה עקידה פרשתנו שער נא (קעח, א). תו\"א פ, סע\"ג."],["53","53","שיר השירים ד, ג."],["54","54","ראה עירובין יט, א. חגיגה בסופה. וש\"נ. ולפי\"ז אולי י\"ל דהג' בגדים (חושן אפוד ומעיל) הם ג' הבחי' דאמה עברי' עבד עברי ועבד כנעני, שהם ג' הסוגים דצדיקים בינונים ורשעים (ראה תו\"ח שמות ד\"ה וכי ימכור (עא, ב ואילך). דרך חיים שער התפלה פס\"ח ואילך. דרמ\"צ מצות יעוד או פדיון אמה העברי'. אוה\"ת משפטים ע' א'קכו ואילך. ועוד)."],["55","55","ועפ\"ז יומתק מה שאבני החושן והאפוד שעליהם היו כתובים שמות בנ\"י היו אבנים טובות כו', כי כניסת הכה\"ג עם החושן והאפוד תוכנה הוא שישראל הם „אוצר חביב . . כלי יקר ואבנים טובות\", כנ\"ל ס\"ט מפרש\"י יתרו."]]],[1300211202,"ביי דער כניסה איין סוג פון אידן — פעלט די (אַדער — אין דער) פעולה פון דער כניסה.\nווייל דער זכרון והתאחדות פון אידן מיטן אויבערשטן איז ניטאָ קיין התחלקות, זי נעמט אַרום אַלע אידן כאחד56. ובמילא, ווען מען טיילט אויס אַ אידן, פעלט דער ענין.\nיב. דאָס דארף זיין אַ הוראה פאַר יעדן רב, מורה דרך און פאַר יעדן איינעם וואָס קען האָבן אַ השפעה בסביבתו:\nבשעת מען טרעפט אַ אידן, אין וועלכן מצב ער זאָל נאָר זיין, דארף מען לכל לראש פועלן אין עם „לזכרון\", אים דערמאָנען וואָס זיין אמת'ע מציאות איז — ער האָט אַ נשמה וואָס איז אַ „חלק אלקה ממעל ממש\" און „ונמשכה ממחשבתו וחכמתו ית'\"57,\nובמילא ברינגט מען אים גלייך אַריין, „נכנס\" „לפני ה'\":\nאון דאָס ווערט אויפגעטאָן דורכן „כהן גדול\" שבדור — דורך דער התקשרות צו די צדיקים ותלמידי חכמים, וואָס דורכדעם איז „כאילו נדבק בשכינה ממש58 כי ע\"י דביקה בתלמידי חכמים קשורות נפש רוח ונשמה של עמי הארץ ומיוחדות במהותן הראשון ושרשן שבחכמה עילאה\"59 — וואָס דאָס איז נוגע צו אַלע סוגי אידן.\nאון ערשט דערנאָך הויבט מען אָן צו טאָן מיט אים אין עבודות ומדריגות פרטיות שלו, כולל „לכפר עליו\"60 — אַראָפנעמען די דברים בלתי רצויים וואָס האָבן זיך צו אים צוגעקלעפט,\nזהירות בסור מרע, הוספה בעשה טוב.\nאון דורך דער עבודה רוחנית פון די לבישת בגדי כהן איז מען זוכה צו „מלבישם לעתיד לבוא\"61, וואָס „אהרן ובניו ומשה עמהם\"61 אין דעם ביהמ\"ק השלישי.\n(משיחות ש\"פ תצוה וש\"פ תשא תשמ\"א)",[["56","56","כי ההתחלקות דג' בחי' הנ\"ל היא רק מצד הכחות הגלוים, אבל לא מצד עצמותם, ולפיכך כולם נכנסים בשוה (כי בעת הכניסה הוא גילוי בחי' זו שלמעלה מהתחלקות), ואעפ\"כ מודגש שהם ג' בגדים היינו ג' בחי' שונות, כי הכוונה היא שהתקשרות וכניסה זו שמצד העצם תחדור ותפעול גם בכל מדריגה פרטית במקומה בפנימיות."],["57","57","תניא פ\"ב. וראה אוה\"ת שם ע' א'תרסג בפי' „לזכרון לפני ה' תמיד\" — „דהיינו להעלותם לבחי' חכמה שנק' זכרון כו' לפי ששורש נש\"י הוא בבחי' חכמה כו'\"."],["58","58","ראה כתובות קיא, ב. ספרי עקב יא, כב."],["59","59","תניא שם."],["60","60","דעבודת הקרבנות וכן בגדי כהונה בכלל, ענינם כפרה — ראה זבחים פח, ב. ערכין טז, א."],["61","61","יומא ה, ב."]]],[1300211203,"<h3>פ' זכור</h3>\nא. אויף דער תקנה<sup data-n=\"1\">1</sup> פון קריאת פרשת זכור<sup data-n=\"2\">2</sup> — לייענען בתורה דעם שבת פאר פורים די פרשה פון „זכור<sup data-n=\"3\">3</sup> את אשר עשה לך עמלק\" — פרעגט דער מגן אברהם<sup data-n=\"4\">4</sup>:\nמ'געפינט דאך כו\"כ מצות פון „זכירה\" — ווי די „זכירות\"<sup data-n=\"5\">5</sup> וואס מ'דארף זיך דערמאנען<sup data-n=\"6\">6</sup> בברכות ק\"ש (וק\"ש): מ\"ת, מעשה עמלק, מעשה מרים, שבת און מעשה העגל — פאר־וואס האט מען מתקן געווען צו לייענען בתורה פ' עמלק דוקא, און ניט „בזכי־רות אחרים\"?\nאון ער פארענטפערט, אז „מ\"ת יש לנו חג עצרת וה\"ה שבת, ומעשה מרים ומעשה עגל לא תקנו מפני שהי' גנותן של ישראל\".\nלכאורה איז דאס אבער ניט קיין תירוץ מספיק. ווייל אויך במעשה עמלק — איז דאך פאראן פורים, וואס איז פארבונדן מיט זכירת ומחיית עמלק<sup data-n=\"7\">7</sup>, ביז אז די קריאה פון פורים איז<sup data-n=\"8\">8</sup> — די פרשה פון מלחמת עמלק („ויבא עמלק\"<sup data-n=\"9\">9</sup>); און נאך מער: דאס וואס פ' זכור איז דער שבת פאר פורים איז „כי היכי דלא תיקדום עשי' לזכירה\"<sup data-n=\"10\">10</sup>, הייסט עס דאך, אז פורים איז די „עשי'\" פון דער זכירה דפ' זכור —\nהיינט פארוואס דארף מען האבן א באזונדערע תקנה אויף קריאת זכירת עמלק, און ביז אז דער שבת ווערט אנגערופן „שבת פרשת זכור\" וכיו\"ב?\nאיז דערפון משמע, אז די תקנה פון פ' זכור איז (ניט נאר ווייל ס'איז ניטא קיין זמן מיוחד אויף צו דערמאנען מעשה עמלק, נאר) ווייל עס איז דא א יתרון וענין מיוחד אין זכירת מעשה עמלק<sup data-n=\"11\">11</sup> לגבי די אנדערע זכירות.\nדארף מען פארשטיין: וואס איז דער ענין מיוחד ביי זכירת מעשה עמלק, וואס איז ניטא ביי די אנדערע זכירות, און וואס דערפאר האט מען דוקא פאר דער זכירה קובע געווען א קריאה מיו־חדת?",[["1","1","כ\"ה במג\"א שצויין בהערה 4. וראה מג\"א סתרפ\"ה, דאף שקריאת פ' זכור הוא מה\"ת, זה שקוראים אותה בשבת זה דוקא הוא תקנת חכמים. וכ\"ה בשו\"ע אדה\"ז או\"ח סרפ\"ב סי\"ג שהוא „מתקנת אנשי כנה\"ג\" (אף שכתב (שם סט\"ז) ש„פרשת זכור היא חובה מן התורה\"). הדיעות בזה — ראה אנציקלופדי' תלמודית ע' ארבע פרשיות (ע' קסו), ע' זכירת מעשה עמלק (ע' ריט ואילך)."],["2","2","מגילה ל, א."],["3","3","ס\"פ תצא (כה, יז-יט)."],["4","4","סי' ס סק\"ב."],["5","5","הובא ג\"כ בשו\"ע אדה\"ז שם סעיף ד. וכן הכניסן אדה\"ז בסידורו לאחרי תפלת שחרית (שש זכירות)."],["6","6","נוסף לזכירת יצי\"מ שנזכרה בפירוש בפ' ציצית."],["7","7","ראה חינוך מצוה תרג: ודין הי' לקרותה (פ' זכור) ביום פורים לפי שהוא מענינו של יום כי המן הרשע הי' מזרעו. ובפרש\"י מגילה (כט, א ד\"ה ומפסיקין): לסמוך מחיית עמלק למחיית המן. ראה רמב\"ן ס\"פ תצא: ויהי' סמך למקרא מגילה מן התורה. ועוד."],["8","8","משנה מגילה ל, סע\"ב. ובמג\"א סתרפ\"ה שם שבזה יוצא מ\"ע דקריאת פ' זכור."],["9","9","בשלח יז, ח ואילך."],["10","10","מגילה ל, א."],["11","11","עד שלרוב הפוסקים קריאת פ' זכור היא מ\"ע מה\"ת (ראה הנסמן בהערה 1)."]]],[1300211204,"ולכאורה, אדרבה: די אנדערע זכירות זיינען ענינים כלליים אין דער הנהגה פון א אידן ובכל עת ובכל מקום: מעמד הר סיני — מ\"ת — איז דאך דער יסוד פון גאנץ תורה ומצותי'; שבת איז פון די מצות כלליות<sup data-n=\"12\">12</sup> און וואס איז פועל (ניט נאר אויף דעם טאג פון שבת, נאר) אויך אויף אלע ששת ימי החול<sup data-n=\"13\">13</sup>; ולאידך, מעשה העגל — היפך פון אנכי ולא יהי' לך. ועוד, וויבאלד אז „וביום פקדי ופקדתי גו'\"<sup data-n=\"14\">14</sup> — דערמאנט עס א אידן ווי מ'דארף זיין אפגעהיט אין סור מרע ס'זאל ניט קומען צו „אפקוד עליהם עונותיהם\", וואס דאס איז דאך כולל — אויך אפגעהיט אין עשה טוב; און אפילו מעשה מרים, וואס איז לכאורה אן ענין פרטי, וואס האט ניט געבראכט קיין תו־צאות פאר כלל ישראל אויף אלע דורות — איז אבער אויך אין דעם פאראן א הוראה<sup data-n=\"15\">15</sup> צו אלע אידן אויף וויפל עס דארף זיין די זהירות פון לשון הרע<sup data-n=\"16\">16</sup>, וואס איז פון די עבירות הכי חמורות, ווי חז\"ל<sup data-n=\"17\">17</sup> זאגן אז עס איז „מגדיל עונות כנגד ג' עבירות ע\"ז וג\"ע וש\"ד\". און צוזאמען דערמיט — פון די שווערסטע אויסגעהיט ווערן לגמרי פון איר<sup data-n=\"18\">18</sup>.\nמשא\"כ זכירת מעשה עמלק איז א מצוה פרטית, און זי אנטהאלט ניט, לכאורה, קיין לימוד פאר יעדן אידן בהנהגתו און — נאך א לימוד כללי<sup data-n=\"19\">19</sup>.\nב. די תמי' אין דעם איז נאך שטאר־קער:\nדער תכלית פון זכירת עמלק איז — מחיית עמלק<sup data-n=\"20\">20</sup>, ווי דער המשך הכתו־בים (נאך „זכור גו'\") — „והי'<sup data-n=\"21\">21</sup> בהניח ה\"א לך מכל אויביך גו' תמחה את זכר עמלק גו'\". און ווי דער רמב\"ם<sup data-n=\"22\">22</sup> איז דאס מסביר: „צונו לזכור מה שעשה לנו עמלק . . (ולשנוא אותו<sup data-n=\"23\">23</sup> בכל עת ועת ונעורר הנפשות במאמרים להלחם בו\".\nאון וויבאלד בזמן הזה איז ניט שייך צו מקיים זיין דעם ציווי פון מחיית עמלק בפועל — ווייל: (א) מצות מחיית עמלק איז נאר ווען אידן זיינען על אד־מתם<sup data-n=\"24\">24</sup> (און אין א מצב פון מנוחה — „בהניח ה\"א לך מכל אויביך מסביב בארץ גו'\"<sup data-n=\"21\">21</sup>); (ב) אפילו ווען ס'וואלטן",[["12","12","ועיין ס' החינוך מצוה לב: משרשי מצוה כו' כל יסודי הדת ומלבד כו' יש בו כו'."],["13","13","עיין רמב\"ן יתרו כ, ח."],["14","14","תשא לב, לד ובחז\"ל עה\"פ."],["15","15","נחוצה תמיד, כי בלא זה אין אדם ניצול מ(אבק) להי\"ר בכל יום כדלקמן בפנים."],["16","16","ראה מפרשים לתצא כד, ט. רמב\"ן ס\"פ תצא. ועוד. מג\"א ושו\"ע אדה\"ז סי' ס שם."],["17","17","ערכין טו, ב."],["18","18","דאין אדם ניצול ממנה בכ\"י (ב\"ב קסד, ב)."],["19","19","ראה חינוך שם, שזכירת מעשה עמלק אינה „עיקר בדת\" כזכירת יצי\"מ (שלכן „די לנו בזה לזכור הענין פעם א' בשנה כו'\"). ולהעיר שהרמב\"ם לא מנה מצות זכירת עמלק בין המצות ההכרחיות (בסהמ\"צ סוף המ\"ע). בחרדים (מל\"ת התלויות בארץ ישראל פ\"ב) ועוד, שזכירת עמלק ענינה לזכור „שבשביל שרפו ידיהם של ישראל מן התורה ומן המצות בא עמלק. אבל עדיין צריך ביאור: ענין זה (שע\"י רפיון במצות בא עונש על בני') מצינו כמ\"פ בתורה (כולל מעשה העגל שהוא א' מהזכירות הנ\"ל), ומהו הענין המיוחד שבזכירת עמלק דוקא? ולהעיר מצפע\"נ עה\"ת ס\"פ בשלח."],["20","20","ראה ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג מ\"ע נט (רסא, ב) שמטעם זה לא מנה הבה\"ג וסיעתו העשה דזכירת עמלק כי היא בכלל העשה דמחי'\". וראה לקמן סעיף ג."],["21","21","תצא שם, יט."],["22","22","מ\"ע קפט. וראה חינוך שם, שלכן נשים פטורות מזכירת עמלק."],["23","23","בתרגום הר\"ח העליר ור\"י קאפח: ושנאמר (את) זה."],["24","24","כמחז\"ל (סנהדרין כ, ב. ובכ\"מ. רמב\"ם ריש הל' מלכים) „ג' מצות נצטוו ישראל בכניסתן לארץ . . ולהכרית זרעו של עמלק\"."]]],[1300211205,"געווען די תנאים הנ\"ל, איז ניט מעג־לעך צו דורכפירן מחיית עמלק, ווייל „כבר עלה סנחריב ובלבל את העולם וכל דפריש מרובא פריש\"<sup data-n=\"25\">25</sup> —\nקומט אויס, אז דער ענין פון זכירת עמלק בזמן הזה איז ניט (אזוי) נוגע לפועל — און אעפ\"כ, האט מען דוקא אויף דער זכירה קובע געווען א קריאה מיוחדת ושבת מיוחדת?\nג. וועט מען דאס פארשטיין בהק־דים הביאור אין דעם עצם ענין פון מצות זכירת עמלק, דלכאורה:\nא) וויבאלד אז דער תכלית פון זכירת עמלק איז<sup data-n=\"26\">26</sup> — מחיית עמלק (כנ\"ל), פארוואס איז דא דער חיוב אויף זכירת עמלק אויך בזמן ווען ע\"פ תורה איז ניט שייך מחיית עמלק בפועל27?\nב) פארוואס דארף מען בכלל אנ־קומען צו א באזונדער ציווי28 „זכור את אשר עשה לך עמלק\" כדי צו מעורר זיין „הנפשות במאמרים להלחם בו\", און עס איז ניט גענוג דער ציווי פון „תמחה את זכר עמלק\" אליין?\n(ע\"ד ווי דער ציווי „לא תחי' כל נשמה\"<sup data-n=\"29\">29</sup> בשייכות די ז' אומות, וואס מען געפינט ניט א באזונדער ציווי צו געדענקען זייערע מעשים רעים כו'<sup data-n=\"30\">30</sup> וואס זאל ברענגען דערצו אז „נעורר הנפשות . . להלחם בהם\"<sup data-n=\"31\">31</sup>.\nאיז דערפון גופא געדרונגען, אז אע\"פ אז דער תכלית פון זכירת עמלק איז מחיית עמלק, איז אבער דא אן ענין וואס טוט זיך אויף אין זכירת עמלק פאר זיך\n— וואס דערפאר רעכנט דער רמב\"ם<sup data-n=\"32\">32</sup> (ועד\"ז אנדערע מוני המצות<sup data-n=\"33\">33</sup> מחיית עמלק און זכירת עמלק אלס צוויי באזונדערע מצות מיט באזונדערע גדרים. לדוגמא — מחיית עמלק איז פון די מצות וואס זיינען „חובה על הציבור\"<sup data-n=\"34\">34</sup> (און לויט כמה דיעות<sup data-n=\"35\">35</sup> איז דאס א מצוה אויפן מלך (פון דעם ציבור<sup data-n=\"36\">36</sup>), און די מצוה האט כמה תנאים (דוקא לאחרי כניסת בנ\"י לארץ ועוד);\nמשא\"כ זכירת עמלק איז א מצוה אויף יעדן יחיד באזונדער, און איז א מצוה תמידית<sup data-n=\"37\">37</sup>, בכל מקום ובכל זמן — און",[["25","25","מנ\"ח מצוה תרד. ולהעיר מצפע\"נ הנ\"ל."],["26","26","משא\"כ להטעם שהובא לעיל הערה 19 (ראה מלאכת שלמה למגילה פ\"ג מ\"ד)."],["27","27","ודוחק לומר שהוא רק כדי להיות מוכנים למלחמת עמלק בביאת המשיח (דאחכה לו בכל יום שיבוא). ולהעיר מספרי ורש\"י עקב יא, יז (יח)."],["28","28","ועד\"ז בבשלח (יז, יד): כתוב זאת זכרון בספר ושים באזני יהושע גו'."],["29","29","שופטים כ, טז."],["30","30","כהמשך הכתובים שם (פסוק יח) — ועד\"ז בכ\"מ — „למען אשר לא ילמדו אתכם לעשות ככל תועבתם גו'\"."],["31","31","אף שיש לחלק כי בעמלק הציווי למחות „זכר עמלק\" — „משור ועד שה\" (רש\"י ס\"פ תצא, מש\"א טו, ג (הפטורה דפ' זכור). וראה מכילתא ס\"פ בשלח. מדרש תהלים ט, ז. ועוד. לקו\"ש חי\"ד ע' 89 הערה 17) — ולכן צ\"ל זכירה מיוחדת לעורר השנאה בלב אל עמלק. וראה טעמי מצות להרדב\"ז מצוה תקצא."],["32","32","בסהמ\"צ מ\"ע קפח-קפט."],["33","33","סמ\"ג עשין קטו-קטז. ועוד."],["34","34","סהמ\"צ להרמב\"ם בסוף המ\"ע. וגם הרס\"ג מנאה במנין הפרשיות (פרשה סא). וראה חינוך מצוה תרד. ביאור הרי\"פ פערלא למ\"ע נט שם."],["35","35","רמב\"ן ובחיי ס\"פ בשלח. יראים סרצ\"ט (בהשלם — סתל\"ה). וראה לקו\"ש חט\"ז ע' 302 (הערה 31). דאולי גם להרמב\"ם מצות המלך הוא (ע\"ש). וראה הערה הבאה."],["36","36","די\"ל דמצוות המלך (שהוא — הכל) הן סוג מיוחד במצוות הציבור. ואכ\"מ."],["37","37","רמב\"ם הל' מלכים פ\"ה ה\"ה. וראה לשונו בסהמ\"צ ומנין המצות בריש ספר היד (מ\"ע קפט). וראה הדיעות שצ\"ל זכירת מעשה עמלק בכל יום —"]]],[1300211206,"דער ענין וואס ווערט אויפגעטאן דורך זכירת עמלק פאר זיך, איז אן ענין כללי אין גאנץ תורה, נאך מער ווי די אנ־דערע זכירות הנ\"ל (כדלקמן סעיף ז).\nד. דער ביאור אין דעם:\nדער ענין פון עמלק איז — „יודע את רבונו ומתכוין למרוד בו\"<sup data-n=\"38\">38</sup>. און דער־פאר, איידער א איד קען מקיים זיין מחיית עמלק — פון עמלק כפשוטו, מוז ער פריער באוואארענען, אז ביי (אין) אים אליין זאל ניט זיין „עמלק\" — „יודע את רבונו ומתכוין למרוד בו\" (אפילו ניט בדקות, כדלקמן סעיף ו).\nאון דאס איז דער תוכן פון מצות זכירת עמלק<sup data-n=\"39\">39</sup>: ס'איז ניט נאר א זכרון וואס דארף מעורר זיין צו טאן לאח\"ז און עשי' (מלחמת ומחיית עמלק כפשוטו), אדער אז דורך דעם זכרון זאל מען זיך אויסהיטן פון אן ענין בלתי רצוי (ע\"ד זכירת מעשה מרים — צו פארהיטן פון לשון הרע) — נאר זכירת עמלק גופא טוט אויף מחיית עמלק שבלב, אין אים גופא<sup data-n=\"40\">40</sup>.\nעס קען זיין ביי א אידן „עמלק\" בנפשו41, וואס וויל פועל זיין אויף אים אז ער זאל מורד זיין ח\"ו אין רבונו, און ווען דער „זכור את אשר עשה לך עמלק\" איז ביי אים כדבעי42, ווערט אויפגעטאן מחיית וביטול עמלק שב־נפשו43 — עס ווערט אויסגעוואארצלט און אויסגעמעקט יעדע נטי' פון „(יודע כו') ומתכוין למרוד בו\".\nועפ\"ז יובן וואס דוקא די זכירה האט מען פארבונדן מיט א קריאה מיוחדת בתורה — ווייל תורה איז בעה\"ב אויף מציאות העולם (ע\"ד דחז\"ל44 הידועים עה\"פ45 „לא־ל גומר עלי\"), און דער־פאר, דורך דעם וואס מ'פארבינדט זכירת עמלק מיט קריאת התורה, ווערט עס א זכרון וואס טוט אויף מחיית עמלק שבנפש46.\nה. דאס איז אויך איינער פון די בי־אורים וואס קריאת פ' זכור איז (לדעת רוב הפוסקים<sup data-n=\"47\">47</sup> א מ\"ע מן התורה:\nפון די עילוים אין מצות דאורייתא לגבי מצות דרבנן, איז וואס מצות דאו־רייתא האבן א שטארקערע פעולה אויף (און אין) וועלט; ווי באוואוסט די אריכות אין אחרונים48 וואס זיינען",[["","","הובאו באנציקלופדי' תלמודית ע' זכירת מעשה עמלק (ע' רכב)."],["38","38","כן הובא בכ\"מ (סה\"מ תקס\"ב ע' קעב. סה\"מ תקס\"ה ח\"א ע' שצה. סהמ\"צ להצ\"צ מצות זכירת מעשה עמלק פ\"א (צה, א). ובכ\"מ) על עמלק. — לשון זה מצאתי בתו\"ר בחוקותי כו, יד (הובא ברש\"י שם. נח י, ט. לך יג, יג) — אבל לא על עמלק. ובאוה\"ת פרשת זכור (ע' א'תשפו) מקשר זה עם מחז\"ל (אסת\"ר פ\"ז, יג) „מהיכן בא עמלק . . מאצל בלעם הרשע\", שבו נאמר (בלק כד, טז) „ויודע דעת עליון\"."],["39","39","ראה בכ\"ז ד\"ה זכור תרס\"ה פרק ח."],["40","40","אלא שזה גופא הוא כדי שיוכל לקיים מחיית עמלק בעולם כפשוטו, כנ\"ל סעיף ב (מסהמ\"צ להרמב\"ם)."],["41","41","ראה תו\"א תצוה סד\"ה זכור: וזרעו של עמלק פי' הזריעה שלו שזרעה בישראל להיות להם בחי' זו."],["42","42","להעיר מלקו\"ש חי\"ט (ע' 4-223) בביאור מחז\"ל (פדר\"א פמ\"ד) „האיך יתקיימו שניהם זה זכור (דעמלק) וזה זכור (דשבת)\"."],["43","43","ראה גם פנים יפות ס\"פ תצא."],["44","44","ירושלמי נדרים פ\"י ה\"ח. ועוד."],["45","45","תהלים נז, ג."],["46","46","ראה גם סה\"מ תר\"פ (ע' רצה): וע\"י הקריאה שקורא פ' מחיית עמלק בתורה מתבטל עי\"ז קליפת עמלק. וראה לקו\"ת במדבר יג, ג."],["47","47","ראה הערה 1."],["48","48","ראה שו\"ת צפע\"נ (ירושלים תשכ\"ה) סל\"ג ובהנסמן במפענח צפונות קונטרס „מאה סברות\""]]],[1300211207,"מחלק, אז איסורי דאורייתא זיינען אן איסור חפצא — די זאך ווערט א דבר מתועב כו', משא\"כ איסורי דרבנן זיינען (לויט כמה דיעות) בלויז אן איסור גברא, די חכמים לייגן ארויף אן איסור אויף דעם מענטשן, אבער ניט אויף די חפצי העולם עצמם.\n— דאס וואס מצות דרבנן האבן א מעלה אויף מצות דאורייתא, כמחז\"ל49 ערבים עלי ד\"ס יותר מד\"ת, איז עס בעיקר נוגע דעם גברא, ווייל אינעם קיום מצות שהוסיפו רבנן — דריקט זיך אויס די עריבות ותשוקה צו זיין אן עבד ה', וואס דערפאר בעט ער לכתחילה גזור עלינו גזירות50 און דערנאך בא־גנוגנט ער זיך ניט דערמיט און איז נאך מוסיף עליהן גזירות, אדער — מאכט סייג לתורה (לגזירות) כדי נאכמער פארזיכערן קיום הגזירות.\nועוד י\"ל: ביי מצות דאורייתא, ווי־באלד זיי פועל'ן אין וועלט אויף א שטארקערן אופן, איז ביי זיי ניט אזוי קענטיק אז מ'איז מקיים די מצוה בלויז מצד ציווי הקב\"ה, ווייל סגולת המצוה (וואס זי טוט אויף בעולם) איז מעלים51 אויפן קבלת עול שבקיום המצוה (וואס זי איז ציווי הקב\"ה):\nמשא\"כ אין קיום מצות דרבנן, וואו די סגולת המצוה איז ניט אזוי שטארק, דריקט זיך אויס ווי א איד איז מקיים מצות (ניט ווייל דורך דעם טוט ער אויף ענינים נעלים בעולם, נאר) ווייל ער איז אן עבד ה' וואס פאלגט דעם רצון וציווי המלך.\nאבער בנוגע דעם „חפצא\" — דאס וואס מצות דארפן אויפטאן אין וועלט52 — איז אדרבה, מצות דאורייתא האבן דעם כח התורה53 צו באווירקן די חפצא (מציאות) פון וועלט אין אן אופן וואס איז ניטא ביי מצות דרבנן, כנ\"ל.\nאון דערפאר איז קריאת פ' זכור54 א מ\"ע מן התורה, וואס דאס גיט א כח נוסף אז די זכירת עמלק זאל אויפטאן די מחיית עמלק (בנדו\"ד — שבאדם<sup data-n=\"55\">55</sup>.\nו. וויבאלד אז זכירת עמלק איז א מצוה תמידית, איז פארשטאנדיק, אז דאס איז אן ענין וואס יעדערער דארף זיך אין דעם באוואארענען תמיד, בכל הזמנים.\nוואורום אע\"פ אז עס האט ניט קיין ארט ח\"ו וח\"ו צו זאגן, אז א איד דארף זיך (תמיד) באוואארענען פון ניט זיין א „יודע את רבונו ומתכוין56 למרוד בו\";",[["","","בתחלתו. אתוון דאורייתא כלל יו\"ד. וראה תניא פ\"ח. ובארוכה שיחות אחש\"פ והתועדויות שלאח\"ז תשל\"ו."],["49","49","ראה ע\"ז לה, א וברש\"י שם. ירושלמי ברכות פ\"א ה\"ד. ועוד."],["50","50","מכילתא יתרו ב, ג (במכילתא לפנינו: אמרו לו עבדיו גזור עליהם גזירות. אבל ברמב\"ן עה\"ת יתרו (שם, ב) וכן בהשגותיו לסהמ\"צ (מל\"ת ה) ובמאירי בפתיחה לאבות (בשם המכילתא): גזור עלינו (לנו) גזירות. ו(גם) גירסא זו הובאה בדא\"ח — ד\"ה בראשית ברא תש\"ג פכ\"ו. (ועוד)."],["51","51","ע\"ד הידוע דשכל מעלים על רצון ומסנ\"פ (סה\"מ: אידיש ע' 5 ואילך. קונטרסים ח\"ג ע' קכא ואילך. תש\"ט ע' 119 ואילך)."],["52","52","שזהו ענין עיקרי בקיום המצות — עיין תניא פל\"ז-לח."],["53","53","להעיר מתו\"א (לד, ב. דרמ\"צ עד, ב) במעלת כח של דאורייתא על דרבנן, דבדאורייתא (שהיא המשכה מלמעלה למטה) „מי מעכב ומי מונע לה' ית\"ש והיד ה' תקצר\", משא\"כ בדרבנן „שהם המשכו להיות גילוי זה\"."],["54","54","נוסף לזה שזכירת עמלק בכלל היא מ\"ע מה\"ת (שבזה שווה לשאר הזכירות הנ\"ל ס\"א). ולהעיר שגם בסה\"מ תר\"פ שם מדגיש שקריאת פ' זכור היא דאורייתא."],["55","55","שפעולת המצוה בהאדם הו\"ע של „חפצא\" (שבגברא גופא)."],["56","56","להעיר מרמב\"ם הל' גירושין ספ\"ב."]]],[1300211208,"דארף ער אבער שטענדיק יע זיין באוארנט אין דעם ענין פון „עמלק\" בדקות. ובפרט אז פון דעם קען סו\"ס ארויסקומען אן ענין פון „יודע כו' ומתכוין למרוד בו\", ר\"ל.\nוהביאור: אויפן פסוק56* „כי יד על כס י\"ה מלחמה לה' בעמלק\", זאגן חז\"ל אז „אין שמו שלם כו' עד שימחה שמו של עמלק\"57 — כל זמן עמלק איז קיים איז דער שם ניט בשלימות, ס'איז בלויז י\"ה. עמלק איז מנגד אויף די אותיות ו\"ה פון שם הוי'.\nולכאורה תמוה: וויבאלד אז עמלק איז מתכוין למרוד בו, איז אין אויברשטן, איז מאי58 טעמא: א) וואס ער איז מנגד בלויז אויף שלימות השם און ניט אויפן שם בכללותו? ב) אין דעם ניגוד אויף שלימות השם — ניט אויף י\"ה שבשם, וואס איז קודם און העכער59 פון ו\"ה? ג) אדרבא — אז עס בלייבט יו\"ד ה\"א — בלייבט א גאנצער שם פון די (ז'<sup data-n=\"60\">60</sup> שמות שאינם נמחקים61?\nדער ביאור בזה62:\nדי פעולות פון די ד' אותיות פון שם הוי' אויף אן אידן און ווי זיי שטייען און זיינען בנפש האדם (אדמה לעליון63, בצלמנו<sup data-n=\"64\">64</sup> זיינען: יו\"ד ה\"א — חכמה בינה (שכל), וא\"ו — מדות שבלב ותורה, ה\"א — דבור ומעשה, מצות65.\nעיקר מלחמת עמלק איז — אויף דעם ענין פון פועל ממש. אויף מוחין אליין — בחי' י\"ה — איז ער ניט אזוי מנגד. אים ארט ניט אזוי שטארק דער יודע את רבונו אז מ'האט (נאר) א פארשטאנד אין אלקות, ער וויל אבער אז דאס זאל ניט זיין פועל אין מדות שבלב (וואס ברענגען צו) מחשבה דיבור ומעשה (בחי' ו\"ה). ואדרבה — דעמאלס איז די מרידה — א מרידה איומה ביותר; און דאס איז מודגש אינעם לשון חז\"ל „יודע את רבונו\" — ער האט א ידיעה אין רבונו — און פונדעסטוועגן „מתכוין למרוד בו\", ווייל די ידיעה האט ניט קיין ווירקונג אויף מדות און מחדו\"מ.\nאון אין דעם פרט פון עמלק — אז זיין „יודע את רבונו\" בריינגט ניט קבלת עול רבונו עכ\"פ לויט דער ידיעה (וואס קב\"ע איז מכריח תומ\"צ, און אז עס פעלט בקבלת עול רבונו — איז עס (בדקות) מרידה ברבונו) — דאס דארף זיך יעדערער באוואארענען, ווייל אין יעדערער דרגא פון עבודת וידיעת ה' קען",[["","","56*) ס\"פ בשלח."],["57","57","פרש\"י שם. תנחומא ס\"פ תצא. פסיקתא דר\"כ ופסיקתא רבתי פ' זכור. מדרש תהלים ט, ז."],["58","58","להעיר משערי אורה (לר\"י גיקטליא) ש\"ט."],["59","59","ראה ד\"ה מן המיצר תרע\"ח. ועוד."],["60","60","ראה תו\"א ס\"פ נח (וש\"נ) — הטעם דשבעה. ובפרדס (ש\"א בסופו וש\"נ) יו\"ד שמות שאינם נמחקים כו' י\"ה כו'. — הרס\"ג כותב „ששה\", רה\"ג — „תשעה\" (הובאו בס' עבודת המלך, בהערות לרמב\"ם שבהערה הבאה (ירושלים, תשכ\"ד) ועיי\"ש). — בשו\"ע אדה\"ז או\"ח ספ\"ה ס\"ג „ז' שמות שאינן נמחקין\". ולהעיר שבזח\"ג (ערב, ב) „מלכות כו' כלילא מעשר ספירן מעטרא בשבע שמהן שאינן נמחקין\". ואכ\"מ."],["61","61","ברמב\"ם הל' יסוה\"ת (פ\"ו ה\"ב) ושו\"ע יו\"ד (סרע\"ו ס\"ט) לא נמנה בו' שמות שאינן נמחקים, אבל ראה רמב\"ם שם ה\"ד (משבועות לה, ב) שהוא שם בפ\"ע ואינו נמחק, וכן בשו\"ע שם ס\"י. וראה ביאורי הגר\"א לשו\"ע שם סקי\"ט."],["62","62","ראה בכ\"ז — תו\"א ס\"פ תצוה. ד\"ה זכור בסה\"מ תקס\"ה ח\"א וביאורו. סידור שער הפורים. סהמ\"צ להצ\"צ מצות זכירת מעשה עמלק."],["63","63","עשרה מאמרות מאמר אכ\"ח ח\"ב פל\"ג ועוד. של\"ה כ, ב ובכ\"מ."],["64","64","בראשית א, כו."],["65","65","ראה בכ\"ז אגה\"ת ספ\"ד. לקו\"ת ר\"פ ראה. ובכ\"מ."]]]]});
